import { persistState, restoreState } from '../core/storage/persistence.svelte.js';
import type { Theme } from '../core/types.js';

let current = $state<Theme>('light');
let initialized = false;

const isDark = $derived(current === 'dark');
const isLight = $derived(current === 'light');

/**
 *
 * @param theme
 */
function applyTheme(theme: Theme): void {
	if (typeof document === 'undefined') return;

	document.documentElement.setAttribute('data-theme', theme);
	document.body.classList.remove('theme-light', 'theme-dark');
	document.body.classList.add(`theme-${theme}`);
}

/**
 *
 */
function persist(): void {
	if (!initialized) return;

	const state = restoreState();
	state.theme.current = current;
	persistState(state, true);
}

export const theme = {
	get current(): Theme {
		return current;
	},

	get isDark(): boolean {
		return isDark;
	},

	get isLight(): boolean {
		return isLight;
	},

	set(newTheme: Theme): void {
		if (newTheme !== 'light' && newTheme !== 'dark') {
			throw new Error(`Invalid theme: ${newTheme}. Must be 'light' or 'dark'.`);
		}

		current = newTheme;
		applyTheme(newTheme);
		persist();
	},

	toggle(): void {
		theme.set(current === 'light' ? 'dark' : 'light');
	},

	setTheme(newTheme: Theme): void {
		theme.set(newTheme);
	},

	toggleTheme(): void {
		theme.toggle();
	},

	getTheme(): Theme {
		return theme.current;
	},

	init(): void {
		if (initialized) return;

		const state = restoreState();
		current = state.theme.current;
		applyTheme(current);
		initialized = true;
	},

	_reset(): void {
		current = 'light';
		initialized = false;
	}
};

