/**
 * Dialog Manager Store
 * Manages custom Windows 98-styled message boxes and dialogs
 * Replaces native browser alert/confirm with themed dialogs
 */

interface DialogButton {
	label: string;
	value: any;
	default?: boolean;
}

interface DialogOptions {
	title: string;
	message: string;
	type: 'info' | 'error' | 'warning' | 'question';
	buttons: DialogButton[];
}

interface DialogState extends DialogOptions {
	resolver: (value: any) => void;
}

interface DialogManagerState {
	activeDialog: DialogState | null;
	queue: DialogState[];
}

// Internal state
const state = $state<DialogManagerState>({
	activeDialog: null,
	queue: []
});

/**
 * Show a dialog and return a promise that resolves when user responds
 * @param options
 */
function showDialog(options: DialogOptions): Promise<any> {
	return new Promise((resolve) => {
		const dialog: DialogState = {
			...options,
			resolver: resolve
		};

		if (state.activeDialog === null) {
			// No active dialog, show immediately
			state.activeDialog = dialog;
		} else {
			// Queue the dialog
			state.queue = [...state.queue, dialog];
		}
	});
}

/**
 * Close the active dialog with a response value
 * @param value
 */
function close(value: any): void {
	if (!state.activeDialog) return;

	// Resolve the promise
	state.activeDialog.resolver(value);

	// Show next dialog in queue or clear active dialog
	if (state.queue.length > 0) {
		state.activeDialog = state.queue[0];
		state.queue = state.queue.slice(1);
	} else {
		state.activeDialog = null;
	}
}

/**
 * Alert dialog - shows informational message with OK button
 * @param message
 * @param title
 */
async function alert(message: string, title = 'Abu OS 98'): Promise<void> {
	await showDialog({
		title,
		message,
		type: 'info',
		buttons: [{ label: 'OK', value: 'ok', default: true }]
	});
}

/**
 * Confirm dialog - shows question with Yes/No buttons
 * @param message
 * @param title
 */
async function confirm(message: string, title = 'Confirm'): Promise<boolean> {
	const result = await showDialog({
		title,
		message,
		type: 'question',
		buttons: [
			{ label: 'Yes', value: true, default: true },
			{ label: 'No', value: false }
		]
	});
	return result === true;
}

/**
 * Error dialog - shows error message with error icon and OK button
 * @param message
 * @param title
 */
async function error(message: string, title = 'Error'): Promise<void> {
	await showDialog({
		title,
		message,
		type: 'error',
		buttons: [{ label: 'OK', value: 'ok', default: true }]
	});
}

/**
 * Warning dialog - shows warning message with warning icon and OK button
 * @param message
 * @param title
 */
async function warning(message: string, title = 'Warning'): Promise<void> {
	await showDialog({
		title,
		message,
		type: 'warning',
		buttons: [{ label: 'OK', value: 'ok', default: true }]
	});
}

/**
 * Custom dialog - full control over all options
 * @param options
 */
async function show(options: DialogOptions): Promise<any> {
	return showDialog(options);
}

/**
 * Close all dialogs (useful for testing)
 */
function closeAll(): void {
	if (state.activeDialog) {
		state.activeDialog.resolver(undefined);
	}
	state.activeDialog = null;
	state.queue = [];
}

/**
 * Get current state (useful for testing)
 */
function getState(): DialogManagerState {
	return {
		activeDialog: state.activeDialog,
		queue: state.queue
	};
}

/**
 * Get active dialog (reactive)
 */
function getActiveDialog() {
	return state.activeDialog;
}

export const dialogManager = {
	alert,
	confirm,
	error,
	warning,
	show,
	close,
	closeAll,
	getState,
	get activeDialog() {
		return getActiveDialog();
	}
};

// Export types
export type { DialogButton, DialogOptions, DialogState, DialogManagerState };

