<script lang="ts">
	import type { WindowState } from '../../core/types.js';
	import { windowManager } from '../../stores/windowManager.svelte.js';
	import { pluginRegistry } from '../../plugins/pluginRegistry.js';
	import { MIN_WINDOW_WIDTH, MIN_WINDOW_HEIGHT, TITLEBAR_HEIGHT } from '../../core/constants.js';
	import { onMount } from 'svelte';
	import Scrollbar from '../controls/Scrollbar.svelte';

	interface Props {
		window: WindowState;
	}

	let { window: windowState }: Props = $props();

	let isDragging = $state(false);
	let isResizing = $state(false);
	let dragStartX = $state(0);
	let dragStartY = $state(0);
	let dragStartPos = $state({ x: 0, y: 0 });
	let resizeHandle = $state<string | null>(null);
	let resizeStartSize = $state({ width: 0, height: 0 });
	let resizeStartPos = $state({ x: 0, y: 0 });
	let factoryContainer: HTMLDivElement | null = null;
	let factoryCleanup: { destroy: () => void } | null = null;

	const plugin = $derived(pluginRegistry.get(windowState.pluginId));
	const isFactoryFunction = $derived(plugin && typeof plugin.component === 'function' && !plugin.component.prototype?.$$render);

	onMount(() => {
		if (isFactoryFunction && plugin && factoryContainer) {
			factoryCleanup = (plugin.component as any)(factoryContainer, windowState.id, () => windowManager.close(windowState.id));
		}

		return () => {
			if (factoryCleanup) {
				if (typeof factoryCleanup.destroy === 'function') {
					factoryCleanup.destroy();
				} else if (typeof factoryCleanup === 'function') {
					factoryCleanup();
				}
			}
		};
	});

	// Window style
	const style = $derived(() => {
		if (windowState.isMinimized) {
			return 'display: none;';
		}

		return `
			position: absolute;
			left: ${windowState.position.x}px;
			top: ${windowState.position.y}px;
			width: ${windowState.size.width}px;
			height: ${windowState.size.height}px;
			z-index: ${windowState.zIndex};
		`;
	});

	function handleTitlebarMouseDown(e: MouseEvent) {
		if ((e.target as HTMLElement).closest('.window-controls')) {
			return; // Don't drag when clicking window controls
		}

		if (windowState.isMaximized) {
			return; // Can't drag maximized windows
		}

		isDragging = true;
		dragStartX = e.clientX;
		dragStartY = e.clientY;
		dragStartPos = { ...windowState.position };

		windowManager.focus(windowState.id);

		e.preventDefault();
	}

	function handleMouseMove(e: MouseEvent) {
		if (isDragging) {
			const deltaX = e.clientX - dragStartX;
			const deltaY = e.clientY - dragStartY;

			const newX = dragStartPos.x + deltaX;
			const newY = Math.max(0, dragStartPos.y + deltaY);

			windowManager.move(windowState.id, { x: newX, y: newY });
		} else if (isResizing && resizeHandle) {
			handleResize(e);
		}
	}

	function handleMouseUp() {
		isDragging = false;
		isResizing = false;
		resizeHandle = null;
	}

	function handleResizeStart(e: MouseEvent, handle: string) {
		if (!windowState.isResizable || windowState.isMaximized) {
			return;
		}

		isResizing = true;
		resizeHandle = handle;
		dragStartX = e.clientX;
		dragStartY = e.clientY;
		resizeStartSize = { ...windowState.size };
		resizeStartPos = { ...windowState.position };

		windowManager.focus(windowState.id);

		e.preventDefault();
		e.stopPropagation();
	}

	function handleResize(e: MouseEvent) {
		if (!resizeHandle) return;

		const deltaX = e.clientX - dragStartX;
		const deltaY = e.clientY - dragStartY;

		let newWidth = resizeStartSize.width;
		let newHeight = resizeStartSize.height;
		let newX = resizeStartPos.x;
		let newY = resizeStartPos.y;

		// Horizontal resizing
		if (resizeHandle.includes('e')) {
			newWidth = Math.max(MIN_WINDOW_WIDTH, resizeStartSize.width + deltaX);
		} else if (resizeHandle.includes('w')) {
			const maxDelta = resizeStartSize.width - MIN_WINDOW_WIDTH;
			const constrainedDelta = Math.min(deltaX, maxDelta);
			newWidth = resizeStartSize.width - constrainedDelta;
			newX = resizeStartPos.x + constrainedDelta;
		}

		// Vertical resizing
		if (resizeHandle.includes('s')) {
			newHeight = Math.max(MIN_WINDOW_HEIGHT, resizeStartSize.height + deltaY);
		} else if (resizeHandle.includes('n')) {
			const maxDelta = resizeStartSize.height - MIN_WINDOW_HEIGHT;
			const constrainedDelta = Math.min(deltaY, maxDelta);
			newHeight = resizeStartSize.height - constrainedDelta;
			newY = resizeStartPos.y + constrainedDelta;
		}

		windowManager.resize(windowState.id, { width: newWidth, height: newHeight }, { x: newX, y: newY });
	}

	function handleMinimize() {
		windowManager.minimize(windowState.id);
	}

	function handleMaximize() {
		if (windowState.isMaximized) {
			windowManager.restore(windowState.id);
		} else {
			windowManager.maximize(windowState.id);
		}
	}

	function handleClose() {
		windowManager.close(windowState.id);
	}

	function handleWindowClick() {
		if (!windowState.isFocused) {
			windowManager.focus(windowState.id);
		}
	}

	// Global event listeners for drag and resize
	$effect(() => {
		if (isDragging || isResizing) {
			window.addEventListener('mousemove', handleMouseMove);
			window.addEventListener('mouseup', handleMouseUp);

			return () => {
				window.removeEventListener('mousemove', handleMouseMove);
				window.removeEventListener('mouseup', handleMouseUp);
			};
		}
	});
</script>

<svelte:window />

<div
	class="window"
	class:focused={windowState.isFocused}
	style={style()}
	onclick={handleWindowClick}
	role="dialog"
	aria-label={windowState.title}
>
	<div class="window-titlebar win98-titlebar" onmousedown={handleTitlebarMouseDown}>
		<div class="window-title">
			<i class="icon {windowState.iconClass} size-16"></i>
			<span class="window-title-text">{windowState.title}</span>
		</div>
		<div class="window-controls">
			<button
				type="button"
				class="window-control minimize"
				onclick={handleMinimize}
				aria-label="Minimize"
			>
				<span class="control-symbol">−</span>
			</button>
			<button
				type="button"
				class="window-control maximize"
				onclick={handleMaximize}
				aria-label={windowState.isMaximized ? 'Restore' : 'Maximize'}
			>
				<span class="control-symbol">{windowState.isMaximized ? '❐' : '□'}</span>
			</button>
			<button
				type="button"
				class="window-control close"
				onclick={handleClose}
				aria-label="Close"
			>
				<span class="control-symbol">×</span>
			</button>
		</div>
	</div>

	<div class="window-content-wrapper win98-window-content">
		<Scrollbar orientation="both">
			{#if plugin}
				{#if isFactoryFunction}
					<div bind:this={factoryContainer}></div>
				{:else}
					<svelte:component this={plugin.component} />
				{/if}
			{:else}
				<div class="window-error">Plugin not found: {windowState.pluginId}</div>
			{/if}
		</Scrollbar>
	</div>

	{#if windowState.isResizable && !windowState.isMaximized}
		<div class="resize-handle n" onmousedown={(e) => handleResizeStart(e, 'n')}></div>
		<div class="resize-handle s" onmousedown={(e) => handleResizeStart(e, 's')}></div>
		<div class="resize-handle e" onmousedown={(e) => handleResizeStart(e, 'e')}></div>
		<div class="resize-handle w" onmousedown={(e) => handleResizeStart(e, 'w')}></div>
		<div class="resize-handle ne" onmousedown={(e) => handleResizeStart(e, 'ne')}></div>
		<div class="resize-handle nw" onmousedown={(e) => handleResizeStart(e, 'nw')}></div>
		<div class="resize-handle se" onmousedown={(e) => handleResizeStart(e, 'se')}></div>
		<div class="resize-handle sw" onmousedown={(e) => handleResizeStart(e, 'sw')}></div>
	{/if}
</div>

<style>
	.window {
		background: var(--color-button-face);
		border: 2px solid;
		border-color: var(--color-button-highlight) var(--color-button-dark-shadow) var(--color-button-dark-shadow) var(--color-button-highlight);
		box-shadow: none;
		display: flex;
		flex-direction: column;
		user-select: none;
	}

	.window.focused {
		border-color: var(--color-button-highlight) var(--color-window-frame) var(--color-window-frame) var(--color-button-highlight);
	}

	.window-titlebar {
		background: linear-gradient(to right, var(--color-active-title), var(--color-active-title-gradient-end));
		color: var(--color-title-text);
		display: flex;
		justify-content: space-between;
		align-items: center;
		height: 24px;
		padding: 2px 4px;
		cursor: move;
	}

	.window.focused .window-titlebar {
		background: linear-gradient(to right, var(--color-active-title), var(--color-active-title-gradient-end));
	}

	.window:not(.focused) .window-titlebar {
		background: linear-gradient(to right, var(--color-inactive-title), var(--color-inactive-title-gradient-end));
	}

	.window-title {
		display: flex;
		align-items: center;
		gap: 4px;
		font-size: 11px;
		font-weight: bold;
	}

	.window-icon {
		width: 16px;
		height: 16px;
		background-size: contain;
	}

	.window-controls {
		display: flex;
		gap: 2px;
	}

	.window-control {
		width: 16px;
		height: 14px;
		background: var(--color-button-face);
		border: 1px outset var(--color-button-highlight);
		cursor: pointer;
		font-size: 10px;
		padding: 0;
		display: flex;
		align-items: center;
		justify-content: center;
		color: var(--color-button-text);
		font-family: 'Marlett', 'MS Sans Serif', Arial, sans-serif;
		line-height: 1;
	}
	
	.control-symbol {
		font-size: 10px;
		font-weight: bold;
		user-select: none;
	}

	.window-control:active {
		border-style: inset;
	}

	.window-control:hover {
		filter: brightness(1.1);
	}

	.window-content-wrapper {
		flex: 1;
		overflow: hidden;
		background: white;
		position: relative;
		min-height: 0; /* Important for flex child scrolling */
	}

	.window-error {
		padding: 16px;
		color: #ff0000;
		font-family: 'MS Sans Serif', Arial, sans-serif;
	}

	.resize-handle {
		position: absolute;
		background: transparent;
	}

	.resize-handle.n {
		top: -3px;
		left: 3px;
		right: 3px;
		height: 6px;
		cursor: n-resize;
	}

	.resize-handle.s {
		bottom: -3px;
		left: 3px;
		right: 3px;
		height: 6px;
		cursor: s-resize;
	}

	.resize-handle.e {
		right: -3px;
		top: 3px;
		bottom: 3px;
		width: 6px;
		cursor: e-resize;
	}

	.resize-handle.w {
		left: -3px;
		top: 3px;
		bottom: 3px;
		width: 6px;
		cursor: w-resize;
	}

	.resize-handle.ne {
		top: -3px;
		right: -3px;
		width: 10px;
		height: 10px;
		cursor: ne-resize;
	}

	.resize-handle.nw {
		top: -3px;
		left: -3px;
		width: 10px;
		height: 10px;
		cursor: nw-resize;
	}

	.resize-handle.se {
		bottom: -3px;
		right: -3px;
		width: 10px;
		height: 10px;
		cursor: se-resize;
	}

	.resize-handle.sw {
		bottom: -3px;
		left: -3px;
		width: 10px;
		height: 10px;
		cursor: sw-resize;
	}
</style>

