/**
 * Windows 98 F1 Help System - History Manager
 * 
 * This class manages help system navigation history including tracking
 * visited topics, back/forward navigation, and history persistence.
 * 
 * @fileoverview Navigation history management for help system
 */

import type {
  HistoryStats
} from './types.js';

/**
 * History manager for help system navigation
 */
export class HelpHistoryManager {
  private history: string[] = [];
  private currentIndex: number = -1;
  private readonly storageKey = 'abu-help-history';
  private readonly maxHistorySize = 1000;
  private visitCounts: Map<string, number> = new Map();
  private visitTimestamps: Map<string, Date[]> = new Map();

  /**
   * Navigate to a topic
   * 
   * @param topicId - Topic ID to navigate to
   */
  navigateTo(topicId: string): void {
    if (!topicId || typeof topicId !== 'string') {
      throw new Error('Topic ID is required and must be a string');
    }

    // Remove any history after current index (when navigating from middle of history)
    if (this.currentIndex < this.history.length - 1) {
      this.history = this.history.slice(0, this.currentIndex + 1);
    }

    // Add new topic to history
    this.history.push(topicId);
    this.currentIndex = this.history.length - 1;

    // Limit history size
    if (this.history.length > this.maxHistorySize) {
      const removedTopic = this.history.shift();
      if (removedTopic) {
        this.removeTopicFromStats(removedTopic);
      }
      this.currentIndex--;
    }

    // Update visit statistics
    this.updateVisitStats(topicId);
  }

  /**
   * Go back in history
   * 
   * @returns Previous topic ID or null if no history
   */
  goBack(): string | null {
    if (!this.canGoBack()) {
      return null;
    }

    this.currentIndex--;
    return this.history[this.currentIndex];
  }

  /**
   * Go forward in history
   * 
   * @returns Next topic ID or null if no forward history
   */
  goForward(): string | null {
    if (!this.canGoForward()) {
      return null;
    }

    this.currentIndex++;
    return this.history[this.currentIndex];
  }

  /**
   * Get navigation history
   * 
   * @returns Array of topic IDs in history
   */
  getHistory(): string[] {
    return [...this.history];
  }

  /**
   * Get current history index
   * 
   * @returns Current index in history
   */
  getCurrentIndex(): number {
    return this.currentIndex;
  }

  /**
   * Check if can go back
   * 
   * @returns True if can go back
   */
  canGoBack(): boolean {
    return this.currentIndex > 0;
  }

  /**
   * Check if can go forward
   * 
   * @returns True if can go forward
   */
  canGoForward(): boolean {
    return this.currentIndex < this.history.length - 1;
  }

  /**
   * Clear navigation history
   */
  clearHistory(): void {
    this.history = [];
    this.currentIndex = -1;
    this.visitCounts.clear();
    this.visitTimestamps.clear();
  }

  /**
   * Remove topic from history
   * 
   * @param topicId - Topic ID to remove
   */
  removeFromHistory(topicId: string): void {
    const index = this.history.indexOf(topicId);
    if (index === -1) {
      return; // Topic not in history
    }

    // Remove topic from history
    this.history.splice(index, 1);

    // Adjust current index
    if (index <= this.currentIndex) {
      this.currentIndex--;
    }

    // Remove from statistics
    this.removeTopicFromStats(topicId);
  }

  /**
   * Get history entry by index
   * 
   * @param index - History index
   * @returns Topic ID or null if index is invalid
   */
  getHistoryEntry(index: number): string | null {
    if (index < 0 || index >= this.history.length) {
      return null;
    }
    return this.history[index];
  }

  /**
   * Save history to localStorage
   */
  saveHistory(): void {
    try {
      if (typeof localStorage === 'undefined') {
        return; // No localStorage available
      }

      const historyData = {
        history: this.history,
        currentIndex: this.currentIndex,
        visitCounts: Array.from(this.visitCounts.entries()),
        visitTimestamps: Array.from(this.visitTimestamps.entries()).map(([topicId, timestamps]) => [
          topicId,
          timestamps.map(date => date.toISOString())
        ])
      };

      localStorage.setItem(this.storageKey, JSON.stringify(historyData));
    } catch (error) {
      console.warn('Failed to save history:', error);
    }
  }

  /**
   * Load history from localStorage
   */
  loadHistory(): void {
    try {
      if (typeof localStorage === 'undefined') {
        return; // No localStorage available
      }

      const serialized = localStorage.getItem(this.storageKey);
      if (!serialized) {
        return; // No saved history
      }

      const historyData = JSON.parse(serialized);
      
      if (historyData.history && Array.isArray(historyData.history)) {
        this.history = historyData.history;
        this.currentIndex = typeof historyData.currentIndex === 'number' ? historyData.currentIndex : -1;
        
        // Ensure current index is valid
        if (this.currentIndex < -1 || this.currentIndex >= this.history.length) {
          this.currentIndex = this.history.length - 1;
        }
      }

      if (historyData.visitCounts && Array.isArray(historyData.visitCounts)) {
        this.visitCounts = new Map(historyData.visitCounts);
      }

      if (historyData.visitTimestamps && Array.isArray(historyData.visitTimestamps)) {
        this.visitTimestamps = new Map(
          historyData.visitTimestamps.map(([topicId, timestamps]: [string, string[]]) => [
            topicId,
            timestamps.map(timestamp => new Date(timestamp))
          ])
        );
      }
    } catch (error) {
      console.warn('Failed to load history:', error);
      // Reset to clean state
      this.history = [];
      this.currentIndex = -1;
      this.visitCounts.clear();
      this.visitTimestamps.clear();
    }
  }

  /**
   * Get most visited topics
   * 
   * @returns Array of topic IDs sorted by visit count
   */
  getMostVisited(): string[] {
    const sortedTopics = Array.from(this.visitCounts.entries())
      .sort(([, countA], [, countB]) => countB - countA)
      .map(([topicId]) => topicId);

    return sortedTopics;
  }

  /**
   * Get recent topics
   * 
   * @param count - Number of recent topics to return
   * @returns Array of recent topic IDs
   */
  getRecentTopics(count: number = 10): string[] {
    // Get unique topics from recent history
    const recentTopics: string[] = [];
    const seen = new Set<string>();

    for (let i = this.history.length - 1; i >= 0 && recentTopics.length < count; i--) {
      const topicId = this.history[i];
      if (!seen.has(topicId)) {
        recentTopics.push(topicId);
        seen.add(topicId);
      }
    }

    return recentTopics;
  }

  /**
   * Get history statistics
   * 
   * @returns History statistics
   */
  getHistoryStats(): HistoryStats {
    const totalVisits = Array.from(this.visitCounts.values()).reduce((sum, count) => sum + count, 0);
    const uniqueTopics = this.visitCounts.size;
    
    const mostVisited = Array.from(this.visitCounts.entries())
      .sort(([, countA], [, countB]) => countB - countA)
      .slice(0, 10)
      .map(([topicId, count]) => ({ topicId, count }));

    // Calculate average session length
    let averageSessionLength = 0;
    if (this.visitTimestamps.size > 0) {
      const allTimestamps = Array.from(this.visitTimestamps.values()).flat();
      if (allTimestamps.length > 1) {
        const sortedTimestamps = allTimestamps.sort((a, b) => a.getTime() - b.getTime());
        const totalTime = sortedTimestamps[sortedTimestamps.length - 1].getTime() - sortedTimestamps[0].getTime();
        averageSessionLength = totalTime / (sortedTimestamps.length - 1);
      }
    }

    // Get last visit date
    let lastVisit: Date | null = null;
    for (const timestamps of this.visitTimestamps.values()) {
      for (const timestamp of timestamps) {
        if (!lastVisit || timestamp > lastVisit) {
          lastVisit = timestamp;
        }
      }
    }

    return {
      totalVisits,
      uniqueTopics,
      mostVisited,
      averageSessionLength,
      lastVisit: lastVisit || new Date()
    };
  }

  /**
   * Get visit count for a topic
   * 
   * @param topicId - Topic ID
   * @returns Visit count
   */
  getVisitCount(topicId: string): number {
    return this.visitCounts.get(topicId) || 0;
  }

  /**
   * Get visit timestamps for a topic
   * 
   * @param topicId - Topic ID
   * @returns Array of visit timestamps
   */
  getVisitTimestamps(topicId: string): Date[] {
    return this.visitTimestamps.get(topicId) || [];
  }

  /**
   * Get topics visited today
   * 
   * @returns Array of topic IDs visited today
   */
  getTopicsVisitedToday(): string[] {
    const today = new Date();
    today.setHours(0, 0, 0, 0);
    
    const topicsVisitedToday: string[] = [];
    
    for (const [topicId, timestamps] of this.visitTimestamps.entries()) {
      const hasVisitedToday = timestamps.some(timestamp => timestamp >= today);
      if (hasVisitedToday) {
        topicsVisitedToday.push(topicId);
      }
    }
    
    return topicsVisitedToday;
  }

  /**
   * Get topics visited this week
   * 
   * @returns Array of topic IDs visited this week
   */
  getTopicsVisitedThisWeek(): string[] {
    const weekAgo = new Date();
    weekAgo.setDate(weekAgo.getDate() - 7);
    
    const topicsVisitedThisWeek: string[] = [];
    
    for (const [topicId, timestamps] of this.visitTimestamps.entries()) {
      const hasVisitedThisWeek = timestamps.some(timestamp => timestamp >= weekAgo);
      if (hasVisitedThisWeek) {
        topicsVisitedThisWeek.push(topicId);
      }
    }
    
    return topicsVisitedThisWeek;
  }

  /**
   * Clear old history entries
   * 
   * @param daysOld - Number of days old to consider for removal
   */
  clearOldHistory(daysOld: number = 30): void {
    const cutoffDate = new Date();
    cutoffDate.setDate(cutoffDate.getDate() - daysOld);
    
    // Clear old visit timestamps
    for (const [topicId, timestamps] of this.visitTimestamps.entries()) {
      const recentTimestamps = timestamps.filter(timestamp => timestamp >= cutoffDate);
      if (recentTimestamps.length === 0) {
        this.visitTimestamps.delete(topicId);
        this.visitCounts.delete(topicId);
      } else {
        this.visitTimestamps.set(topicId, recentTimestamps);
        this.visitCounts.set(topicId, recentTimestamps.length);
      }
    }
  }

  /**
   * Update visit statistics for a topic
   * 
   * @param topicId - Topic ID
   */
  private updateVisitStats(topicId: string): void {
    // Update visit count
    const currentCount = this.visitCounts.get(topicId) || 0;
    this.visitCounts.set(topicId, currentCount + 1);

    // Update visit timestamps
    const timestamps = this.visitTimestamps.get(topicId) || [];
    timestamps.push(new Date());
    this.visitTimestamps.set(topicId, timestamps);
  }

  /**
   * Remove topic from statistics
   * 
   * @param topicId - Topic ID
   */
  private removeTopicFromStats(topicId: string): void {
    this.visitCounts.delete(topicId);
    this.visitTimestamps.delete(topicId);
  }

  /**
   * Get current topic
   * 
   * @returns Current topic ID or null if no current topic
   */
  getCurrentTopic(): string | null {
    if (this.currentIndex >= 0 && this.currentIndex < this.history.length) {
      return this.history[this.currentIndex];
    }
    return null;
  }

  /**
   * Get history length
   * 
   * @returns Number of entries in history
   */
  getHistoryLength(): number {
    return this.history.length;
  }

  /**
   * Check if history is empty
   * 
   * @returns True if history is empty
   */
  isHistoryEmpty(): boolean {
    return this.history.length === 0;
  }
}

