import { ValidationError, type StoredState } from '../types.js';
import { validateStoredState } from '../validation.js';
import { STORAGE_KEY, STORAGE_VERSION, STORAGE_TTL_DAYS } from '../constants.js';

class InMemoryStorage {
	private data = new Map<string, string>();

	getItem(key: string): string | null {
		return this.data.get(key) ?? null;
	}

	setItem(key: string, value: string): void {
		this.data.set(key, value);
	}

	removeItem(key: string): void {
		this.data.delete(key);
	}

	clear(): void {
		this.data.clear();
	}
}

let inMemoryFallback: InMemoryStorage | null = null;
let storageAvailable = false;

/**
 *
 */
function initializeStorage(): void {
	try {
		const testKey = '__abu_os_storage_test__';
		localStorage.setItem(testKey, 'test');
		localStorage.removeItem(testKey);
		storageAvailable = true;
	} catch (error) {
		console.warn('localStorage unavailable, using in-memory fallback:', error);
		inMemoryFallback = new InMemoryStorage();
		storageAvailable = false;
	}
}

initializeStorage();

/**
 *
 */
function getStorageBackend(): Storage | InMemoryStorage {
	if (inMemoryFallback) {
		return inMemoryFallback;
	}
	return localStorage;
}

/**
 *
 */
export function isStorageAvailable(): boolean {
	return storageAvailable;
}

/**
 *
 */
export function load(): StoredState | null {
	try {
		const raw = getStorageBackend().getItem(STORAGE_KEY);

		if (!raw) {
			return null;
		}

		const data = JSON.parse(raw);

		return validateStoredState(data);
	} catch (error) {
		if (error instanceof SyntaxError) {
			console.error('Failed to parse stored state (corrupted data):', error);
		} else if (error instanceof ValidationError) {
			console.warn('Stored state validation failed:', error.message);
		} else {
			console.error('Failed to load stored state:', error);
		}
		return null;
	}
}

/**
 *
 * @param state
 */
export function save(state: StoredState): boolean {
	try {
		const serialized = JSON.stringify(state);
		getStorageBackend().setItem(STORAGE_KEY, serialized);
		return true;
	} catch (error) {
		// Check for QuotaExceededError (can be DOMException or have name property)
		const isQuotaError = (error instanceof DOMException && error.name === 'QuotaExceededError') ||
			(error instanceof Error && error.name === 'QuotaExceededError');
		
		const isSecurityError = (error instanceof DOMException && error.name === 'SecurityError') ||
			(error instanceof Error && error.name === 'SecurityError');
		
		if (isQuotaError) {
			console.error('Storage quota exceeded, attempting to clear old data');
			try {
				clear();
				getStorageBackend().setItem(STORAGE_KEY, JSON.stringify(state));
				return true;
			} catch (retryError) {
				console.error('Failed to save after clearing:', retryError);
				return false;
			}
		} else if (isSecurityError) {
			console.error('Storage access denied (SecurityError):', error);
			return false;
		} else {
			console.error('Failed to save state:', error);
			return false;
		}
	}
}

/**
 *
 */
export function clear(): void {
	try {
		getStorageBackend().removeItem(STORAGE_KEY);
	} catch (error) {
		console.error('Failed to clear storage:', error);
	}
}

/**
 *
 */
export function createDefaultState(): StoredState {
	return {
		version: STORAGE_VERSION,
		timestamp: Date.now(),
		ttl: STORAGE_TTL_DAYS,
		windows: {
			open: [],
			history: []
		},
		desktop: {
			layout: 'grid',
			icons: []
		},
		theme: {
			current: 'light',
			auto: false
		},
		audio: {
			volume: 0.5,
			muted: false,
			track: null
		},
		system: {
			taskbarPosition: 'bottom',
			startMenuPinned: []
		}
	};
}

