<script lang="ts">
	import { pluginRegistry } from '../../plugins/pluginRegistry.js';
	import { windowManager } from '../../stores/windowManager.svelte.js';
	import { dialogManager } from '../../stores/dialogManager.svelte.js';

	interface MenuItem {
		id: string;
		label: string;
		iconClass?: string;
		action?: () => void;
		submenu?: MenuItem[];
		divider?: boolean;
		disabled?: boolean;
	}

	interface Props {
		show: boolean;
		onClose: () => void;
	}

	let { show = false, onClose }: Props = $props();

	const plugins = $derived(pluginRegistry.getAllPlugins());
	
	// Build Programs submenu from registered plugins
	const programsSubmenu = $derived(
		plugins.map(plugin => ({
			id: `program-${plugin.id}`,
			label: plugin.name,
			iconClass: plugin.defaultIcon,
			action: () => {
				windowManager.open(plugin.id);
				onClose();
			}
		}))
	);

	// Settings submenu
	const settingsSubmenu: MenuItem[] = [
		{
			id: 'control-panel',
			label: 'Control Panel',
			iconClass: 'icon-system-control-panel',
			action: () => {
				windowManager.open('builtin-control-panel');
				onClose();
			}
		},
	{
		id: 'printers',
		label: 'Printers',
		iconClass: 'icon-hardware-printers-printers',
		disabled: true,
			action: () => {
				dialogManager.alert('Coming soon', 'Printers');
				onClose();
			}
		},
	{
		id: 'taskbar',
		label: 'Taskbar & Start Menu',
		iconClass: 'icon-ui-misc-taskbar',
		disabled: true,
			action: () => {
				dialogManager.alert('Coming soon', 'Taskbar Settings');
				onClose();
			}
		},
	{
		id: 'folder-options',
		label: 'Folder Options...',
		iconClass: 'icon-system-directory-folder-options',
		disabled: true,
			action: () => {
				dialogManager.alert('Coming soon', 'Folder Options');
				onClose();
			}
		},
		{
			id: 'active-desktop',
			label: 'Active Desktop',
			iconClass: 'icon-system-desktop',
			disabled: true,
			action: () => {
				dialogManager.alert('Coming soon', 'Active Desktop');
				onClose();
			}
		},
	{
		id: 'windows-update',
		label: 'Windows Update',
		iconClass: 'icon-ui-misc-windows-update',
		disabled: true,
		action: () => {
			dialogManager.alert('Coming soon', 'Windows Update');
			onClose();
		}
	}
];

// Find submenu
	const findSubmenu: MenuItem[] = [
	{
		id: 'find-files',
		label: 'Files or Folders...',
		iconClass: 'icon-ui-misc-find',
		disabled: true,
			action: () => {
				dialogManager.alert('Coming soon', 'Find Files');
				onClose();
			}
		},
		{
			id: 'find-computer',
			label: 'Computer...',
			iconClass: 'icon-system-network',
			disabled: true,
			action: () => {
				dialogManager.alert('Coming soon', 'Find Computer');
				onClose();
			}
		},
		{
			id: 'find-internet',
			label: 'On the Internet...',
			iconClass: 'icon-apps-internet-internet-explorer',
			disabled: true,
			action: () => {
				dialogManager.alert('Coming soon', 'Find on Internet');
				onClose();
			}
		}
	];

	// Favorites submenu
	const favoritesSubmenu: MenuItem[] = [
	{
		id: 'fav-channels',
		label: 'Channels',
		iconClass: 'icon-ui-misc-channels',
		disabled: true,
			action: () => {
				dialogManager.alert('Coming soon', 'Channels');
				onClose();
			}
		},
	{
		id: 'fav-links',
		label: 'Links',
		iconClass: 'icon-ui-toolbar-favorites-folder',
		disabled: true,
			action: () => {
				dialogManager.alert('Coming soon', 'Links');
				onClose();
			}
		}
	];

	// Main menu structure
	const menuItems = $derived<MenuItem[]>([
	{
		id: 'windows-update-main',
		label: 'Windows Update',
		iconClass: 'icon-ui-misc-windows-update',
		disabled: true,
		action: () => {
			dialogManager.alert('Coming soon', 'Windows Update');
			onClose();
		}
	},
		{
			id: 'divider-0',
			label: '',
			divider: true
		},
	{
		id: 'programs',
		label: 'Programs',
		iconClass: 'icon-system-directory-open',
		submenu: programsSubmenu
	},
	{
		id: 'favorites',
		label: 'Favorites',
		iconClass: 'icon-ui-toolbar-favorites-folder',
		submenu: favoritesSubmenu
	},
		{
			id: 'documents',
			label: 'Documents',
			iconClass: 'icon-system-folder-closed',
			submenu: [],
			disabled: true
		},
		{
			id: 'settings',
			label: 'Settings',
			iconClass: 'icon-system-settings',
			submenu: settingsSubmenu
		},
	{
		id: 'find',
		label: 'Find',
		iconClass: 'icon-ui-misc-find',
		submenu: findSubmenu
	},
	{
		id: 'help',
		label: 'Help',
		iconClass: 'icon-ui-misc-help',
		disabled: true,
			action: () => {
				dialogManager.alert('Coming soon', 'Help & Support');
				onClose();
			}
		},
	{
		id: 'run',
		label: 'Run...',
		iconClass: 'icon-ui-misc-run',
		disabled: true,
			action: () => {
				dialogManager.alert('Coming soon', 'Run');
				onClose();
			}
		},
		{
			id: 'divider-1',
			label: '',
			divider: true
		},
	{
		id: 'logoff',
		label: 'Log Off Abu...',
		iconClass: 'icon-files-system-files-log-off',
		disabled: true,
			action: () => {
				dialogManager.alert('Coming soon', 'Log Off');
				onClose();
			}
		},
	{
		id: 'shutdown',
		label: 'Shut Down...',
		iconClass: 'icon-ui-misc-shutdown',
		action: () => {
				dialogManager.alert('Shutdown functionality not yet implemented', 'Shut Down');
				onClose();
			}
		}
	]);

	let expandedSubmenu = $state<string | null>(null);

	// Reset submenu state when menu closes
	$effect(() => {
		if (!show) {
			expandedSubmenu = null;
		}
	});

	function handleItemClick(item: MenuItem) {
		if (item.disabled) return;
		
		if (item.submenu) {
			expandedSubmenu = expandedSubmenu === item.id ? null : item.id;
		} else if (item.action) {
			item.action();
		}
	}

	function handleItemHover(item: MenuItem) {
		if (item.submenu) {
			expandedSubmenu = item.id;
		}
	}
</script>

{#if show}
	<div class="start-menu">
		<div class="start-menu-sidebar">
			<div class="start-menu-title">Abu OS 98</div>
		</div>

		<div class="start-menu-content">
			{#each menuItems as item}
				{#if item.divider}
					<div class="start-menu-divider"></div>
				{:else}
					<div class="start-menu-item-container">
						<button
							type="button"
							class="start-menu-item"
							class:disabled={item.disabled}
							class:expanded={expandedSubmenu === item.id}
							onclick={() => handleItemClick(item)}
							onmouseenter={() => handleItemHover(item)}
							disabled={item.disabled}
						>
							{#if item.iconClass}
								<i class="icon {item.iconClass} start-menu-icon"></i>
							{:else}
								<span class="start-menu-icon"></span>
							{/if}
						<span class="start-menu-label">{item.label}</span>
						{#if item.submenu}
							<span class="submenu-arrow">►</span>
						{/if}
						</button>
						
						{#if item.submenu && expandedSubmenu === item.id}
							<div class="start-menu-submenu">
								{#each item.submenu as subitem}
									<button
										type="button"
										class="start-menu-item submenu-item"
										onclick={() => subitem.action?.()}
									>
										{#if subitem.iconClass}
											<i class="icon {subitem.iconClass} start-menu-icon"></i>
										{:else}
											<span class="start-menu-icon"></span>
										{/if}
										<span class="start-menu-label">{subitem.label}</span>
									</button>
								{/each}
								
								{#if item.submenu.length === 0}
									<div class="start-menu-empty">No programs available</div>
								{/if}
							</div>
						{/if}
					</div>
				{/if}
			{/each}
		</div>
	</div>

	<!-- Backdrop to close menu when clicking outside -->
	<div class="start-menu-backdrop" onclick={onClose}></div>
{/if}

<style>
	.start-menu {
		position: fixed;
		bottom: 30px;
		left: 2px;
		width: 300px;
		background: var(--color-button-face);
		/* Windows 98 3D border effect */
		border-top: 2px solid var(--color-button-highlight);
		border-left: 2px solid var(--color-button-highlight);
		border-right: 2px solid var(--color-button-shadow);
		border-bottom: 2px solid var(--color-button-shadow);
		box-shadow: 2px 2px 5px rgba(0, 0, 0, 0.3);
		display: flex;
		z-index: 1100;
		font-family: 'MS Sans Serif', Arial, sans-serif;
		/* Disable font smoothing for authentic Windows 98 look */
		-webkit-font-smoothing: none;
		-moz-osx-font-smoothing: grayscale;
		font-smooth: never;
	}

	.start-menu-sidebar {
		width: 28px;
		background: linear-gradient(to bottom, #000080, #1084d0);
		display: flex;
		align-items: flex-end;
		padding: 8px 2px;
		flex-shrink: 0;
	}

	.start-menu-title {
		color: #ffffff;
		font-weight: bold;
		font-size: 16px;
		writing-mode: vertical-rl;
		text-orientation: mixed;
		transform: rotate(180deg);
		letter-spacing: 1px;
		line-height: 1.2;
	}

	.start-menu-content {
		flex: 1;
		display: flex;
		flex-direction: column;
		position: relative;
		padding: 2px;
	}

	.start-menu-item-container {
		position: relative;
		display: flex;
		flex-direction: column;
	}

	.start-menu-item {
		width: 100%;
		background: transparent;
		border: 1px solid transparent;
		padding: 4px 6px;
		min-height: 32px;
		display: flex;
		align-items: center;
		gap: 6px;
		cursor: pointer;
		font-size: 11px;
		text-align: left;
		position: relative;
		color: var(--color-button-text);
		/* Disable font smoothing */
		-webkit-font-smoothing: none;
		-moz-osx-font-smoothing: grayscale;
		font-smooth: never;
	}

	.start-menu-item:hover:not(.disabled) {
		background: #000080;
		color: #ffffff;
		border: 1px solid transparent;
	}

	.start-menu-item.disabled {
		color: #808080; /* Fixed medium gray for readability in both light and dark modes */
		cursor: default;
	}

	.start-menu-item.expanded {
		background: #000080;
		color: #ffffff;
	}

	.start-menu-icon {
		width: 16px;
		height: 16px;
		background-size: contain;
		flex-shrink: 0;
	}

	.start-menu-label {
		overflow: hidden;
		text-overflow: ellipsis;
		white-space: nowrap;
		flex: 1;
	}

	.submenu-arrow {
		margin-left: auto;
		font-size: 10px;
	}

	.start-menu-submenu {
		position: absolute;
		left: calc(100% - 3px);
		top: 0;
		min-width: 200px;
		background: var(--color-button-face);
		/* Windows 98 3D border effect */
		border-top: 2px solid var(--color-button-highlight);
		border-left: 2px solid var(--color-button-highlight);
		border-right: 2px solid var(--color-button-shadow);
		border-bottom: 2px solid var(--color-button-shadow);
		box-shadow: 2px 2px 5px rgba(0, 0, 0, 0.3);
		z-index: 1002;
		padding: 2px;
	}

	.submenu-item {
		width: 100%;
	}

	.start-menu-empty {
		padding: 8px;
		font-size: 11px;
		color: var(--color-button-shadow);
		font-style: italic;
	}

	.start-menu-divider {
		height: 1px;
		border-top: 1px solid var(--color-button-shadow);
		border-bottom: 1px solid var(--color-button-highlight);
		margin: 3px 4px;
	}

	.start-menu-backdrop {
		position: fixed;
		top: 0;
		left: 0;
		right: 0;
		bottom: 0;
		z-index: 999;
	}
</style>
