<!--
  Windows 98 F1 Help System - Status Bar Component
  
  This component provides the Windows 98 style status bar at the bottom
  of the help window, showing status information and page indicators.
  
  @fileoverview Status bar component for help system
-->

<script lang="ts">
  import { onMount } from 'svelte';
  import type { HelpSystemManager, HelpSystemState, HelpTopic } from '../index.js';

  // Props
  let { helpManager, currentTopic = null, systemState = null }: { helpManager: HelpSystemManager; currentTopic?: HelpTopic | null; systemState?: HelpSystemState | null } = $props();

  // State
  let statusText = $state('Ready');
  let pageIndicator = $state('');
  let isOnline = $state(true);
  let lastUpdate = new Date();

  // Update status text
  function updateStatusText() {
    if (!systemState) {
      statusText = 'Ready';
      return;
    }

    switch (systemState.activeTab) {
      case 'contents':
        statusText = 'Ready';
        break;
      case 'index':
        statusText = 'Index ready';
        break;
      case 'search':
        if (systemState.searchQuery) {
          statusText = `Search results for "${systemState.searchQuery}"`;
        } else {
          statusText = 'Enter search terms';
        }
        break;
      case 'favorites':
        statusText = `${systemState.bookmarks.length} bookmarks`;
        break;
      case 'history':
        statusText = `${systemState.history.length} history entries`;
        break;
      default:
        statusText = 'Ready';
    }
  }

  // Update page indicator
  function updatePageIndicator() {
    if (!currentTopic) {
      pageIndicator = '';
      return;
    }

    // For now, just show "1 of 1" since we don't have pagination
    // In a real implementation, this would show current page of total pages
    pageIndicator = '1 of 1';
  }

  // Update online status
  function updateOnlineStatus() {
    isOnline = navigator.onLine;
  }

  // Format last update time
  function formatLastUpdate(): string {
    return lastUpdate.toLocaleTimeString();
  }

  // Update status when state changes
  $effect(() => {
    if (systemState) {
      updateStatusText();
      updatePageIndicator();
      lastUpdate = new Date();
    }
  });

  // Update status when topic changes
  $effect(() => {
    if (currentTopic) {
      updatePageIndicator();
    }
  });

  // Initialize component
  onMount(() => {
    updateOnlineStatus();
    updateStatusText();
    updatePageIndicator();

    // Listen for online/offline events
    window.addEventListener('online', updateOnlineStatus);
    window.addEventListener('offline', updateOnlineStatus);

    // Listen for help system events
    const unsubscribeState = helpManager?.on('state:changed', () => {
      updateStatusText();
      updatePageIndicator();
      lastUpdate = new Date();
    });

    const unsubscribeTopic = helpManager?.on('topic:changed', () => {
      updatePageIndicator();
      lastUpdate = new Date();
    });

    const unsubscribeSearch = helpManager?.on('search:performed', () => {
      updateStatusText();
      lastUpdate = new Date();
    });

    // Clean up on destroy
    return () => {
      window.removeEventListener('online', updateOnlineStatus);
      window.removeEventListener('offline', updateOnlineStatus);
      unsubscribeState?.();
      unsubscribeTopic?.();
      unsubscribeSearch?.();
    };
  });
</script>

<!-- Status Bar -->
<div class="help-status-bar">
  <!-- Left Section - Status Text -->
  <div class="status-left">
    <span class="status-text">{statusText}</span>
    {#if !isOnline}
      <span class="offline-indicator" title="Offline">📴</span>
    {/if}
  </div>
  
  <!-- Right Section - Page Indicator and Time -->
  <div class="status-right">
    {#if pageIndicator}
      <span class="page-indicator">{pageIndicator}</span>
    {/if}
    <span class="time-indicator" title="Last updated: {formatLastUpdate()}">
      {formatLastUpdate()}
    </span>
  </div>
</div>

