<script lang="ts">
	import type { KernelInterface } from '../kernel/types.js';
	import Button from '../components/controls/Button.svelte';
	import TextInput from '../components/controls/TextInput.svelte';

	interface Props {
		windowId: string;
		kernel?: KernelInterface;
	}

	let { windowId, kernel }: Props = $props();

	let host = $state('');
	let port = $state('22');
	let username = $state('');
	let connected = $state(false);
	let output = $state<string[]>([]);
	let commandInput = $state('');
	let commandHistory = $state<string[]>([]);
	let historyIndex = $state(-1);

	let outputElement: HTMLDivElement;

	function handleConnect() {
		if (!host || !username) {
			addOutput('Error: Host and username are required');
			return;
		}

		addOutput(`Connecting to ${username}@${host}:${port}...`);
		
		setTimeout(() => {
			connected = true;
			addOutput('Connection established (mock mode)');
			addOutput(`Welcome to ${host}`);
			addOutput(`Last login: ${new Date().toLocaleString()}`);
			addOutput('');
			addOutput(`${username}@${host}:~$`);
		}, 500);
	}

	function handleDisconnect() {
		addOutput('');
		addOutput('Connection closed.');
		connected = false;
		commandInput = '';
	}

	function addOutput(text: string) {
		output.push(text);
		output = output;
		
		// Scroll to bottom
		setTimeout(() => {
			if (outputElement) {
				outputElement.scrollTop = outputElement.scrollHeight;
			}
		}, 0);
	}

	async function executeCommand(cmd: string) {
		if (!cmd.trim()) return;

		addOutput(`${username}@${host}:~$ ${cmd}`);
		commandHistory.push(cmd);
		historyIndex = -1;

		if (kernel) {
			try {
				const result = await kernel.executeCommand(cmd);
				if (result.stdout) {
					result.stdout.split('\n').forEach(line => addOutput(line));
				}
				if (result.stderr) {
					result.stderr.split('\n').forEach(line => addOutput(`Error: ${line}`));
				}
				if (result.exitCode !== 0) {
					addOutput(`Exit code: ${result.exitCode}`);
				}
			} catch (error) {
				addOutput(`Error: ${error}`);
			}
		} else {
			// Mock response
			addOutput(`bash: ${cmd}: command not found`);
		}

		addOutput('');
		addOutput(`${username}@${host}:~$`);
	}

	function handleCommandSubmit() {
		if (!commandInput.trim()) return;

		const cmd = commandInput;
		commandInput = '';
		executeCommand(cmd);
	}

	function handleKeyDown(e: KeyboardEvent) {
		if (e.key === 'Enter') {
			e.preventDefault();
			handleCommandSubmit();
		} else if (e.key === 'ArrowUp') {
			e.preventDefault();
			if (commandHistory.length > 0) {
				if (historyIndex === -1) {
					historyIndex = commandHistory.length - 1;
				} else if (historyIndex > 0) {
					historyIndex--;
				}
				commandInput = commandHistory[historyIndex];
			}
		} else if (e.key === 'ArrowDown') {
			e.preventDefault();
			if (historyIndex !== -1) {
				if (historyIndex < commandHistory.length - 1) {
					historyIndex++;
					commandInput = commandHistory[historyIndex];
				} else {
					historyIndex = -1;
					commandInput = '';
				}
			}
		}
	}
</script>

<div class="ssh-terminal">
	{#if !connected}
		<div class="connection-form">
			<h2 class="form-title">SSH Connection</h2>
			
			<div class="form-field">
				<label for="host">Host:</label>
				<TextInput
					id="host"
					value={host}
					placeholder="example.com"
					oninput={(v) => host = v}
				/>
			</div>

			<div class="form-field">
				<label for="port">Port:</label>
				<TextInput
					id="port"
					value={port}
					placeholder="22"
					oninput={(v) => port = v}
				/>
			</div>

			<div class="form-field">
				<label for="username">Username:</label>
				<TextInput
					id="username"
					value={username}
					placeholder="user"
					oninput={(v) => username = v}
				/>
			</div>

			<div class="form-actions">
				<Button label="Connect" onclick={handleConnect} />
			</div>

		<div class="form-note">
			<i class="icon icon-ui-misc-info"></i>
			<span>This is a mock SSH terminal. Commands will be executed through the kernel interface.</span>
		</div>
		</div>
	{:else}
		<div class="terminal-container">
			<div class="terminal-header">
				<span class="terminal-status">
					<i class="icon icon-ui-misc-info"></i>
					Connected to {host}
				</span>
				<Button label="Disconnect" onclick={handleDisconnect} />
			</div>

			<div class="terminal-output" bind:this={outputElement}>
				{#each output as line}
					<div class="output-line">{line}</div>
				{/each}
			</div>

			<div class="terminal-input-area">
				<span class="terminal-prompt">{username}@{host}:~$</span>
				<input
					type="text"
					class="terminal-input"
					bind:value={commandInput}
					onkeydown={handleKeyDown}
					placeholder="Enter command..."
					autofocus
				/>
			</div>
		</div>
	{/if}
</div>

