<script lang="ts">
	interface Props {
		checked: boolean;
		label: string;
		disabled?: boolean;
		onchange: (checked: boolean) => void;
	}

	let { checked = $bindable(), label, disabled = false, onchange }: Props = $props();

	function handleChange(event: Event) {
		if (!disabled) {
			const target = event.target as HTMLInputElement;
			checked = target.checked;
			onchange(checked);
		}
	}
</script>

<label class="win98-checkbox">
	<input
		type="checkbox"
		class="win98-checkbox__input"
		checked={checked}
		{disabled}
		onchange={handleChange}
		tabindex="0"
	/>
	<span class="win98-checkbox__box">
		{#if checked}
			<span class="win98-checkbox__checkmark">✓</span>
		{/if}
	</span>
	<span class="win98-checkbox__label">{label}</span>
</label>

