import { persistState, restoreState } from '../core/storage/persistence.svelte.js';
import { validateVolume } from '../core/validation.js';
import { VOLUME_DEFAULT } from '../core/constants.js';

let volume = $state(VOLUME_DEFAULT);
let muted = $state(false);
let playing = $state(false);
let currentTrack = $state<string | null>(null);
let initialized = false;

const effectiveVolume = $derived(muted ? 0 : volume);
const volumePercent = $derived(Math.round(volume * 100));

/**
 *
 */
function persist(): void {
	if (!initialized) return;

	const state = restoreState();
	state.audio.volume = volume;
	state.audio.muted = muted;
	state.audio.track = currentTrack;
	persistState(state);
}

export const audio = {
	get volume(): number {
		return volume;
	},

	get muted(): boolean {
		return muted;
	},

	get playing(): boolean {
		return playing;
	},

	get effectiveVolume(): number {
		return effectiveVolume;
	},

	get volumePercent(): number {
		return volumePercent;
	},

	get currentTrack(): string | null {
		return currentTrack;
	},

	setVolume(value: number): void {
		validateVolume(value);
		volume = value;
		persist();
	},

	toggleMute(): void {
		muted = !muted;
		persist();
	},

	isMuted(): boolean {
		return muted;
	},

	play(trackUrl?: string): void {
		if (trackUrl) {
			currentTrack = trackUrl;
		}
		playing = true;
	},

	pause(): void {
		playing = false;
	},

	stop(): void {
		playing = false;
		currentTrack = null;
	},

	init(): void {
		if (initialized) return;

		const state = restoreState();
		volume = state.audio.volume;
		muted = state.audio.muted;
		currentTrack = state.audio.track;
		playing = false;
		initialized = true;
	},

	_reset(): void {
		volume = VOLUME_DEFAULT;
		muted = false;
		playing = false;
		currentTrack = null;
		initialized = false;
	}
};

