<!--
  Windows 98 F1 Help System - Search Panel Component
  
  This component provides the search interface in the Search tab,
  including search input, results display, and search history.
  
  @fileoverview Search panel component for help system
-->

<script lang="ts">
  import { createEventDispatcher, onMount } from 'svelte';
  import type { HelpSystemManager, SearchResult } from '../index.js';

  // Props
  let { helpManager }: { helpManager: HelpSystemManager } = $props();

  // State
  let searchQuery = $state('');
  let searchResults: SearchResult[] = $state([]);
  let searchHistory: string[] = $state([]);
  let isSearching = $state(false);
  let error: string | null = $state(null);
  let showHistory = $state(false);

  // Event dispatcher
  const dispatch = createEventDispatcher();

  // Search input element
  let searchInput: HTMLInputElement;

  // Perform search
  async function performSearch(query: string) {
    if (!query.trim()) {
      searchResults = [];
      return;
    }

    try {
      isSearching = true;
      error = null;
      
      const results = await helpManager.search(query);
      searchResults = results;
      
    } catch (err) {
      error = `Search failed: ${err instanceof Error ? err.message : 'Unknown error'}`;
      console.error('Search error:', err);
      searchResults = [];
    } finally {
      isSearching = false;
    }
  }

  // Handle search input
  function handleSearchInput(event: Event) {
    const target = event.target as HTMLInputElement;
    searchQuery = target.value;
  }

  // Handle search submit
  function handleSearchSubmit(event: Event) {
    event.preventDefault();
    performSearch(searchQuery);
  }

  // Handle search button click
  function handleSearchClick() {
    performSearch(searchQuery);
  }

  // Handle clear search
  function handleClearSearch() {
    searchQuery = '';
    searchResults = [];
    error = null;
    searchInput?.focus();
  }

  // Handle result click
  function handleResultClick(result: SearchResult) {
    dispatch('topic-select', result.topicId);
  }

  // Handle history item click
  function handleHistoryItemClick(query: string) {
    searchQuery = query;
    performSearch(query);
    showHistory = false;
  }

  // Handle clear history
  function handleClearHistory() {
    helpManager?.clearSearchHistory();
    searchHistory = [];
  }

  // Toggle history dropdown
  function toggleHistory() {
    showHistory = !showHistory;
  }

  // Handle keyboard navigation
  function handleKeydown(event: KeyboardEvent) {
    if (event.key === 'Escape') {
      showHistory = false;
    } else if (event.key === 'ArrowDown' && showHistory && searchHistory.length > 0) {
      event.preventDefault();
      // Focus first history item
    }
  }

  // Load search history
  function loadSearchHistory() {
    searchHistory = helpManager?.getSearchHistory() || [];
  }

  // Initialize component
  onMount(() => {
    loadSearchHistory();
    searchInput?.focus();
    
    // Listen for search history changes
    const unsubscribe = helpManager?.on('search:performed', (data) => {
      loadSearchHistory();
    });
    
    return unsubscribe;
  });

  // Update search history when it changes
  $effect(() => {
    if (helpManager) {
      loadSearchHistory();
    }
  });
</script>

<svelte:window on:keydown={handleKeydown} />

<!-- Search Panel Container -->
<div class="help-search-panel">
  <!-- Search Input -->
  <div class="search-input-container">
    <form on:submit={handleSearchSubmit} class="search-form">
      <div class="search-input-group">
        <input
          bind:this={searchInput}
          type="text"
          bind:value={searchQuery}
          on:input={handleSearchInput}
          placeholder="Enter search terms..."
          class="search-input"
          autocomplete="off"
        />
        <button
          type="button"
          class="search-button"
          on:click={handleSearchClick}
          disabled={isSearching}
        >
          {isSearching ? '⏳' : '🔍'}
        </button>
        <button
          type="button"
          class="history-button"
          on:click={toggleHistory}
          title="Search History"
        >
          📋
        </button>
        <button
          type="button"
          class="clear-button"
          on:click={handleClearSearch}
          title="Clear Search"
        >
          ✕
        </button>
      </div>
    </form>
    
    <!-- Search History Dropdown -->
    {#if showHistory && searchHistory.length > 0}
      <div class="search-history">
        <div class="history-header">
          <span>Recent Searches</span>
          <button class="clear-history-button" on:click={handleClearHistory}>Clear</button>
        </div>
        <div class="history-items">
          {#each searchHistory as query}
            <button
              class="history-item"
              on:click={() => handleHistoryItemClick(query)}
            >
              {query}
            </button>
          {/each}
        </div>
      </div>
    {/if}
  </div>

  <!-- Search Results -->
  <div class="search-results">
    {#if error}
      <!-- Error State -->
      <div class="search-error">
        <p>{error}</p>
        <button on:click={() => performSearch(searchQuery)}>Retry</button>
      </div>
    {:else if isSearching}
      <!-- Loading State -->
      <div class="search-loading">
        <div class="loading-spinner"></div>
        <p>Searching...</p>
      </div>
    {:else if searchResults.length === 0 && searchQuery}
      <!-- No Results -->
      <div class="search-no-results">
        <p>No results found for "{searchQuery}"</p>
        <p>Try different keywords or check your spelling.</p>
      </div>
    {:else if searchResults.length === 0}
      <!-- Empty State -->
      <div class="search-empty">
        <p>Enter search terms above to find help topics.</p>
        <div class="search-tips">
          <h4>Search Tips:</h4>
          <ul>
            <li>Use specific keywords</li>
            <li>Try different word combinations</li>
            <li>Check your spelling</li>
            <li>Use quotes for exact phrases</li>
          </ul>
        </div>
      </div>
    {:else}
      <!-- Search Results -->
      <div class="results-list">
        <div class="results-header">
          <span>Found {searchResults.length} result{searchResults.length !== 1 ? 's' : ''}</span>
        </div>
        {#each searchResults as result}
          <div
            class="search-result"
            on:click={() => handleResultClick(result)}
            on:keydown={(e) => e.key === 'Enter' && handleResultClick(result)}
            tabindex="0"
            role="button"
          >
            <div class="result-header">
              <h3 class="result-title">{result.title}</h3>
              <span class="result-category">{result.category}</span>
            </div>
            <div class="result-snippet">{result.snippet}</div>
            <div class="result-meta">
              <span class="result-relevance">Relevance: {Math.round(result.relevance * 100)}%</span>
              {#if result.matchedTerms.length > 0}
                <span class="result-terms">Matched: {result.matchedTerms.join(', ')}</span>
              {/if}
            </div>
          </div>
        {/each}
      </div>
    {/if}
  </div>
</div>

