/**
 * Windows 98 F1 Help System - Search Engine
 * 
 * This class provides full-text search functionality for the help system,
 * including query parsing, indexing, ranking, and result highlighting.
 * 
 * @fileoverview Search engine for help system content
 */

import type {
  HelpTopic,
  SearchResult,
  SearchOptions,
  ParsedQuery,
  QueryOperator,
  SearchIndex,
  DocumentEntry,
  SearchField,
  SearchQuery,
  EnhancedSearchResult,
  SearchHighlight,
  SearchIndexStats,
  SearchConfig
} from './types.js';

/**
 * Search engine for help system content
 */
export class HelpSearchEngine {
  private searchIndex: SearchIndex = {
    terms: new Map(),
    documents: new Map(),
    lastUpdated: new Date()
  };
  private searchHistory: string[] = [];
  private readonly maxHistorySize = 20;
  private config: SearchConfig;

  constructor(config?: Partial<SearchConfig>) {
    this.config = this.createDefaultConfig(config);
  }

  /**
   * Search topics with query
   * 
   * @param query - Search query string
   * @param options - Search options
   * @returns Array of search results
   */
  search(query: string, options: SearchOptions = {}): SearchResult[] {
    if (!query || query.trim().length === 0) {
      return [];
    }

    try {
      // Add to search history
      this.addToHistory(query);

      // Parse query
      const parsedQuery = this.parseQuery(query);
      
      // Get matching documents
      const matchingDocs = this.findMatchingDocuments(parsedQuery);
      
      // Rank results
      const rankedResults = this.rankResults(matchingDocs, parsedQuery);
      
      // Apply options
      let results = rankedResults;
      
      if (options.category) {
        results = results.filter(result => result.category === options.category);
      }
      
      if (options.limit) {
        results = results.slice(0, options.limit);
      }
      
      return results;
    } catch (error) {
      throw new Error(`Search failed: ${error instanceof Error ? error.message : 'Unknown error'}`);
    }
  }

  /**
   * Build search index from topics
   * 
   * @param topics - Topics to index
   * @returns Promise that resolves when index is built
   */
  async buildSearchIndex(topics: HelpTopic[]): Promise<void> {
    try {
      // Clear existing index
      this.searchIndex.terms.clear();
      this.searchIndex.documents.clear();
      
      // Index each topic
      for (const topic of topics) {
        await this.updateSearchIndex(topic.id, topic);
      }
      
      this.searchIndex.lastUpdated = new Date();
    } catch (error) {
      throw new Error(`Failed to build search index: ${error instanceof Error ? error.message : 'Unknown error'}`);
    }
  }

  /**
   * Update search index for a specific topic
   * 
   * @param topicId - Topic ID to update
   * @param topic - Topic to index
   * @returns Promise that resolves when index is updated
   */
  async updateSearchIndex(topicId: string, topic: HelpTopic): Promise<void> {
    try {
      // Create document entry
      const document: DocumentEntry = {
        id: topicId,
        title: topic.title,
        content: topic.content,
        keywords: topic.keywords,
        category: topic.category,
        lastModified: topic.lastModified
      };
      
      this.searchIndex.documents.set(topicId, document);
      
      // Index terms from title
      const titleTerms = this.tokenize(topic.title);
      for (let i = 0; i < titleTerms.length; i++) {
        this.addTermToIndex(titleTerms[i], topicId, i, 'title');
      }
      
      // Index terms from content
      const contentTerms = this.tokenize(topic.content);
      for (let i = 0; i < contentTerms.length; i++) {
        this.addTermToIndex(contentTerms[i], topicId, i, 'content');
      }
      
      // Index keywords
      for (const keyword of topic.keywords) {
        const keywordTerms = this.tokenize(keyword);
        for (let i = 0; i < keywordTerms.length; i++) {
          this.addTermToIndex(keywordTerms[i], topicId, i, 'keywords');
        }
      }
      
      // Index category
      this.addTermToIndex(topic.category, topicId, 0, 'category');
    } catch (error) {
      throw new Error(`Failed to update search index for topic ${topicId}: ${error instanceof Error ? error.message : 'Unknown error'}`);
    }
  }

  /**
   * Tokenize text into search terms
   * 
   * @param text - Text to tokenize
   * @returns Array of normalized terms
   */
  tokenize(text: string): string[] {
    if (!text || typeof text !== 'string') {
      return [];
    }
    
    // Remove HTML tags
    const cleanText = text.replace(/<[^>]*>/g, ' ');
    
    // Split into words and normalize
    return cleanText
      .toLowerCase()
      .replace(/[^\w\s]/g, ' ')
      .split(/\s+/)
      .filter(term => term.length > 0)
      .map(term => this.normalize(term));
  }

  /**
   * Normalize search term
   * 
   * @param term - Term to normalize
   * @returns Normalized term
   */
  normalize(term: string): string {
    return term.toLowerCase().trim();
  }

  /**
   * Parse search query
   * 
   * @param query - Query string to parse
   * @returns Parsed query object
   */
  parseQuery(query: string): ParsedQuery {
    const terms: string[] = [];
    const phrases: string[] = [];
    const operators: QueryOperator[] = [];
    
    // Extract quoted phrases
    const phraseRegex = /"([^"]+)"/g;
    let match;
    while ((match = phraseRegex.exec(query)) !== null) {
      phrases.push(match[1]);
    }
    
    // Remove quoted phrases from query
    const queryWithoutPhrases = query.replace(phraseRegex, '');
    
    // Extract operators and terms
    const words = queryWithoutPhrases.split(/\s+/).filter(word => word.length > 0);
    
    for (let i = 0; i < words.length; i++) {
      const word = words[i].toLowerCase();
      
      if (word === 'and' || word === '&&') {
        operators.push({ type: 'AND', operand: '', position: i });
      } else if (word === 'or' || word === '||') {
        operators.push({ type: 'OR', operand: '', position: i });
      } else if (word === 'not' || word === '!') {
        operators.push({ type: 'NOT', operand: '', position: i });
      } else if (word.startsWith('-')) {
        operators.push({ type: 'NOT', operand: word.substring(1), position: i });
      } else {
        terms.push(this.normalize(word));
      }
    }
    
    return {
      terms,
      phrases,
      operators,
      fuzzy: false, // TODO: Implement fuzzy matching
      caseSensitive: false
    };
  }

  /**
   * Find documents matching the parsed query
   * 
   * @param parsedQuery - Parsed query object
   * @returns Array of matching document IDs with scores
   */
  private findMatchingDocuments(parsedQuery: ParsedQuery): Array<{ documentId: string; score: number }> {
    const documentScores = new Map<string, number>();
    
    // Search for terms
    for (const term of parsedQuery.terms) {
      const termEntry = this.searchIndex.terms.get(term);
      if (termEntry) {
        for (const docMatch of termEntry.documents) {
          const currentScore = documentScores.get(docMatch.documentId) || 0;
          documentScores.set(docMatch.documentId, currentScore + docMatch.frequency);
        }
      }
    }
    
    // Search for phrases
    for (const phrase of parsedQuery.phrases) {
      const phraseTerms = this.tokenize(phrase);
      for (const term of phraseTerms) {
        const termEntry = this.searchIndex.terms.get(term);
        if (termEntry) {
          for (const docMatch of termEntry.documents) {
            const currentScore = documentScores.get(docMatch.documentId) || 0;
            documentScores.set(docMatch.documentId, currentScore + docMatch.frequency * 2); // Boost phrase matches
          }
        }
      }
    }
    
    // Apply operators
    for (const operator of parsedQuery.operators) {
      if (operator.type === 'NOT' && operator.operand) {
        const termEntry = this.searchIndex.terms.get(operator.operand);
        if (termEntry) {
          for (const docMatch of termEntry.documents) {
            documentScores.delete(docMatch.documentId);
          }
        }
      }
    }
    
    // Convert to array and filter out zero scores
    return Array.from(documentScores.entries())
      .filter(([, score]) => score > 0)
      .map(([documentId, score]) => ({ documentId, score }));
  }

  /**
   * Rank search results by relevance
   * 
   * @param matchingDocs - Documents with scores
   * @param parsedQuery - Parsed query
   * @returns Ranked search results
   */
  rankResults(matchingDocs: Array<{ documentId: string; score: number }>, parsedQuery: ParsedQuery): SearchResult[] {
    const results: SearchResult[] = [];
    
    for (const { documentId, score } of matchingDocs) {
      const document = this.searchIndex.documents.get(documentId);
      if (!document) continue;
      
      // Calculate relevance score (0-1)
      const maxPossibleScore = this.calculateMaxScore(document, parsedQuery);
      const relevance = maxPossibleScore > 0 ? Math.min(score / maxPossibleScore, 1) : 0;
      
      // Create snippet
      const snippet = this.createSnippet(document.content, parsedQuery);
      
      // Get matched terms
      const matchedTerms = this.getMatchedTerms(document, parsedQuery);
      
      results.push({
        topicId: documentId,
        title: document.title,
        snippet,
        relevance,
        matchedTerms,
        category: document.category,
        lastModified: document.lastModified
      });
    }
    
    // Sort by relevance (highest first)
    return results.sort((a, b) => b.relevance - a.relevance);
  }

  /**
   * Calculate maximum possible score for a document
   * 
   * @param document - Document to calculate max score for
   * @param parsedQuery - Parsed query
   * @returns Maximum possible score
   */
  private calculateMaxScore(document: DocumentEntry, _parsedQuery: ParsedQuery): number {
    let maxScore = 0;
    
    // Title matches get higher weight
    const titleTerms = this.tokenize(document.title);
    maxScore += titleTerms.length * 3;
    
    // Content matches
    const contentTerms = this.tokenize(document.content);
    maxScore += contentTerms.length;
    
    // Keyword matches
    maxScore += document.keywords.length * 2;
    
    // Category match
    maxScore += 1;
    
    return maxScore;
  }

  /**
   * Create content snippet with highlighted matches
   * 
   * @param content - Content to create snippet from
   * @param parsedQuery - Parsed query
   * @returns Content snippet
   */
  private createSnippet(content: string, parsedQuery: ParsedQuery): string {
    // Remove HTML tags for snippet
    const cleanContent = content.replace(/<[^>]*>/g, ' ');
    
    // Find first occurrence of any search term
    const allTerms = [...parsedQuery.terms, ...parsedQuery.phrases.flatMap(p => this.tokenize(p))];
    let bestMatch = -1;
    let bestTerm = '';
    
    for (const term of allTerms) {
      const index = cleanContent.toLowerCase().indexOf(term.toLowerCase());
      if (index !== -1 && (bestMatch === -1 || index < bestMatch)) {
        bestMatch = index;
        bestTerm = term;
      }
    }
    
    if (bestMatch === -1) {
      // No match found, return beginning of content
      return cleanContent.substring(0, 200) + (cleanContent.length > 200 ? '...' : '');
    }
    
    // Create snippet around the match
    const start = Math.max(0, bestMatch - 100);
    const end = Math.min(cleanContent.length, bestMatch + bestTerm.length + 100);
    let snippet = cleanContent.substring(start, end);
    
    // Add ellipsis if needed
    if (start > 0) snippet = '...' + snippet;
    if (end < cleanContent.length) snippet = snippet + '...';
    
    return snippet;
  }

  /**
   * Get matched terms for a document
   * 
   * @param document - Document
   * @param parsedQuery - Parsed query
   * @returns Array of matched terms
   */
  private getMatchedTerms(document: DocumentEntry, parsedQuery: ParsedQuery): string[] {
    const matchedTerms: string[] = [];
    const allTerms = [...parsedQuery.terms, ...parsedQuery.phrases.flatMap(p => this.tokenize(p))];
    
    for (const term of allTerms) {
      const documentText = (document.title + ' ' + document.content + ' ' + document.keywords.join(' ')).toLowerCase();
      if (documentText.includes(term.toLowerCase())) {
        matchedTerms.push(term);
      }
    }
    
    return matchedTerms;
  }

  /**
   * Highlight matches in content
   * 
   * @param content - Content to highlight
   * @param terms - Terms to highlight
   * @returns Content with highlighted terms
   */
  highlightMatches(content: string, terms: string[]): string {
    let highlightedContent = content;
    
    for (const term of terms) {
      const regex = new RegExp(`(${term})`, 'gi');
      highlightedContent = highlightedContent.replace(regex, '<mark>$1</mark>');
    }
    
    return highlightedContent;
  }

  /**
   * Add query to search history
   * 
   * @param query - Query to add
   */
  addToHistory(query: string): void {
    if (!query || query.trim().length === 0) return;
    
    const trimmedQuery = query.trim();
    
    // Remove if already exists
    const existingIndex = this.searchHistory.indexOf(trimmedQuery);
    if (existingIndex !== -1) {
      this.searchHistory.splice(existingIndex, 1);
    }
    
    // Add to beginning
    this.searchHistory.unshift(trimmedQuery);
    
    // Limit history size
    if (this.searchHistory.length > this.maxHistorySize) {
      this.searchHistory = this.searchHistory.slice(0, this.maxHistorySize);
    }
  }

  /**
   * Get search history
   * 
   * @returns Array of recent search queries
   */
  getSearchHistory(): string[] {
    return [...this.searchHistory];
  }

  /**
   * Clear search history
   */
  clearSearchHistory(): void {
    this.searchHistory = [];
  }

  /**
   * Add term to search index
   * 
   * @param term - Term to add
   * @param documentId - Document ID
   * @param position - Position in document
   * @param field - Field where term appears
   */
  private addTermToIndex(term: string, documentId: string, position: number, field: SearchField): void {
    if (!term || term.length === 0) return;
    
    const normalizedTerm = this.normalize(term);
    if (normalizedTerm.length === 0) return;
    
    let termEntry = this.searchIndex.terms.get(normalizedTerm);
    if (!termEntry) {
      termEntry = {
        term: normalizedTerm,
        documents: [],
        frequency: 0
      };
      this.searchIndex.terms.set(normalizedTerm, termEntry);
    }
    
    // Find existing document match
    let docMatch = termEntry.documents.find(doc => doc.documentId === documentId);
    if (!docMatch) {
      docMatch = {
        documentId,
        frequency: 0,
        positions: [],
        fields: []
      };
      termEntry.documents.push(docMatch);
    }
    
    // Update document match
    docMatch.frequency++;
    docMatch.positions.push(position);
    if (!docMatch.fields.includes(field)) {
      docMatch.fields.push(field);
    }
    
    // Update term frequency
    termEntry.frequency++;
  }


  /**
   * Get the search index
   * 
   * @returns The current search index
   */
  getSearchIndex(): SearchIndex {
    return this.searchIndex;
  }

  /**
   * Check if the search index is built
   * 
   * @returns True if index is built, false otherwise
   */
  isIndexBuilt(): boolean {
    return this.searchIndex.documents.size > 0;
  }

  /**
   * Execute a parsed query
   * 
   * @param parsedQuery - The parsed query to execute
   * @returns Array of search results
   */
  executeQuery(parsedQuery: ParsedQuery): SearchResult[] {
    if (!parsedQuery || parsedQuery.terms.length === 0) {
      return [];
    }

    const matchingDocs = this.findMatchingDocuments(parsedQuery);
    return this.rankResults(matchingDocs, parsedQuery);
  }

  /**
   * Calculate relevance score for a term match
   * 
   * @param term - The search term
   * @param text - The text to search in
   * @returns Relevance score between 0 and 1
   */
  calculateRelevance(term: string, text: string): number {
    if (!term || !text) return 0;

    const normalizedTerm = this.normalize(term);
    const normalizedText = this.normalize(text);

    if (normalizedText.includes(normalizedTerm)) {
      // Exact match gets highest score
      if (normalizedText === normalizedTerm) return 1.0;
      
      // Partial match gets lower score
      const termLength = normalizedTerm.length;
      const textLength = normalizedText.length;
      return termLength / textLength;
    }

    return 0;
  }

  /**
   * Generate a snippet from content with highlighted terms
   * 
   * @param content - The content to generate snippet from
   * @param terms - Terms to highlight
   * @param maxLength - Maximum snippet length (default: 200)
   * @returns Generated snippet with highlighted terms
   */
  generateSnippet(content: string, terms: string, maxLength: number = 200): string {
    if (!content || !terms) return '';

    const normalizedTerms = this.normalize(terms).split(' ');
    const cleanContent = content.replace(/<[^>]*>/g, '').trim();
    
    if (cleanContent.length <= maxLength) {
      return this.highlightMatches(cleanContent, normalizedTerms);
    }

    // Find the best match position
    let bestMatch = -1;
    for (const term of normalizedTerms) {
      const index = cleanContent.toLowerCase().indexOf(term.toLowerCase());
      if (index !== -1 && (bestMatch === -1 || index < bestMatch)) {
        bestMatch = index;
      }
    }

    if (bestMatch === -1) {
      return cleanContent.substring(0, maxLength) + '...';
    }

    // Create snippet around the match
    const start = Math.max(0, bestMatch - Math.floor(maxLength / 2));
    const end = Math.min(cleanContent.length, start + maxLength);
    let snippet = cleanContent.substring(start, end);

    if (start > 0) snippet = '...' + snippet;
    if (end < cleanContent.length) snippet = snippet + '...';

    return this.highlightMatches(snippet, normalizedTerms);
  }

  /**
   * Search with advanced query
   * 
   * @param query - Advanced search query
   * @returns Promise that resolves with enhanced search results
   */
  async searchAdvanced(query: SearchQuery): Promise<EnhancedSearchResult[]> {
    try {
      const results = await this.search(query.terms.join(' '), query.options);
      return results.map(result => this.enhanceSearchResult(result, query));
    } catch (error) {
      throw new Error(`Advanced search failed: ${error instanceof Error ? error.message : 'Unknown error'}`);
    }
  }

  /**
   * Search by category
   * 
   * @param query - Search query
   * @param category - Category to filter by
   * @returns Promise that resolves with search results
   */
  async searchByCategory(query: string, category: string): Promise<SearchResult[]> {
    return this.search(query, { category });
  }

  /**
   * Search by tag
   * 
   * @param query - Search query
   * @param tag - Tag to filter by
   * @returns Promise that resolves with search results
   */
  async searchByTag(query: string, tag: string): Promise<SearchResult[]> {
    try {
      const results = await this.search(query);
      return results.filter(result => {
        const document = this.searchIndex.documents.get(result.topicId);
        return document && document.keywords.includes(tag);
      });
    } catch (error) {
      throw new Error(`Tag search failed: ${error instanceof Error ? error.message : 'Unknown error'}`);
    }
  }

  /**
   * Get search suggestions
   * 
   * @param query - Partial search query
   * @returns Promise that resolves with suggestions
   */
  async getSuggestions(query: string): Promise<string[]> {
    if (!query || query.length < 2) {
      return [];
    }

    try {
      const suggestions: string[] = [];
      const normalizedQuery = this.normalize(query);
      
      // Get suggestions from search history
      const historySuggestions = this.searchHistory
        .filter(historyQuery => 
          this.normalize(historyQuery).includes(normalizedQuery)
        )
        .slice(0, 5);
      
      suggestions.push(...historySuggestions);
      
      // Get suggestions from indexed terms
      const termSuggestions = Array.from(this.searchIndex.terms.keys())
        .filter(term => term.includes(normalizedQuery))
        .slice(0, 5);
      
      suggestions.push(...termSuggestions);
      
      // Remove duplicates and limit results
      const uniqueSuggestions = [...new Set(suggestions)];
      return uniqueSuggestions.slice(0, this.config.maxSuggestions);
    } catch (error) {
      console.warn('Failed to get search suggestions:', error);
      return [];
    }
  }

  /**
   * Get related topics
   * 
   * @param topicId - Topic ID to get related topics for
   * @returns Promise that resolves with related topics
   */
  async getRelatedTopics(topicId: string): Promise<SearchResult[]> {
    try {
      const document = this.searchIndex.documents.get(topicId);
      if (!document) {
        return [];
      }

      // Find topics with shared keywords
      const relatedTopics: SearchResult[] = [];
      const topicKeywords = document.keywords;
      
      for (const [docId, doc] of this.searchIndex.documents.entries()) {
        if (docId === topicId) continue;
        
        const sharedKeywords = topicKeywords.filter(keyword => 
          doc.keywords.includes(keyword)
        );
        
        if (sharedKeywords.length > 0) {
          const relevance = sharedKeywords.length / Math.max(topicKeywords.length, doc.keywords.length);
          
          relatedTopics.push({
            topicId: docId,
            title: doc.title,
            snippet: this.createSnippet(doc.content, { terms: [], phrases: [], operators: [], fuzzy: false, caseSensitive: false }),
            relevance,
            matchedTerms: sharedKeywords,
            category: doc.category,
            lastModified: doc.lastModified
          });
        }
      }
      
      return relatedTopics
        .sort((a, b) => b.relevance - a.relevance)
        .slice(0, 5);
    } catch (error) {
      throw new Error(`Failed to get related topics: ${error instanceof Error ? error.message : 'Unknown error'}`);
    }
  }

  /**
   * Get popular searches
   * 
   * @returns Promise that resolves with popular search queries
   */
  async getPopularSearches(): Promise<string[]> {
    // In a real implementation, this would track search frequency
    return this.searchHistory.slice(0, 10);
  }

  /**
   * Get search suggestions for partial query
   * 
   * @param query - Partial search query
   * @returns Array of search suggestions
   */
  getSearchSuggestions(query: string): string[] {
    if (!query || query.trim().length === 0) {
      return [];
    }

    const suggestions: string[] = [];
    const queryLower = query.toLowerCase();

    // Get suggestions from search history
    for (const historyQuery of this.searchHistory) {
      if (historyQuery.toLowerCase().includes(queryLower)) {
        suggestions.push(historyQuery);
      }
    }

    // Get suggestions from indexed terms
    for (const term of this.searchIndex.terms.keys()) {
      if (term.toLowerCase().includes(queryLower)) {
        suggestions.push(term);
      }
    }

    // Remove duplicates and limit results
    return [...new Set(suggestions)].slice(0, 10);
  }

  /**
   * Check if search index is built
   * 
   * @returns True if index is built
   */
  isIndexed(): boolean {
    return this.searchIndex.documents.size > 0;
  }

  /**
   * Remove from search index
   * 
   * @param path - Path to remove from index
   * @returns Promise that resolves when removal is complete
   */
  async removeFromIndex(path: string): Promise<void> {
    try {
      // Find document by path (assuming path maps to topic ID)
      const document = this.searchIndex.documents.get(path);
      if (!document) {
        return;
      }

      // Remove from documents
      this.searchIndex.documents.delete(path);

      // Remove from terms index
      for (const [term, termEntry] of this.searchIndex.terms.entries()) {
        termEntry.documents = termEntry.documents.filter(doc => doc.documentId !== path);
        
        // Remove term if no documents left
        if (termEntry.documents.length === 0) {
          this.searchIndex.terms.delete(term);
        }
      }

      this.searchIndex.lastUpdated = new Date();
    } catch (error) {
      throw new Error(`Failed to remove from index: ${error instanceof Error ? error.message : 'Unknown error'}`);
    }
  }

  /**
   * Clear search index
   * 
   * @returns Promise that resolves when index is cleared
   */
  async clearIndex(): Promise<void> {
    try {
      this.searchIndex.terms.clear();
      this.searchIndex.documents.clear();
      this.searchIndex.lastUpdated = new Date();
    } catch (error) {
      throw new Error(`Failed to clear index: ${error instanceof Error ? error.message : 'Unknown error'}`);
    }
  }

  /**
   * Rebuild search index
   * 
   * @returns Promise that resolves when index is rebuilt
   */
  async rebuildIndex(): Promise<void> {
    try {
      const documents = Array.from(this.searchIndex.documents.values());
      await this.clearIndex();
      
      // Rebuild index from existing documents
      for (const document of documents) {
        const topic: HelpTopic = {
          id: document.id,
          title: document.title,
          content: document.content,
          icon: 'help-icon-document',
          children: [],
          keywords: document.keywords,
          category: document.category as any,
          lastModified: document.lastModified,
          relatedTopics: []
        };
        
        await this.updateSearchIndex(document.id, topic);
      }
    } catch (error) {
      throw new Error(`Failed to rebuild index: ${error instanceof Error ? error.message : 'Unknown error'}`);
    }
  }

  /**
   * Get search index statistics
   * 
   * @returns Search index statistics
   */
  getIndexStats(): SearchIndexStats {
    const totalTerms = this.searchIndex.terms.size;
    const totalDocuments = this.searchIndex.documents.size;
    const averageTermsPerDocument = totalDocuments > 0 ? 
      Array.from(this.searchIndex.terms.values())
        .reduce((sum, term) => sum + term.documents.length, 0) / totalDocuments : 0;

    return {
      totalTerms,
      totalDocuments,
      averageTermsPerDocument,
      indexSize: this.calculateIndexSize(),
      buildTime: 0, // TODO: Track build time
      lastUpdated: this.searchIndex.lastUpdated
    };
  }

  /**
   * Set search configuration
   * 
   * @param config - Search configuration
   */
  setConfig(config: SearchConfig): void {
    this.config = { ...this.config, ...config };
  }

  /**
   * Get search configuration
   * 
   * @returns Current search configuration
   */
  getConfig(): SearchConfig {
    return { ...this.config };
  }

  /**
   * Set stop words
   * 
   * @param words - Array of stop words
   */
  setStopWords(words: string[]): void {
    this.config.stopWords = words;
  }

  /**
   * Set minimum score threshold
   * 
   * @param score - Minimum score threshold
   */
  setMinScore(score: number): void {
    this.config.minScore = score;
  }

  /**
   * Enhance search result with additional data
   * 
   * @param result - Basic search result
   * @param query - Search query
   * @returns Enhanced search result
   */
  private enhanceSearchResult(result: SearchResult, query: SearchQuery): EnhancedSearchResult {
    const highlights = this.generateHighlights(result, query);
    const snippet = this.createEnhancedSnippet(result, query);
    const matchedTerms = this.getMatchedTermsFromQuery(result, query);

    return {
      ...result,
      topic: this.createTopicFromResult(result),
      highlights,
      snippet,
      matchedTerms
    };
  }

  /**
   * Generate search highlights
   * 
   * @param result - Search result
   * @param query - Search query
   * @returns Array of search highlights
   */
  private generateHighlights(result: SearchResult, query: SearchQuery): SearchHighlight[] {
    const highlights: SearchHighlight[] = [];
    const allTerms = [...query.terms, ...query.filters.map(f => f.value)];

    for (const term of allTerms) {
      const titleIndex = result.title.toLowerCase().indexOf(term.toLowerCase());
      if (titleIndex !== -1) {
        highlights.push({
          start: titleIndex,
          end: titleIndex + term.length,
          type: 'title',
          term
        });
      }

      const contentIndex = result.snippet.toLowerCase().indexOf(term.toLowerCase());
      if (contentIndex !== -1) {
        highlights.push({
          start: contentIndex,
          end: contentIndex + term.length,
          type: 'content',
          term
        });
      }
    }

    return highlights;
  }

  /**
   * Create enhanced snippet
   * 
   * @param result - Search result
   * @param query - Search query
   * @returns Enhanced snippet
   */
  private createEnhancedSnippet(result: SearchResult, query: SearchQuery): string {
    const document = this.searchIndex.documents.get(result.topicId);
    if (!document) {
      return result.snippet;
    }

    const allTerms = [...query.terms, ...query.filters.map(f => f.value)];
    return this.generateSnippet(document.content, allTerms.join(' '), 300);
  }

  /**
   * Get matched terms from query
   * 
   * @param result - Search result
   * @param query - Search query
   * @returns Array of matched terms
   */
  private getMatchedTermsFromQuery(result: SearchResult, query: SearchQuery): string[] {
    const matchedTerms: string[] = [];
    const allTerms = [...query.terms, ...query.filters.map(f => f.value)];

    for (const term of allTerms) {
      const document = this.searchIndex.documents.get(result.topicId);
      if (document) {
        const documentText = (document.title + ' ' + document.content).toLowerCase();
        if (documentText.includes(term.toLowerCase())) {
          matchedTerms.push(term);
        }
      }
    }

    return matchedTerms;
  }

  /**
   * Create topic from search result
   * 
   * @param result - Search result
   * @returns Help topic
   */
  private createTopicFromResult(result: SearchResult): HelpTopic {
    const document = this.searchIndex.documents.get(result.topicId);
    if (!document) {
      throw new Error(`Document not found for topic ID: ${result.topicId}`);
    }

    return {
      id: document.id,
      title: document.title,
      content: document.content,
      icon: 'help-icon-document',
      children: [],
      keywords: document.keywords,
      category: document.category as any,
      lastModified: document.lastModified,
      relatedTopics: []
    };
  }

  /**
   * Calculate index size in bytes
   * 
   * @returns Index size in bytes
   */
  private calculateIndexSize(): number {
    let size = 0;
    
    // Calculate terms size
    for (const [term, termEntry] of this.searchIndex.terms.entries()) {
      size += term.length * 2; // UTF-16
      size += termEntry.documents.length * 50; // Approximate document match size
    }
    
    // Calculate documents size
    for (const [id, document] of this.searchIndex.documents.entries()) {
      size += id.length * 2;
      size += document.title.length * 2;
      size += document.content.length * 2;
      size += document.keywords.length * 20; // Approximate keyword size
    }
    
    return size;
  }

  /**
   * Create default search configuration
   * 
   * @param overrides - Configuration overrides
   * @returns Default search configuration
   */
  private createDefaultConfig(overrides?: Partial<SearchConfig>): SearchConfig {
    const defaultConfig: SearchConfig = {
      maxResults: 50,
      minScore: 0.1,
      enableFuzzy: true,
      fuzzyThreshold: 0.8,
      enableStemming: true,
      stopWords: ['the', 'a', 'an', 'and', 'or', 'but', 'in', 'on', 'at', 'to', 'for', 'of', 'with', 'by'],
      enableSuggestions: true,
      maxSuggestions: 10
    };

    return { ...defaultConfig, ...overrides };
  }
}
