<script lang="ts">
	import MenuItem from './MenuItem.svelte';

	interface MenuItemData {
		label?: string;
		icon?: string;
		shortcut?: string;
		hasSubmenu?: boolean;
		disabled?: boolean;
		type?: 'standard' | 'separator' | 'header';
		onclick?: () => void;
		submenu?: MenuItemData[];
	}

	interface Props {
		items: MenuItemData[];
		visible?: boolean;
		x?: number;
		y?: number;
		label?: string;
		onclose?: () => void;
	}

	let { 
		items = [], 
		visible = false, 
		x = 0, 
		y = 0, 
		label = 'Context menu',
		onclose
	}: Props = $props();

	// State for keyboard navigation
	let focusedIndex = $state(-1);
	let openSubmenuIndex = $state(-1);
	let submenuElement = $state<HTMLElement | null>(null);
	let menuElement = $state<HTMLElement | null>(null);

	// Get interactive items (skip separators and headers)
	const interactiveItems = $derived(() => {
		return items.map((item, index) => ({ item, index }))
			.filter(({ item }) => item.type !== 'separator' && item.type !== 'header');
	});

	// Handle outside clicks
	function handleClickOutside(event: MouseEvent) {
		if (visible && onclose) {
			// Check if click is outside the menu
			const target = event.target as HTMLElement;
			const menu = target.closest('.win98-context-menu');
			if (!menu) {
				onclose();
			}
		}
	}

	// Handle keyboard events
	function handleKeydown(event: KeyboardEvent) {
		if (!visible) return;

		switch (event.key) {
			case 'Escape':
				event.preventDefault();
				if (onclose) onclose();
				break;
			case 'ArrowDown':
				event.preventDefault();
				navigateDown();
				break;
			case 'ArrowUp':
				event.preventDefault();
				navigateUp();
				break;
			case 'ArrowRight':
				event.preventDefault();
				openSubmenu();
				break;
			case 'ArrowLeft':
				event.preventDefault();
				closeSubmenu();
				break;
			case 'Enter':
				event.preventDefault();
				activateFocusedItem();
				break;
			default:
				// First letter navigation
				if (event.key.length === 1 && !event.ctrlKey && !event.altKey && !event.metaKey) {
					event.preventDefault();
					navigateToFirstLetter(event.key.toLowerCase());
				}
				break;
		}
	}

	// Keyboard navigation functions
	function navigateDown() {
		const interactive = interactiveItems();
		if (interactive.length === 0) return;

		focusedIndex = focusedIndex < interactive.length - 1 ? focusedIndex + 1 : 0;
		updateFocus();
	}

	function navigateUp() {
		const interactive = interactiveItems();
		if (interactive.length === 0) return;

		focusedIndex = focusedIndex > 0 ? focusedIndex - 1 : interactive.length - 1;
		updateFocus();
	}

	function navigateToFirstLetter(letter: string) {
		const interactive = interactiveItems();
		const matchingIndex = interactive.findIndex(({ item }) => 
			item.label?.toLowerCase().startsWith(letter)
		);
		if (matchingIndex !== -1) {
			focusedIndex = matchingIndex;
			updateFocus();
		}
	}

	function openSubmenu() {
		const interactive = interactiveItems();
		if (focusedIndex >= 0 && focusedIndex < interactive.length) {
			const { item } = interactive[focusedIndex];
			if (item.hasSubmenu || item.submenu) {
				openSubmenuIndex = focusedIndex;
			}
		}
	}

	function closeSubmenu() {
		openSubmenuIndex = -1;
	}

	function activateFocusedItem() {
		const interactive = interactiveItems();
		if (focusedIndex >= 0 && focusedIndex < interactive.length) {
			const { item } = interactive[focusedIndex];
			handleItemClick(item);
		}
	}

	function updateFocus() {
		// Focus will be handled by MenuItem components
	}

	// Handle menu item click
	function handleItemClick(item: MenuItemData) {
		if (item.disabled) return;

		if (item.hasSubmenu || item.submenu) {
			// Don't close menu for submenu items
			return;
		}

		if (item.onclick) {
			item.onclick();
		}
		
		// Close menu for standard items
		if (onclose) {
			onclose();
		}
	}

	// Handle submenu item hover
	function handleSubmenuHover(index: number) {
		openSubmenuIndex = index;
	}

	// Handle submenu item leave
	function handleSubmenuLeave() {
		// Keep submenu open for a short delay
		setTimeout(() => {
			if (openSubmenuIndex !== -1) {
				openSubmenuIndex = -1;
			}
		}, 200);
	}

	// Position submenu
	function positionSubmenu(submenuEl: HTMLElement, parentEl: HTMLElement) {
		const parentRect = parentEl.getBoundingClientRect();
		const submenuRect = submenuEl.getBoundingClientRect();
		const viewportWidth = window.innerWidth;
		const viewportHeight = window.innerHeight;

		// Position to the right of parent
		let left = parentRect.right - 4; // 4px overlap
		let top = parentRect.top;

		// Check if would go off right edge
		if (left + submenuRect.width > viewportWidth) {
			// Flip to left side
			left = parentRect.left - submenuRect.width + 4;
		}

		// Check if would go off bottom edge
		if (top + submenuRect.height > viewportHeight) {
			top = viewportHeight - submenuRect.height;
		}

		// Check if would go off top edge
		if (top < 0) {
			top = 0;
		}

		submenuEl.style.left = `${left}px`;
		submenuEl.style.top = `${top}px`;
	}

	// Svelte action for positioning submenus
	function positionSubmenuAction(node: HTMLElement, parentItem: MenuItemData) {
		// This will be called when the submenu is mounted
		const parentElement = node.parentElement?.querySelector('.win98-menu-item') as HTMLElement;
		if (parentElement) {
			positionSubmenu(node, parentElement);
		}
	}

	// Reset state when menu closes
	$effect(() => {
		if (!visible) {
			focusedIndex = -1;
			openSubmenuIndex = -1;
		}
	});

	// Add/remove event listeners when visibility changes
	$effect(() => {
		if (visible) {
			document.addEventListener('click', handleClickOutside);
			document.addEventListener('keydown', handleKeydown);
			// Focus the menu for keyboard navigation
			if (menuElement) {
				menuElement.focus();
			}
		} else {
			document.removeEventListener('click', handleClickOutside);
			document.removeEventListener('keydown', handleKeydown);
		}

		return () => {
			document.removeEventListener('click', handleClickOutside);
			document.removeEventListener('keydown', handleKeydown);
		};
	});
</script>

<div 
	bind:this={menuElement}
	class="win98-context-menu"
	style:display={visible ? 'block' : 'none'}
	style:left="{x}px"
	style:top="{y}px"
	role="menu"
	tabindex="0"
	aria-label={label}
>
	{#each items as item, index (`${item.label || 'no-label'}-${item.type || 'no-type'}-${index}`)}
		<div 
			class="context-menu-item-container"
			role="presentation"
			onmouseenter={() => {
				if (item.hasSubmenu || item.submenu) {
					handleSubmenuHover(index);
				}
			}}
			onmouseleave={() => {
				if (item.hasSubmenu || item.submenu) {
					handleSubmenuLeave();
				}
			}}
		>
			<MenuItem
				{...item}
				onclick={() => handleItemClick(item)}
			/>
			
			{#if (item.hasSubmenu || item.submenu) && openSubmenuIndex === index}
				<div 
					bind:this={submenuElement}
					class="win98-context-menu win98-context-menu--submenu"
					role="menu"
					aria-label={`${item.label} submenu`}
					use:positionSubmenuAction={item}
				>
					{#each (item.submenu || []) as subitem}
						<MenuItem
							{...subitem}
							onclick={() => {
								if (subitem.onclick) {
									subitem.onclick();
								}
								if (onclose) {
									onclose();
								}
							}}
						/>
					{/each}
				</div>
			{/if}
		</div>
	{/each}
</div>

<style lang="scss">
	.win98-context-menu {
		/* Positioning */
		position: fixed;
		
		/* Colors */
		background: var(--context-menu-bg, #C0C0C0);
		
		/* Borders - raised bevel */
		border-top: 2px solid var(--context-menu-border-light, #FFFFFF);
		border-left: 2px solid var(--context-menu-border-light, #FFFFFF);
		border-right: 2px solid var(--context-menu-border-dark, #808080);
		border-bottom: 2px solid var(--context-menu-border-dark, #808080);
		
		/* Shadow */
		box-shadow: 2px 2px 0 rgba(0, 0, 0, 0.5);
		
		/* Dimensions */
		min-width: 150px;
		max-width: 300px;
		max-height: 400px;
		
		/* Layout */
		display: flex;
		flex-direction: column;
		
		/* Overflow */
		overflow-y: auto;
		
		/* Z-index */
		z-index: 10000;
		
		/* Hide when not visible */
		&[style*="display: none"] {
			display: none !important;
		}

		/* Submenu styling */
		&--submenu {
			z-index: 10001;
		}
	}

	.context-menu-item-container {
		position: relative;
	}
</style>

