import { load, save, createDefaultState } from './storage.js';
import { validateStoredState } from '../validation.js';
import type { StoredState } from '../types.js';
import { ValidationError } from '../types.js';
import { STORAGE_DEBOUNCE_MS } from '../constants.js';

let debounceTimer: ReturnType<typeof setTimeout> | null = null;
let pendingState: StoredState | null = null;

/**
 *
 */
export function restoreState(): StoredState {
	try {
		const stored = load();

		if (!stored) {
			return createDefaultState();
		}

		const validated = validateStoredState(stored);
		return validated;
	} catch (error) {
		if (error instanceof ValidationError) {
			console.warn('Validation failed during restore, using defaults:', error.message);
		} else {
			console.error('Unexpected error during restore:', error);
		}
		return createDefaultState();
	}
}

/**
 *
 * @param state
 * @param immediate
 */
export function persistState(state: StoredState, immediate = false): void {
	if (immediate) {
		if (debounceTimer) {
			clearTimeout(debounceTimer);
			debounceTimer = null;
		}
		pendingState = null;
		save({ ...state, timestamp: Date.now() });
		return;
	}

	if (debounceTimer) {
		clearTimeout(debounceTimer);
	}

	// Store the state for the debounced save
	pendingState = state;
	debounceTimer = setTimeout(() => {
		if (pendingState) {
			save({ ...pendingState, timestamp: Date.now() });
		}
		debounceTimer = null;
		pendingState = null;
	}, STORAGE_DEBOUNCE_MS);
}

/**
 *
 */
export function cancelPendingPersist(): void {
	if (debounceTimer) {
		clearTimeout(debounceTimer);
		debounceTimer = null;
	}
	pendingState = null;
}

/**
 *
 * @param state
 */
export function flushPendingPersist(state: StoredState): void {
	if (debounceTimer) {
		clearTimeout(debounceTimer);
		debounceTimer = null;
		save({ ...state, timestamp: Date.now() });
	}
	pendingState = null;
}

