<script lang="ts">
	import { theme } from '../stores/theme.svelte.js';
	import { audio } from '../stores/audio.svelte.js';
	import type { KernelInterface } from '../kernel/types.js';

	interface Props {
		windowId: string;
		kernel?: KernelInterface;
	}

	let { windowId, kernel }: Props = $props();

	interface SystemInfo {
		osName: string;
		version: string;
		uptime: number;
		totalMemory: number;
		usedMemory: number;
	}

	let systemInfo = $state<SystemInfo | null>(null);
	let loading = $state(true);

	$effect(() => {
		if (kernel) {
			kernel.getSystemInfo().then(info => {
				systemInfo = info;
				loading = false;
			});
		} else {
			systemInfo = {
				osName: 'Abu OS 98',
				version: '1.0.0',
				uptime: 0,
				totalMemory: 2048,
				usedMemory: 512
			};
			loading = false;
		}
	});

	function formatUptime(seconds: number): string {
		const hours = Math.floor(seconds / 3600);
		const minutes = Math.floor((seconds % 3600) / 60);
		const secs = seconds % 60;
		return `${hours}h ${minutes}m ${secs}s`;
	}
</script>

<div class="control-panel">
	<div class="panel-header">
		<i class="icon icon-system-control-panel icon-size-32"></i>
		<h1 class="panel-title">Control Panel</h1>
	</div>

	<div class="panel-section">
		<div class="section-header">
			<i class="icon icon-hardware-devices-display-properties"></i>
			<h2 class="section-title">Display</h2>
		</div>
		<div class="section-content">
			<div class="info-row">
				<span class="info-label">Current Theme:</span>
				<span class="info-value">{theme.current === 'dark' ? 'Dark Mode' : 'Light Mode'}</span>
			</div>
			<div class="info-row">
				<span class="info-label">Background:</span>
				<span class="info-value">{theme.current === 'dark' ? 'Blue Gradient' : 'Teal'}</span>
			</div>
		</div>
	</div>

	<div class="panel-section">
		<div class="section-header">
			<i class="icon icon-ui-misc-loudspeaker-wave"></i>
			<h2 class="section-title">Audio</h2>
		</div>
		<div class="section-content">
			<div class="info-row">
				<span class="info-label">Volume:</span>
				<span class="info-value">{audio.volumePercent}%</span>
			</div>
			<div class="info-row">
				<span class="info-label">Muted:</span>
				<span class="info-value">{audio.muted ? 'Yes' : 'No'}</span>
			</div>
			<div class="info-row">
				<span class="info-label">Status:</span>
				<span class="info-value">{audio.playing ? 'Playing' : 'Stopped'}</span>
			</div>
		</div>
	</div>

	<div class="panel-section">
		<div class="section-header">
			<i class="icon icon-system-computer"></i>
			<h2 class="section-title">System</h2>
		</div>
		<div class="section-content">
			{#if loading}
				<div class="loading">Loading system information...</div>
			{:else if systemInfo}
				<div class="info-row">
					<span class="info-label">Operating System:</span>
					<span class="info-value">{systemInfo.osName}</span>
				</div>
				<div class="info-row">
					<span class="info-label">Version:</span>
					<span class="info-value">{systemInfo.version}</span>
				</div>
				<div class="info-row">
					<span class="info-label">Uptime:</span>
					<span class="info-value">{formatUptime(systemInfo.uptime)}</span>
				</div>
				<div class="info-row">
					<span class="info-label">Memory:</span>
					<span class="info-value">{systemInfo.usedMemory} / {systemInfo.totalMemory} MB</span>
				</div>
				<div class="info-row">
					<span class="info-label">Memory Usage:</span>
					<div class="memory-bar">
						<div 
							class="memory-bar-fill" 
							style="width: {(systemInfo.usedMemory / systemInfo.totalMemory) * 100}%"
						></div>
					</div>
				</div>
			{/if}
		</div>
	</div>

	<div class="panel-footer">
		<i class="icon icon-ui-misc-info"></i>
		<span class="footer-text">Use Settings to change system configuration</span>
	</div>
</div>

