<!--
  Windows 98 F1 Help System - Menu Bar Component
  
  This component provides the Windows 98 style menu bar with File, Edit,
  Bookmark, Options, and Help menus.
  
  @fileoverview Menu bar component for help system
-->

<script lang="ts">
  import { createEventDispatcher } from 'svelte';
  import type { HelpSystemManager } from '../index.js';

  // Props
  let { helpManager, close = () => {} }: { helpManager: HelpSystemManager; close?: () => void } = $props();

  // State
  let activeMenu: string | null = $state(null);
  let showPrintDialog = $state(false);
  let showFontDialog = $state(false);
  let showAboutDialog = $state(false);

  // Event dispatcher
  const dispatch = createEventDispatcher();

  // Menu items
  const menuItems = [
    {
      name: 'File',
      items: [
        { label: 'New', shortcut: 'Ctrl+N', action: () => handleNew() },
        { label: 'Open...', shortcut: 'Ctrl+O', action: () => handleOpen() },
        { label: 'Print...', shortcut: 'Ctrl+P', action: () => handlePrint() },
        { label: 'Print Setup...', action: () => handlePrintSetup() },
        { label: 'Exit', shortcut: 'Alt+F4', action: () => handleExit() }
      ]
    },
    {
      name: 'Edit',
      items: [
        { label: 'Copy', shortcut: 'Ctrl+C', action: () => handleCopy() },
        { label: 'Find...', shortcut: 'Ctrl+F', action: () => handleFind() },
        { label: 'Find Next', shortcut: 'F3', action: () => handleFindNext() }
      ]
    },
    {
      name: 'Bookmark',
      items: [
        { label: 'Define...', shortcut: 'Ctrl+D', action: () => handleDefineBookmark() },
        { label: 'Go to Bookmark', action: () => handleGoToBookmark() }
      ]
    },
    {
      name: 'Options',
      items: [
        { label: 'Font...', action: () => handleFont() },
        { label: 'Keep Help on Top', action: () => handleKeepOnTop() },
        { label: 'Use System Colors', action: () => handleUseSystemColors() }
      ]
    },
    {
      name: 'Help',
      items: [
        { label: 'How to Use Help', action: () => handleHowToUseHelp() },
        { label: 'About Help', action: () => handleAboutHelp() }
      ]
    }
  ];

  // Handle menu click
  function handleMenuClick(menuName: string) {
    if (activeMenu === menuName) {
      activeMenu = null;
    } else {
      activeMenu = menuName;
    }
  }

  // Handle menu item click
  function handleMenuItemClick(action: () => void) {
    action();
    activeMenu = null;
  }

  // Handle click outside to close menu
  function handleClickOutside(event: MouseEvent) {
    if (!(event.target as HTMLElement).closest('.help-menu-bar')) {
      activeMenu = null;
    }
  }

  // File menu actions
  function handleNew() {
    // TODO: Implement new help window
    console.log('New help window');
  }

  function handleOpen() {
    // TODO: Implement open help file
    console.log('Open help file');
  }

  function handlePrint() {
    showPrintDialog = true;
  }

  function handlePrintSetup() {
    // TODO: Implement print setup
    console.log('Print setup');
  }

  function handleExit() {
    close();
  }

  // Edit menu actions
  function handleCopy() {
    // Copy current topic content to clipboard
    const currentTopic = helpManager?.getState().currentTopic;
    if (currentTopic) {
      const topic = helpManager?.getTopic(currentTopic);
      if (topic) {
        navigator.clipboard?.writeText(topic.content.replace(/<[^>]*>/g, ''));
      }
    }
  }

  function handleFind() {
    // Focus search input
    dispatch('focus-search');
  }

  function handleFindNext() {
    // TODO: Implement find next
    console.log('Find next');
  }

  // Bookmark menu actions
  function handleDefineBookmark() {
    const currentTopic = helpManager?.getState().currentTopic;
    if (currentTopic) {
      const topic = helpManager?.getTopic(currentTopic);
      if (topic) {
        helpManager?.addBookmark(currentTopic, topic.title);
      }
    }
  }

  function handleGoToBookmark() {
    // Switch to favorites tab
    helpManager?.setActiveTab('favorites');
  }

  // Options menu actions
  function handleFont() {
    showFontDialog = true;
  }

  function handleKeepOnTop() {
    // TODO: Implement keep on top
    console.log('Keep on top');
  }

  function handleUseSystemColors() {
    // TODO: Implement system colors
    console.log('Use system colors');
  }

  // Help menu actions
  function handleHowToUseHelp() {
    // TODO: Show how to use help
    console.log('How to use help');
  }

  function handleAboutHelp() {
    showAboutDialog = true;
  }

  // Handle keyboard shortcuts
  function handleKeydown(event: KeyboardEvent) {
    if (event.ctrlKey || event.altKey) {
      switch (event.key) {
        case 'n':
          if (event.ctrlKey) {
            event.preventDefault();
            handleNew();
          }
          break;
        case 'o':
          if (event.ctrlKey) {
            event.preventDefault();
            handleOpen();
          }
          break;
        case 'p':
          if (event.ctrlKey) {
            event.preventDefault();
            handlePrint();
          }
          break;
        case 'c':
          if (event.ctrlKey) {
            event.preventDefault();
            handleCopy();
          }
          break;
        case 'f':
          if (event.ctrlKey) {
            event.preventDefault();
            handleFind();
          }
          break;
        case 'd':
          if (event.ctrlKey) {
            event.preventDefault();
            handleDefineBookmark();
          }
          break;
        case 'F4':
          if (event.altKey) {
            event.preventDefault();
            handleExit();
          }
          break;
      }
    } else if (event.key === 'F3') {
      event.preventDefault();
      handleFindNext();
    }
  }
</script>

<svelte:window on:click={handleClickOutside} on:keydown={handleKeydown} />

<!-- Menu Bar -->
<div class="help-menu-bar">
  {#each menuItems as menu}
    <div class="menu-item" class:active={activeMenu === menu.name}>
      <button 
        class="menu-button"
        on:click={() => handleMenuClick(menu.name)}
        on:keydown={(e) => e.key === 'Enter' && handleMenuClick(menu.name)}
      >
        {menu.name}
      </button>
      
      {#if activeMenu === menu.name}
        <div class="menu-dropdown">
          {#each menu.items as item}
            <button 
              class="menu-dropdown-item"
              on:click={() => handleMenuItemClick(item.action)}
              on:keydown={(e) => e.key === 'Enter' && handleMenuItemClick(item.action)}
            >
              <span class="menu-label">{item.label}</span>
              {#if item.shortcut}
                <span class="menu-shortcut">{item.shortcut}</span>
              {/if}
            </button>
          {/each}
        </div>
      {/if}
    </div>
  {/each}
</div>

<!-- Print Dialog -->
{#if showPrintDialog}
  <div class="help-dialog-overlay" on:click={() => showPrintDialog = false}>
    <div class="help-dialog" on:click|stopPropagation>
      <div class="dialog-header">
        <h3>Print</h3>
        <button class="dialog-close" on:click={() => showPrintDialog = false}>×</button>
      </div>
      <div class="dialog-content">
        <p>Print functionality would be implemented here.</p>
        <div class="dialog-buttons">
          <button class="dialog-button primary" on:click={() => showPrintDialog = false}>OK</button>
          <button class="dialog-button" on:click={() => showPrintDialog = false}>Cancel</button>
        </div>
      </div>
    </div>
  </div>
{/if}

<!-- Font Dialog -->
{#if showFontDialog}
  <div class="help-dialog-overlay" on:click={() => showFontDialog = false}>
    <div class="help-dialog" on:click|stopPropagation>
      <div class="dialog-header">
        <h3>Font</h3>
        <button class="dialog-close" on:click={() => showFontDialog = false}>×</button>
      </div>
      <div class="dialog-content">
        <p>Font selection would be implemented here.</p>
        <div class="dialog-buttons">
          <button class="dialog-button primary" on:click={() => showFontDialog = false}>OK</button>
          <button class="dialog-button" on:click={() => showFontDialog = false}>Cancel</button>
        </div>
      </div>
    </div>
  </div>
{/if}

<!-- About Dialog -->
{#if showAboutDialog}
  <div class="help-dialog-overlay" on:click={() => showAboutDialog = false}>
    <div class="help-dialog" on:click|stopPropagation>
      <div class="dialog-header">
        <h3>About Help</h3>
        <button class="dialog-close" on:click={() => showAboutDialog = false}>×</button>
      </div>
      <div class="dialog-content">
        <div class="about-content">
          <h4>Windows 98 F1 Help System</h4>
          <p>Version 1.0.0</p>
          <p>Part of the Abu OS 98 Web Kernel</p>
          <p>© 2024 Abu OS 98 Project</p>
        </div>
        <div class="dialog-buttons">
          <button class="dialog-button primary" on:click={() => showAboutDialog = false}>OK</button>
        </div>
      </div>
    </div>
  </div>
{/if}

