<!--
  Windows 98 F1 Help System - Tree Node Component
  
  This is a recursive component for rendering individual tree nodes in the topic tree.
  
  @fileoverview Tree node component for help system
-->

<script lang="ts">
  import type { HelpTopic } from '../types.js';

  // Props
  let {
    topic,
    currentTopic = null,
    expandedNodes,
    isExpanded,
    hasChildren,
    toggleNode,
    handleTopicClick,
    handleTopicKeydown,
    getNodeIcon,
    level = 0
  }: {
    topic: HelpTopic;
    currentTopic?: HelpTopic | null;
    expandedNodes: Set<string>;
    isExpanded: (nodeId: string) => boolean;
    hasChildren: (node: HelpTopic) => boolean;
    toggleNode: (nodeId: string) => void;
    handleTopicClick: (topic: HelpTopic) => void;
    handleTopicKeydown: (event: KeyboardEvent, topic: HelpTopic) => void;
    getNodeIcon: (topic: HelpTopic) => string;
    level?: number;
  } = $props();
</script>

<div class="tree-node" class:current={currentTopic?.id === topic.id}>
  <div 
    class="node-content"
    class:has-children={hasChildren(topic)}
    class:expanded={isExpanded(topic.id)}
    style="padding-left: {level * 16 + 4}px;"
  >
    <!-- Expand/Collapse Button -->
    {#if hasChildren(topic)}
      <button
        class="expand-button"
        onclick={() => toggleNode(topic.id)}
        title={isExpanded(topic.id) ? 'Collapse' : 'Expand'}
      >
        {isExpanded(topic.id) ? '▼' : '▶'}
      </button>
    {:else}
      <span class="expand-spacer"></span>
    {/if}

    <!-- Node Icon -->
    <span class="node-icon">{getNodeIcon(topic)}</span>

    <!-- Node Label -->
    <button
      class="node-label"
      onclick={() => handleTopicClick(topic)}
      onkeydown={(e) => handleTopicKeydown(e, topic)}
      title={topic.title}
    >
      {topic.title}
    </button>
  </div>

  <!-- Children -->
  {#if hasChildren(topic) && isExpanded(topic.id)}
    <div class="node-children">
      {#each topic.children as child}
        <TreeNode 
          topic={child} 
          {currentTopic}
          {expandedNodes}
          {isExpanded}
          {hasChildren}
          {toggleNode}
          {handleTopicClick}
          {handleTopicKeydown}
          {getNodeIcon}
          level={level + 1}
        />
      {/each}
    </div>
  {/if}
</div>

<style>
  .tree-node {
    user-select: none;
  }

  .tree-node.current .node-content {
    background: #a6caf0;
  }

  .node-content {
    display: flex;
    align-items: center;
    gap: 2px;
    padding: 1px 4px;
    cursor: pointer;
    font-size: 11px;
    font-family: 'MS Sans Serif', sans-serif;
  }

  .node-content:hover {
    background: #e0e0e0;
  }

  .expand-button {
    width: 12px;
    height: 12px;
    border: none;
    background: transparent;
    color: black;
    cursor: pointer;
    font-size: 8px;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 0;
  }

  .expand-button:hover {
    background: #d0d0d0;
  }

  .expand-spacer {
    width: 12px;
    height: 12px;
  }

  .node-icon {
    font-size: 12px;
    line-height: 1;
    width: 16px;
    text-align: center;
  }

  .node-label {
    flex: 1;
    border: none;
    background: transparent;
    color: black;
    cursor: pointer;
    font-size: 11px;
    font-family: 'MS Sans Serif', sans-serif;
    text-align: left;
    padding: 0;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
  }

  .node-label:hover {
    color: #0a246a;
  }

  .node-label:focus {
    outline: 1px dotted #000;
  }

  .node-children {
    /* Children are rendered with increased padding-left via inline style */
  }
</style>
