<!--
  Windows 98 F1 Help System - Menu Bar Component
  
  This component provides the main menu bar with File, Edit, View, Go, and Help menus
  following Windows 98 menu conventions.
  
  @fileoverview Menu bar component for help system
-->

<script lang="ts">
  import { createEventDispatcher } from 'svelte';
  import type { 
    HelpSystemManager, 
    HelpTopic,
    UserPreferences
  } from '../types.js';

  // Props
  let { 
    helpSystem,
    currentTopic = $bindable(null)
  }: {
    helpSystem: HelpSystemManager;
    currentTopic?: HelpTopic | null;
  } = $props();

  // State
  let activeMenu: string | null = null;
  let showAboutDialog = false;
  let showPreferencesDialog = false;
  let showPrintDialog = false;

  // Event dispatcher
  const dispatch = createEventDispatcher();

  // Menu items
  const fileMenuItems = [
    { id: 'new', label: 'New', shortcut: 'Ctrl+N', disabled: true },
    { id: 'open', label: 'Open...', shortcut: 'Ctrl+O', disabled: true },
    { id: 'separator1', type: 'separator' },
    { id: 'print', label: 'Print...', shortcut: 'Ctrl+P', action: () => showPrintDialog = true },
    { id: 'separator2', type: 'separator' },
    { id: 'exit', label: 'Exit', shortcut: 'Alt+F4', action: () => dispatch('close') }
  ];

  const editMenuItems = [
    { id: 'copy', label: 'Copy', shortcut: 'Ctrl+C', disabled: true },
    { id: 'select-all', label: 'Select All', shortcut: 'Ctrl+A', disabled: true },
    { id: 'separator1', type: 'separator' },
    { id: 'find', label: 'Find...', shortcut: 'Ctrl+F', action: () => dispatch('search', { query: '' }) }
  ];

  const viewMenuItems = [
    { id: 'toolbar', label: 'Toolbar', checked: true, action: () => toggleToolbar() },
    { id: 'status-bar', label: 'Status Bar', checked: true, action: () => toggleStatusBar() },
    { id: 'separator1', type: 'separator' },
    { id: 'font-size', label: 'Font Size', submenu: [
      { id: 'small', label: 'Small', action: () => setFontSize('small') },
      { id: 'medium', label: 'Medium', checked: true, action: () => setFontSize('medium') },
      { id: 'large', label: 'Large', action: () => setFontSize('large') }
    ]},
    { id: 'separator2', type: 'separator' },
    { id: 'refresh', label: 'Refresh', shortcut: 'F5', action: () => refresh() }
  ];

  const goMenuItems = [
    { id: 'back', label: 'Back', shortcut: 'Alt+Left', disabled: !helpSystem?.canGoBack(), action: () => dispatch('go-back') },
    { id: 'forward', label: 'Forward', shortcut: 'Alt+Right', disabled: !helpSystem?.canGoForward(), action: () => dispatch('go-forward') },
    { id: 'home', label: 'Home', shortcut: 'Alt+Home', action: () => dispatch('go-home') },
    { id: 'separator1', type: 'separator' },
    { id: 'bookmark', label: 'Add Bookmark', shortcut: 'Ctrl+D', disabled: !currentTopic, action: () => addBookmark() }
  ];

  const helpMenuItems = [
    { id: 'contents', label: 'Help Topics', shortcut: 'F1', action: () => dispatch('navigate', { topicId: 'getting-started' }) },
    { id: 'index', label: 'Index', action: () => dispatch('search', { query: '' }) },
    { id: 'separator1', type: 'separator' },
    { id: 'about', label: 'About Help System', action: () => showAboutDialog = true }
  ];

  // Menu handlers
  function toggleMenu(menuId: string) {
    activeMenu = activeMenu === menuId ? null : menuId;
  }

  function handleMenuItemClick(item: any) {
    if (item.action) {
      item.action();
    }
    activeMenu = null;
  }

  function handleKeydown(event: KeyboardEvent) {
    // Handle keyboard shortcuts
    if (event.ctrlKey || event.altKey) {
      switch (event.key) {
        case 'n':
          if (event.ctrlKey) event.preventDefault();
          break;
        case 'o':
          if (event.ctrlKey) event.preventDefault();
          break;
        case 'p':
          if (event.ctrlKey) {
            event.preventDefault();
            showPrintDialog = true;
          }
          break;
        case 'c':
          if (event.ctrlKey) event.preventDefault();
          break;
        case 'a':
          if (event.ctrlKey) event.preventDefault();
          break;
        case 'f':
          if (event.ctrlKey) {
            event.preventDefault();
            dispatch('search', { query: '' });
          }
          break;
        case 'd':
          if (event.ctrlKey) {
            event.preventDefault();
            addBookmark();
          }
          break;
        case 'F4':
          if (event.altKey) {
            event.preventDefault();
            dispatch('close');
          }
          break;
      }
    }

    // Handle function keys
    switch (event.key) {
      case 'F1':
        event.preventDefault();
        dispatch('navigate', { topicId: 'getting-started' });
        break;
      case 'F5':
        event.preventDefault();
        refresh();
        break;
    }

    // Handle arrow keys for menu navigation
    if (activeMenu) {
      switch (event.key) {
        case 'Escape':
          activeMenu = null;
          break;
        case 'ArrowLeft':
        case 'ArrowRight':
          // Navigate between menus
          break;
        case 'ArrowDown':
        case 'ArrowUp':
          // Navigate within menu
          break;
        case 'Enter':
          // Activate selected menu item
          break;
      }
    }
  }

  function addBookmark() {
    if (currentTopic) {
      dispatch('bookmark', { topicId: currentTopic.id });
    }
  }

  function toggleToolbar() {
    // Toggle toolbar visibility
    dispatch('preference-change', { showToolbar: !helpSystem.getState().userPreferences.showToolbar });
  }

  function toggleStatusBar() {
    // Toggle status bar visibility
    dispatch('preference-change', { showStatusBar: !helpSystem.getState().userPreferences.showStatusBar });
  }

  function setFontSize(size: 'small' | 'medium' | 'large') {
    dispatch('preference-change', { fontSize: size });
  }

  async function refresh() {
    try {
      await helpSystem.refresh();
    } catch (error) {
      console.error('Failed to refresh:', error);
    }
  }

  function closeDialogs() {
    showAboutDialog = false;
    showPreferencesDialog = false;
    showPrintDialog = false;
  }

  // Close menus when clicking outside
  function handleClickOutside(event: MouseEvent) {
    if (!(event.target as Element).closest('.menu-bar, .menu-dropdown')) {
      activeMenu = null;
    }
  }
</script>

<svelte:window on:keydown={handleKeydown} on:click={handleClickOutside} />

<div class="menu-bar">
  <!-- File Menu -->
  <div class="menu-item" class:active={activeMenu === 'file'}>
    <button 
      class="menu-button" 
      on:click={() => toggleMenu('file')}
      on:keydown={(e) => e.key === 'Enter' && toggleMenu('file')}
    >
      &File
    </button>
    {#if activeMenu === 'file'}
      <div class="menu-dropdown">
        {#each fileMenuItems as item}
          {#if item.type === 'separator'}
            <div class="menu-separator"></div>
          {:else}
            <button 
              class="menu-dropdown-item" 
              class:disabled={item.disabled}
              on:click={() => handleMenuItemClick(item)}
            >
              <span class="menu-label">{item.label}</span>
              {#if item.shortcut}
                <span class="menu-shortcut">{item.shortcut}</span>
              {/if}
            </button>
          {/if}
        {/each}
      </div>
    {/if}
  </div>

  <!-- Edit Menu -->
  <div class="menu-item" class:active={activeMenu === 'edit'}>
    <button 
      class="menu-button" 
      on:click={() => toggleMenu('edit')}
      on:keydown={(e) => e.key === 'Enter' && toggleMenu('edit')}
    >
      &Edit
    </button>
    {#if activeMenu === 'edit'}
      <div class="menu-dropdown">
        {#each editMenuItems as item}
          {#if item.type === 'separator'}
            <div class="menu-separator"></div>
          {:else}
            <button 
              class="menu-dropdown-item" 
              class:disabled={item.disabled}
              on:click={() => handleMenuItemClick(item)}
            >
              <span class="menu-label">{item.label}</span>
              {#if item.shortcut}
                <span class="menu-shortcut">{item.shortcut}</span>
              {/if}
            </button>
          {/if}
        {/each}
      </div>
    {/if}
  </div>

  <!-- View Menu -->
  <div class="menu-item" class:active={activeMenu === 'view'}>
    <button 
      class="menu-button" 
      on:click={() => toggleMenu('view')}
      on:keydown={(e) => e.key === 'Enter' && toggleMenu('view')}
    >
      &View
    </button>
    {#if activeMenu === 'view'}
      <div class="menu-dropdown">
        {#each viewMenuItems as item}
          {#if item.type === 'separator'}
            <div class="menu-separator"></div>
          {:else if item.submenu}
            <div class="menu-submenu">
              <button class="menu-dropdown-item">
                <span class="menu-label">{item.label}</span>
                <span class="menu-arrow">▶</span>
              </button>
              <div class="menu-submenu-dropdown">
                {#each item.submenu as subItem}
                  <button 
                    class="menu-dropdown-item" 
                    class:checked={subItem.checked}
                    on:click={() => handleMenuItemClick(subItem)}
                  >
                    <span class="menu-label">{subItem.label}</span>
                    {#if subItem.checked}
                      <span class="menu-check">✓</span>
                    {/if}
                  </button>
                {/each}
              </div>
            </div>
          {:else}
            <button 
              class="menu-dropdown-item" 
              class:checked={item.checked}
              on:click={() => handleMenuItemClick(item)}
            >
              <span class="menu-label">{item.label}</span>
              {#if item.checked}
                <span class="menu-check">✓</span>
              {/if}
              {#if item.shortcut}
                <span class="menu-shortcut">{item.shortcut}</span>
              {/if}
            </button>
          {/if}
        {/each}
      </div>
    {/if}
  </div>

  <!-- Go Menu -->
  <div class="menu-item" class:active={activeMenu === 'go'}>
    <button 
      class="menu-button" 
      on:click={() => toggleMenu('go')}
      on:keydown={(e) => e.key === 'Enter' && toggleMenu('go')}
    >
      &Go
    </button>
    {#if activeMenu === 'go'}
      <div class="menu-dropdown">
        {#each goMenuItems as item}
          {#if item.type === 'separator'}
            <div class="menu-separator"></div>
          {:else}
            <button 
              class="menu-dropdown-item" 
              class:disabled={item.disabled}
              on:click={() => handleMenuItemClick(item)}
            >
              <span class="menu-label">{item.label}</span>
              {#if item.shortcut}
                <span class="menu-shortcut">{item.shortcut}</span>
              {/if}
            </button>
          {/if}
        {/each}
      </div>
    {/if}
  </div>

  <!-- Help Menu -->
  <div class="menu-item" class:active={activeMenu === 'help'}>
    <button 
      class="menu-button" 
      on:click={() => toggleMenu('help')}
      on:keydown={(e) => e.key === 'Enter' && toggleMenu('help')}
    >
      &Help
    </button>
    {#if activeMenu === 'help'}
      <div class="menu-dropdown">
        {#each helpMenuItems as item}
          {#if item.type === 'separator'}
            <div class="menu-separator"></div>
          {:else}
            <button 
              class="menu-dropdown-item" 
              on:click={() => handleMenuItemClick(item)}
            >
              <span class="menu-label">{item.label}</span>
              {#if item.shortcut}
                <span class="menu-shortcut">{item.shortcut}</span>
              {/if}
            </button>
          {/if}
        {/each}
      </div>
    {/if}
  </div>
</div>

<!-- About Dialog -->
{#if showAboutDialog}
  <div class="dialog-overlay" on:click={closeDialogs}>
    <div class="dialog" on:click|stopPropagation>
      <div class="dialog-title-bar">
        <div class="dialog-title">About Help System</div>
        <button class="dialog-close" on:click={closeDialogs}>×</button>
      </div>
      <div class="dialog-content">
        <div class="about-content">
          <div class="about-icon">📖</div>
          <div class="about-title">Windows 98 Help System</div>
          <div class="about-version">Version 1.0.0</div>
          <div class="about-description">
            A comprehensive help system for the Abu OS 98 ecosystem, 
            providing Windows 98 authentic styling and functionality.
          </div>
          <div class="about-copyright">
            © 2024 Abu OS 98. All rights reserved.
          </div>
        </div>
      </div>
      <div class="dialog-buttons">
        <button class="dialog-button" on:click={closeDialogs}>OK</button>
      </div>
    </div>
  </div>
{/if}

<!-- Print Dialog -->
{#if showPrintDialog}
  <div class="dialog-overlay" on:click={closeDialogs}>
    <div class="dialog" on:click|stopPropagation>
      <div class="dialog-title-bar">
        <div class="dialog-title">Print</div>
        <button class="dialog-close" on:click={closeDialogs}>×</button>
      </div>
      <div class="dialog-content">
        <div class="print-content">
          <div class="print-preview">
            <div class="print-preview-header">
              <div class="print-preview-title">
                {currentTopic?.title || 'Help Topic'}
              </div>
            </div>
            <div class="print-preview-body">
              Preview of content to be printed...
            </div>
          </div>
        </div>
      </div>
      <div class="dialog-buttons">
        <button class="dialog-button" on:click={closeDialogs}>Cancel</button>
        <button class="dialog-button primary" on:click={closeDialogs}>Print</button>
      </div>
    </div>
  </div>
{/if}

<style>
