import {
	isPosition,
	isSize,
	isBounds,
	ValidationError,
	type Position,
	type Size,
	type Bounds,
	type WindowState,
	type StoredState
} from './types.js';
import {
	MIN_WINDOW_WIDTH,
	MIN_WINDOW_HEIGHT,
	WINDOW_BASE_Z,
	VOLUME_MIN,
	VOLUME_MAX,
	STORAGE_VERSION
} from './constants.js';

/**
 *
 * @param value
 */
export function validatePosition(value: unknown): Position {
	if (!isPosition(value)) {
		throw new ValidationError('position', 'Must be an object with x and y number properties');
	}

	if (!Number.isFinite(value.x)) {
		throw new ValidationError('position.x', 'Must be a finite number');
	}

	if (!Number.isFinite(value.y)) {
		throw new ValidationError('position.y', 'Must be a finite number');
	}

	if (value.y < 0) {
		throw new ValidationError('position.y', 'Must be greater than or equal to 0');
	}

	return value;
}

/**
 *
 * @param value
 */
export function validateSize(value: unknown): Size {
	if (!isSize(value)) {
		throw new ValidationError('size', 'Must be an object with width and height number properties');
	}

	if (!Number.isFinite(value.width) || value.width < 0) {
		throw new ValidationError('size.width', 'Must be a finite non-negative number');
	}

	if (!Number.isFinite(value.height) || value.height < 0) {
		throw new ValidationError('size.height', 'Must be a finite non-negative number');
	}

	if (value.width < MIN_WINDOW_WIDTH) {
		throw new ValidationError('size.width', `Must be at least ${MIN_WINDOW_WIDTH}px`);
	}

	if (value.height < MIN_WINDOW_HEIGHT) {
		throw new ValidationError('size.height', `Must be at least ${MIN_WINDOW_HEIGHT}px`);
	}

	return value;
}

/**
 *
 * @param value
 */
export function validateBounds(value: unknown): Bounds {
	if (!isBounds(value)) {
		throw new ValidationError(
			'bounds',
			'Must be an object with x, y, width, and height number properties'
		);
	}

	if (!Number.isFinite(value.x)) {
		throw new ValidationError('bounds.x', 'Must be a finite number');
	}

	if (!Number.isFinite(value.y) || value.y < 0) {
		throw new ValidationError('bounds.y', 'Must be a finite non-negative number');
	}

	if (!Number.isFinite(value.width) || value.width < MIN_WINDOW_WIDTH) {
		throw new ValidationError('bounds.width', `Must be at least ${MIN_WINDOW_WIDTH}px`);
	}

	if (!Number.isFinite(value.height) || value.height < MIN_WINDOW_HEIGHT) {
		throw new ValidationError('bounds.height', `Must be at least ${MIN_WINDOW_HEIGHT}px`);
	}

	return value;
}

/**
 *
 * @param value
 */
export function validateWindowState(value: unknown): WindowState {
	if (typeof value !== 'object' || value === null) {
		throw new ValidationError('windowState', 'Must be an object');
	}

	const obj = value as Partial<WindowState>;

	if (!obj.id || typeof obj.id !== 'string') {
		throw new ValidationError('windowState.id', 'Must be a non-empty string');
	}

	if (!obj.pluginId || typeof obj.pluginId !== 'string') {
		throw new ValidationError('windowState.pluginId', 'Must be a non-empty string');
	}

	if (!obj.title || typeof obj.title !== 'string') {
		throw new ValidationError('windowState.title', 'Must be a non-empty string');
	}

	if (!obj.iconClass || typeof obj.iconClass !== 'string') {
		throw new ValidationError('windowState.iconClass', 'Must be a non-empty string');
	}

	validatePosition(obj.position);
	validateSize(obj.size);

	if (typeof obj.zIndex !== 'number' || obj.zIndex < WINDOW_BASE_Z) {
		throw new ValidationError('windowState.zIndex', `Must be a number >= ${WINDOW_BASE_Z}`);
	}

	if (typeof obj.isMinimized !== 'boolean') {
		throw new ValidationError('windowState.isMinimized', 'Must be a boolean');
	}

	if (typeof obj.isMaximized !== 'boolean') {
		throw new ValidationError('windowState.isMaximized', 'Must be a boolean');
	}

	if (obj.isMinimized && obj.isMaximized) {
		throw new ValidationError('windowState', 'Cannot be both minimized and maximized');
	}

	if (typeof obj.isFocused !== 'boolean') {
		throw new ValidationError('windowState.isFocused', 'Must be a boolean');
	}

	if (typeof obj.isResizable !== 'boolean') {
		throw new ValidationError('windowState.isResizable', 'Must be a boolean');
	}

	if (obj.preMaximizeBounds !== undefined) {
		validateBounds(obj.preMaximizeBounds);
	}

	return obj as WindowState;
}

/**
 *
 * @param value
 */
export function validateVolume(value: unknown): number {
	if (typeof value !== 'number') {
		throw new ValidationError('volume', 'Must be a number');
	}

	if (!Number.isFinite(value)) {
		throw new ValidationError('volume', 'Must be a finite number');
	}

	if (value < VOLUME_MIN || value > VOLUME_MAX) {
		throw new ValidationError('volume', `Must be between ${VOLUME_MIN} and ${VOLUME_MAX}`);
	}

	return value;
}

/**
 *
 * @param value
 */
export function validateStoredState(value: unknown): StoredState {
	if (typeof value !== 'object' || value === null) {
		throw new ValidationError('storedState', 'Must be an object');
	}

	const obj = value as Partial<StoredState>;

	if (typeof obj.version !== 'number' || obj.version !== STORAGE_VERSION) {
		throw new ValidationError('storedState.version', `Must be ${STORAGE_VERSION}`);
	}

	if (typeof obj.timestamp !== 'number' || obj.timestamp <= 0) {
		throw new ValidationError('storedState.timestamp', 'Must be a positive number');
	}

	if (typeof obj.ttl !== 'number' || obj.ttl <= 0) {
		throw new ValidationError('storedState.ttl', 'Must be a positive number');
	}

	const now = Date.now();
	const age = now - obj.timestamp;
	const maxAge = obj.ttl * 24 * 60 * 60 * 1000;

	if (age > maxAge) {
		throw new ValidationError('storedState', 'State has exceeded TTL and is expired');
	}

	if (typeof obj.windows !== 'object' || obj.windows === null) {
		throw new ValidationError('storedState.windows', 'Must be an object');
	}

	if (!Array.isArray(obj.windows.open)) {
		throw new ValidationError('storedState.windows.open', 'Must be an array');
	}

	if (!Array.isArray(obj.windows.history)) {
		throw new ValidationError('storedState.windows.history', 'Must be an array');
	}

	if (typeof obj.desktop !== 'object' || obj.desktop === null) {
		throw new ValidationError('storedState.desktop', 'Must be an object');
	}

	if (obj.desktop.layout !== 'grid' && obj.desktop.layout !== 'custom') {
		throw new ValidationError('storedState.desktop.layout', 'Must be "grid" or "custom"');
	}

	if (!Array.isArray(obj.desktop.icons)) {
		throw new ValidationError('storedState.desktop.icons', 'Must be an array');
	}

	if (typeof obj.theme !== 'object' || obj.theme === null) {
		throw new ValidationError('storedState.theme', 'Must be an object');
	}

	if (obj.theme.current !== 'light' && obj.theme.current !== 'dark') {
		throw new ValidationError('storedState.theme.current', 'Must be "light" or "dark"');
	}

	if (typeof obj.theme.auto !== 'boolean') {
		throw new ValidationError('storedState.theme.auto', 'Must be a boolean');
	}

	if (typeof obj.audio !== 'object' || obj.audio === null) {
		throw new ValidationError('storedState.audio', 'Must be an object');
	}

	validateVolume(obj.audio.volume);

	if (typeof obj.audio.muted !== 'boolean') {
		throw new ValidationError('storedState.audio.muted', 'Must be a boolean');
	}

	if (obj.audio.track !== null && typeof obj.audio.track !== 'string') {
		throw new ValidationError('storedState.audio.track', 'Must be a string or null');
	}

	return obj as StoredState;
}

/**
 *
 * @param id
 */
export function validatePluginId(id: unknown): string {
	if (typeof id !== 'string' || id.length === 0) {
		throw new ValidationError('pluginId', 'Must be a non-empty string');
	}

	if (!/^[a-z0-9-]+$/.test(id)) {
		throw new ValidationError('pluginId', 'Must be lowercase kebab-case (letters, numbers, hyphens)');
	}

	return id;
}

/**
 *
 * @param version
 */
export function validateSemanticVersion(version: unknown): string {
	if (typeof version !== 'string') {
		throw new ValidationError('version', 'Must be a string');
	}

	if (!/^\d+\.\d+\.\d+$/.test(version)) {
		throw new ValidationError('version', 'Must be in semantic version format (e.g., "1.0.0")');
	}

	// Check for leading zeros in version components
	const parts = version.split('.');
	for (const part of parts) {
		if (part.length > 1 && part.startsWith('0')) {
			throw new ValidationError('version', 'Version components cannot have leading zeros');
		}
	}

	return version;
}

