<!--
  Windows 98 F1 Help System - Content Area Component
  
  This component displays the main content area where help topics are rendered,
  including text content, images, links, and interactive elements.
  
  @fileoverview Content area component for help system
-->

<script lang="ts">
  import { onMount, onDestroy } from 'svelte';
  import type { HelpTopic, HelpSystemState } from '../types.js';

  // Props
  let { 
    currentTopic = null,
    systemState,
    isLoading = false,
    error = null
  }: {
    currentTopic?: HelpTopic | null;
    systemState?: HelpSystemState;
    isLoading?: boolean;
    error?: string | null;
  } = $props();

  // State
  let contentContainer: HTMLDivElement;
  let scrollPosition = $state(0);

  // Computed values
  const hasContent = $derived(currentTopic && currentTopic.content);
  const displayContent = $derived(currentTopic?.content || '');

  // Event handlers
  function handleScroll(event: Event) {
    const target = event.target as HTMLDivElement;
    scrollPosition = target.scrollTop;
  }

  function handleLinkClick(event: Event) {
    const target = event.target as HTMLElement;
    if (target.tagName === 'A') {
      event.preventDefault();
      const href = target.getAttribute('href');
      if (href) {
        // Handle internal links
        if (href.startsWith('#')) {
          const topicId = href.substring(1);
          // Dispatch topic navigation event
          const customEvent = new CustomEvent('topic-navigate', {
            detail: { topicId },
            bubbles: true
          });
          target.dispatchEvent(customEvent);
        } else {
          // Handle external links
          window.open(href, '_blank');
        }
      }
    }
  }

  function handleImageLoad(event: Event) {
    const img = event.target as HTMLImageElement;
    img.style.opacity = '1';
  }

  function handleImageError(event: Event) {
    const img = event.target as HTMLImageElement;
    img.style.display = 'none';
    console.warn('Failed to load image:', img.src);
  }

  // Lifecycle
  onMount(() => {
    if (contentContainer) {
      contentContainer.addEventListener('scroll', handleScroll);
      contentContainer.addEventListener('click', handleLinkClick);
    }
  });

  onDestroy(() => {
    if (contentContainer) {
      contentContainer.removeEventListener('scroll', handleScroll);
      contentContainer.removeEventListener('click', handleLinkClick);
    }
  });
</script>

<div class="content-area win98-content-area">
  {#if isLoading}
    <div class="loading-container">
      <div class="loading-spinner"></div>
      <div class="loading-text">Loading content...</div>
    </div>
  {:else if error}
    <div class="error-container">
      <div class="error-icon">⚠️</div>
      <div class="error-title">Error Loading Content</div>
      <div class="error-message">{error}</div>
      <button class="retry-button" onclick={() => window.location.reload()}>
        Retry
      </button>
    </div>
  {:else if !hasContent}
    <div class="empty-container">
      <div class="empty-icon">📖</div>
      <div class="empty-title">No Content Available</div>
      <div class="empty-message">
        Select a topic from the table of contents to view its content.
      </div>
    </div>
  {:else}
    <div 
      class="content-container"
      bind:this={contentContainer}
      role="main"
      aria-label="Help content"
    >
      <div class="content-header">
        {#if currentTopic}
          <h1 class="content-title">{currentTopic.title}</h1>
          {#if currentTopic.subtitle}
            <h2 class="content-subtitle">{currentTopic.subtitle}</h2>
          {/if}
        {/if}
      </div>
      
      <div class="content-body">
        {@html displayContent}
      </div>
      
      {#if currentTopic?.relatedTopics && currentTopic.relatedTopics.length > 0}
        <div class="related-topics">
          <h3 class="related-title">Related Topics</h3>
          <ul class="related-list">
            {#each currentTopic.relatedTopics as relatedTopic}
              <li class="related-item">
                <a 
                  href="#{relatedTopic.id}" 
                  class="related-link"
                  title={relatedTopic.title}
                >
                  {relatedTopic.title}
                </a>
              </li>
            {/each}
          </ul>
        </div>
      {/if}
    </div>
  {/if}
</div>

