/**
 * Windows 98 F1 Help System - Styles Export
 * 
 * This file exports all help system styles and provides utilities
 * for style management and theming.
 * 
 * @fileoverview Main export file for help system styles
 */

// Import main styles
import './help-system.scss';

/**
 * Help system style utilities
 */
export class HelpStyleManager {
  private static instance: HelpStyleManager;
  private currentTheme: 'light' | 'dark' | 'high-contrast' = 'light';

  private constructor() {}

  /**
   * Get singleton instance
   */
  static getInstance(): HelpStyleManager {
    if (!HelpStyleManager.instance) {
      HelpStyleManager.instance = new HelpStyleManager();
    }
    return HelpStyleManager.instance;
  }

  /**
   * Set theme
   */
  setTheme(theme: 'light' | 'dark' | 'high-contrast'): void {
    this.currentTheme = theme;
    document.documentElement.setAttribute('data-help-theme', theme);
  }

  /**
   * Get current theme
   */
  getTheme(): 'light' | 'dark' | 'high-contrast' {
    return this.currentTheme;
  }

  /**
   * Apply Windows 98 styling to element
   */
  applyWin98Styling(element: HTMLElement, type: 'button' | 'input' | 'panel' | 'dialog'): void {
    element.classList.add('help-system');
    
    switch (type) {
      case 'button':
        element.classList.add('help-button');
        break;
      case 'input':
        element.classList.add('help-input');
        break;
      case 'panel':
        element.classList.add('help-panel');
        break;
      case 'dialog':
        element.classList.add('help-dialog');
        break;
    }
  }

  /**
   * Remove Windows 98 styling from element
   */
  removeWin98Styling(element: HTMLElement): void {
    element.classList.remove(
      'help-system',
      'help-button',
      'help-input',
      'help-panel',
      'help-dialog'
    );
  }

  /**
   * Initialize help system styles
   */
  initialize(): void {
    // Set initial theme
    this.setTheme('light');
    
    // Apply global styles
    document.documentElement.classList.add('help-system-root');
    
    // Set up theme change listeners
    this.setupThemeListeners();
  }

  /**
   * Set up theme change listeners
   */
  private setupThemeListeners(): void {
    // Listen for system theme changes
    if (window.matchMedia) {
      const highContrastQuery = window.matchMedia('(prefers-contrast: high)');
      const reducedMotionQuery = window.matchMedia('(prefers-reduced-motion: reduce)');
      
      highContrastQuery.addEventListener('change', (e) => {
        if (e.matches) {
          this.setTheme('high-contrast');
        } else {
          this.setTheme('light');
        }
      });
      
      reducedMotionQuery.addEventListener('change', (e) => {
        document.documentElement.setAttribute('data-reduced-motion', e.matches ? 'true' : 'false');
      });
    }
  }

  /**
   * Get CSS custom property value
   */
  getCSSProperty(property: string): string {
    return getComputedStyle(document.documentElement).getPropertyValue(property);
  }

  /**
   * Set CSS custom property value
   */
  setCSSProperty(property: string, value: string): void {
    document.documentElement.style.setProperty(property, value);
  }

  /**
   * Get Windows 98 color value
   */
  getWin98Color(colorName: string): string {
    return this.getCSSProperty(`--win98-color-${colorName}`);
  }

  /**
   * Set Windows 98 color value
   */
  setWin98Color(colorName: string, value: string): void {
    this.setCSSProperty(`--win98-color-${colorName}`, value);
  }
}

