/**
 * Style utility functions
 */
export const HelpStyleUtils = {
  /**
   * Create Windows 98 button element
   */
  createButton(text: string, className: string = ''): HTMLButtonElement {
    const button = document.createElement('button');
    button.textContent = text;
    button.className = `help-button ${className}`.trim();
    return button;
  },

  /**
   * Create Windows 98 input element
   */
  createInput(type: string = 'text', placeholder: string = '', className: string = ''): HTMLInputElement {
    const input = document.createElement('input');
    input.type = type;
    input.placeholder = placeholder;
    input.className = `help-input ${className}`.trim();
    return input;
  },

  /**
   * Create Windows 98 panel element
   */
  createPanel(className: string = ''): HTMLDivElement {
    const panel = document.createElement('div');
    panel.className = `help-panel ${className}`.trim();
    return panel;
  },

  /**
   * Create Windows 98 dialog element
   */
  createDialog(className: string = ''): HTMLDivElement {
    const dialog = document.createElement('div');
    dialog.className = `help-dialog ${className}`.trim();
    return dialog;
  },

  /**
   * Apply Windows 98 border to element
   */
  applyBorder(element: HTMLElement, type: 'raised' | 'inset' | 'groove' | 'ridge'): void {
    element.classList.add(`help-border-${type}`);
  },

  /**
   * Apply Windows 98 scrollbar to element
   */
  applyScrollbar(element: HTMLElement): void {
    element.classList.add('help-scrollbar');
  },

  /**
   * Check if element has Windows 98 styling
   */
  hasWin98Styling(element: HTMLElement): boolean {
    return element.classList.contains('help-system') || 
           element.classList.contains('help-button') ||
           element.classList.contains('help-input') ||
           element.classList.contains('help-panel') ||
           element.classList.contains('help-dialog');
  },

  /**
   * Get element's Windows 98 style type
   */
  getWin98StyleType(element: HTMLElement): string | null {
    if (element.classList.contains('help-button')) return 'button';
    if (element.classList.contains('help-input')) return 'input';
    if (element.classList.contains('help-panel')) return 'panel';
    if (element.classList.contains('help-dialog')) return 'dialog';
    return null;
  }
};

/**
 * Initialize help system styles
 */
export function initializeHelpStyles(): HelpStyleManager {
  const styleManager = HelpStyleManager.getInstance();
  styleManager.initialize();
  return styleManager;
}

/**
 * Get help system style manager
 */
export function getHelpStyleManager(): HelpStyleManager {
  return HelpStyleManager.getInstance();
}
