<!--
  Windows 98 F1 Help System - Index Panel Component
  
  This component provides the alphabetical index interface in the Index tab,
  showing topics organized alphabetically with quick navigation.
  
  @fileoverview Index panel component for help system
-->

<script lang="ts">
  import { createEventDispatcher, onMount } from 'svelte';
  import type { HelpSystemManager, HelpTopic } from '../index.js';

  // Props
  let { helpManager }: { helpManager: HelpSystemManager } = $props();

  // State
  let topics: HelpTopic[] = $state([]);
  let indexEntries: IndexEntry[] = $state([]);
  let selectedLetter: string | null = $state(null);
  let isLoading = $state(true);
  let error: string | null = $state(null);

  // Event dispatcher
  const dispatch = createEventDispatcher();

  // Index entry interface
  interface IndexEntry {
    letter: string;
    topics: HelpTopic[];
  }

  // Load topics and build index
  async function loadIndex() {
    try {
      isLoading = true;
      error = null;
      
      const allTopics = helpManager.getAllTopics();
      topics = allTopics;
      
      // Build alphabetical index
      const indexMap = new Map<string, HelpTopic[]>();
      
      for (const topic of allTopics) {
        const firstLetter = topic.title.charAt(0).toUpperCase();
        if (!indexMap.has(firstLetter)) {
          indexMap.set(firstLetter, []);
        }
        indexMap.get(firstLetter)!.push(topic);
      }
      
      // Sort topics within each letter
      for (const [letter, topicList] of indexMap) {
        topicList.sort((a, b) => a.title.localeCompare(b.title));
      }
      
      // Convert to array and sort by letter
      indexEntries = Array.from(indexMap.entries())
        .map(([letter, topics]) => ({ letter, topics }))
        .sort((a, b) => a.letter.localeCompare(b.letter));
      
      // Select first letter if available
      if (indexEntries.length > 0) {
        selectedLetter = indexEntries[0].letter;
      }
      
    } catch (err) {
      error = `Failed to load index: ${err instanceof Error ? err.message : 'Unknown error'}`;
      console.error('Error loading index:', err);
    } finally {
      isLoading = false;
    }
  }

  // Handle letter selection
  function handleLetterSelect(letter: string) {
    selectedLetter = letter;
  }

  // Handle topic selection
  function handleTopicSelect(topic: HelpTopic) {
    dispatch('topic-select', topic.id);
  }

  // Handle keyboard navigation
  function handleKeydown(event: KeyboardEvent, topic: HelpTopic) {
    if (event.key === 'Enter' || event.key === ' ') {
      event.preventDefault();
      handleTopicSelect(topic);
    }
  }

   // Get topics for selected letter
   let selectedTopics = $derived(selectedLetter 
     ? indexEntries.find(entry => entry.letter === selectedLetter)?.topics || []
     : []);

  // Initialize component
  onMount(() => {
    loadIndex();
  });
</script>

<!-- Index Panel Container -->
<div class="help-index-panel">
  {#if isLoading}
    <!-- Loading State -->
    <div class="index-loading">
      <div class="loading-spinner"></div>
      <p>Loading index...</p>
    </div>
  {:else if error}
    <!-- Error State -->
    <div class="index-error">
      <p>{error}</p>
      <button on:click={loadIndex}>Retry</button>
    </div>
  {:else if indexEntries.length === 0}
    <!-- Empty State -->
    <div class="index-empty">
      <p>No topics available for indexing</p>
    </div>
  {:else}
    <!-- Index Interface -->
    <div class="index-interface">
      <!-- Letter Navigation -->
      <div class="letter-nav">
        {#each indexEntries as entry}
          <button
            class="letter-button"
            class:selected={selectedLetter === entry.letter}
            on:click={() => handleLetterSelect(entry.letter)}
            title="{entry.letter} ({entry.topics.length} topics)"
          >
            {entry.letter}
          </button>
        {/each}
      </div>
      
      <!-- Topics List -->
      <div class="topics-list">
        {#if selectedLetter}
          <div class="topics-header">
            <h3>{selectedLetter} ({selectedTopics.length} topics)</h3>
          </div>
          
          {#if selectedTopics.length === 0}
            <div class="no-topics">
              <p>No topics found for letter "{selectedLetter}"</p>
            </div>
          {:else}
            <div class="topics-items">
              {#each selectedTopics as topic}
                <div
                  class="topic-item"
                  on:click={() => handleTopicSelect(topic)}
                  on:keydown={(e) => handleKeydown(e, topic)}
                  tabindex="0"
                  role="button"
                  title={topic.title}
                >
                  <span class="topic-icon">📄</span>
                  <span class="topic-title">{topic.title}</span>
                  <span class="topic-category">{topic.category}</span>
                </div>
              {/each}
            </div>
          {/if}
        {:else}
          <div class="no-selection">
            <p>Select a letter to view topics</p>
          </div>
        {/if}
      </div>
    </div>
  {/if}
</div>

