/**
 * Windows 98 F1 Help System - Bookmark Manager
 * 
 * This class manages help system bookmarks including adding, removing,
 * organizing, and persisting bookmarks to localStorage.
 * 
 * @fileoverview Bookmark management for help system topics
 */

import type {
  HelpBookmark,
  BookmarkOrganization
} from './types.js';

/**
 * Bookmark manager for help system topics
 */
export class HelpBookmarkManager {
  private bookmarks: Map<string, HelpBookmark> = new Map();
  private readonly storageKey = 'abu-help-bookmarks';
  private readonly maxBookmarks = 1000;

  /**
   * Add a bookmark for a topic
   * 
   * @param topicId - Topic ID to bookmark
   * @param title - Optional bookmark title
   * @returns Promise that resolves with the created bookmark
   * @throws Error if bookmark creation fails
   */
  async addBookmark(topicId: string, title?: string): Promise<HelpBookmark> {
    if (!topicId || typeof topicId !== 'string') {
      throw new Error('Topic ID is required and must be a string');
    }

    // Check if bookmark already exists
    if (this.bookmarks.has(topicId)) {
      throw new Error(`Bookmark already exists for topic: ${topicId}`);
    }

    // Check bookmark limit
    if (this.bookmarks.size >= this.maxBookmarks) {
      throw new Error(`Maximum number of bookmarks (${this.maxBookmarks}) reached`);
    }

    try {
      const bookmark: HelpBookmark = {
        id: this.generateBookmarkId(),
        topicId,
        title: title || `Bookmark for ${topicId}`,
        dateAdded: new Date(),
        category: 'general',
        notes: '',
        tags: []
      };

      this.bookmarks.set(topicId, bookmark);
      await this.saveBookmarks();

      return bookmark;
    } catch (error) {
      throw new Error(`Failed to add bookmark: ${error instanceof Error ? error.message : 'Unknown error'}`);
    }
  }

  /**
   * Remove a bookmark
   * 
   * @param topicId - Topic ID to remove bookmark for
   * @returns Promise that resolves when bookmark is removed
   * @throws Error if bookmark removal fails
   */
  async removeBookmark(topicId: string): Promise<void> {
    if (!topicId || typeof topicId !== 'string') {
      throw new Error('Topic ID is required and must be a string');
    }

    const bookmark = this.bookmarks.get(topicId);
    if (!bookmark) {
      throw new Error(`Bookmark not found for topic: ${topicId}`);
    }

    try {
      this.bookmarks.delete(topicId);
      await this.saveBookmarks();
    } catch (error) {
      throw new Error(`Failed to remove bookmark: ${error instanceof Error ? error.message : 'Unknown error'}`);
    }
  }

  /**
   * Get all bookmarks
   * 
   * @returns Array of all bookmarks
   */
  getBookmarks(): HelpBookmark[] {
    return Array.from(this.bookmarks.values());
  }

  /**
   * Get a specific bookmark by topic ID
   * 
   * @param topicId - Topic ID to get bookmark for
   * @returns Bookmark or null if not found
   */
  getBookmark(topicId: string): HelpBookmark | null {
    return this.bookmarks.get(topicId) || null;
  }

  /**
   * Check if a topic is bookmarked
   * 
   * @param topicId - Topic ID to check
   * @returns True if topic is bookmarked
   */
  isBookmarked(topicId: string): boolean {
    return this.bookmarks.has(topicId);
  }

  /**
   * Update a bookmark
   * 
   * @param bookmarkId - Bookmark ID to update
   * @param updates - Updates to apply
   * @returns Promise that resolves when bookmark is updated
   * @throws Error if bookmark update fails
   */
  async updateBookmark(bookmarkId: string, updates: Partial<HelpBookmark>): Promise<void> {
    if (!bookmarkId || typeof bookmarkId !== 'string') {
      throw new Error('Bookmark ID is required and must be a string');
    }

    // Find bookmark by ID
    let bookmark: HelpBookmark | undefined;
    for (const b of this.bookmarks.values()) {
      if (b.id === bookmarkId) {
        bookmark = b;
        break;
      }
    }

    if (!bookmark) {
      throw new Error(`Bookmark not found: ${bookmarkId}`);
    }

    try {
      // Validate updates
      const updatedBookmark = { ...bookmark, ...updates };
      
      // Validate title
      if (updates.title !== undefined && (!updates.title || typeof updates.title !== 'string')) {
        throw new Error('Bookmark title must be a non-empty string');
      }

      // Validate category
      if (updates.category !== undefined && (!updates.category || typeof updates.category !== 'string')) {
        throw new Error('Bookmark category must be a non-empty string');
      }

      // Validate notes
      if (updates.notes !== undefined && typeof updates.notes !== 'string') {
        throw new Error('Bookmark notes must be a string');
      }

      // Validate tags
      if (updates.tags !== undefined && (!Array.isArray(updates.tags) || !updates.tags.every(tag => typeof tag === 'string'))) {
        throw new Error('Bookmark tags must be an array of strings');
      }

      // Update bookmark
      this.bookmarks.set(bookmark.topicId, updatedBookmark);
      await this.saveBookmarks();
    } catch (error) {
      throw new Error(`Failed to update bookmark: ${error instanceof Error ? error.message : 'Unknown error'}`);
    }
  }

  /**
   * Organize bookmarks
   * 
   * @param organization - Organization configuration
   * @returns Promise that resolves when bookmarks are organized
   * @throws Error if organization fails
   */
  async organizeBookmarks(organization: BookmarkOrganization): Promise<void> {
    try {
      // Apply categories
      for (const category of organization.categories) {
        for (const bookmarkId of category.bookmarks) {
          const bookmark = this.getBookmarkById(bookmarkId);
          if (bookmark) {
            bookmark.category = category.name;
            this.bookmarks.set(bookmark.topicId, bookmark);
          }
        }
      }

      // Sort bookmarks
      const sortedBookmarks = this.sortBookmarks(organization.sortBy, organization.sortOrder);
      
      // Rebuild bookmark map with sorted order
      this.bookmarks.clear();
      for (const bookmark of sortedBookmarks) {
        this.bookmarks.set(bookmark.topicId, bookmark);
      }

      await this.saveBookmarks();
    } catch (error) {
      throw new Error(`Failed to organize bookmarks: ${error instanceof Error ? error.message : 'Unknown error'}`);
    }
  }

  /**
   * Save bookmarks to localStorage
   * 
   * @returns Promise that resolves when bookmarks are saved
   * @throws Error if saving fails
   */
  async saveBookmarks(): Promise<void> {
    try {
      const bookmarksArray = Array.from(this.bookmarks.values());
      const serialized = JSON.stringify(bookmarksArray, this.dateReplacer);
      
      if (typeof localStorage !== 'undefined') {
        localStorage.setItem(this.storageKey, serialized);
      }
    } catch (error) {
      throw new Error(`Failed to save bookmarks: ${error instanceof Error ? error.message : 'Unknown error'}`);
    }
  }

  /**
   * Load bookmarks from localStorage
   * 
   * @returns Promise that resolves when bookmarks are loaded
   * @throws Error if loading fails
   */
  async loadBookmarks(): Promise<void> {
    try {
      if (typeof localStorage === 'undefined') {
        return; // No localStorage available
      }

      const serialized = localStorage.getItem(this.storageKey);
      if (!serialized) {
        return; // No saved bookmarks
      }

      const bookmarksArray = JSON.parse(serialized, this.dateReviver) as HelpBookmark[];
      
      // Validate and load bookmarks
      this.bookmarks.clear();
      for (const bookmark of bookmarksArray) {
        if (this.validateBookmark(bookmark)) {
          this.bookmarks.set(bookmark.topicId, bookmark);
        }
      }
    } catch (error) {
      // If loading fails, clear corrupted data
      this.bookmarks.clear();
      if (typeof localStorage !== 'undefined') {
        localStorage.removeItem(this.storageKey);
      }
      throw new Error(`Failed to load bookmarks: ${error instanceof Error ? error.message : 'Unknown error'}`);
    }
  }

  /**
   * Export bookmarks to JSON string
   * 
   * @returns Promise that resolves with exported bookmarks JSON
   */
  async exportBookmarks(): Promise<string> {
    try {
      const bookmarksArray = Array.from(this.bookmarks.values());
      return JSON.stringify(bookmarksArray, this.dateReplacer, 2);
    } catch (error) {
      throw new Error(`Failed to export bookmarks: ${error instanceof Error ? error.message : 'Unknown error'}`);
    }
  }

  /**
   * Import bookmarks from JSON string
   * 
   * @param data - JSON string containing bookmarks
   * @returns Promise that resolves when bookmarks are imported
   * @throws Error if import fails
   */
  async importBookmarks(data: string): Promise<void> {
    if (!data || typeof data !== 'string') {
      throw new Error('Import data must be a non-empty string');
    }

    try {
      const bookmarksArray = JSON.parse(data, this.dateReviver) as HelpBookmark[];
      
      if (!Array.isArray(bookmarksArray)) {
        throw new Error('Import data must be an array of bookmarks');
      }

      // Validate and import bookmarks
      const validBookmarks: HelpBookmark[] = [];
      for (const bookmark of bookmarksArray) {
        if (this.validateBookmark(bookmark)) {
          validBookmarks.push(bookmark);
        }
      }

      // Check if import would exceed limit
      if (this.bookmarks.size + validBookmarks.length > this.maxBookmarks) {
        throw new Error(`Import would exceed maximum bookmark limit of ${this.maxBookmarks}`);
      }

      // Import bookmarks
      for (const bookmark of validBookmarks) {
        this.bookmarks.set(bookmark.topicId, bookmark);
      }

      await this.saveBookmarks();
    } catch (error) {
      throw new Error(`Failed to import bookmarks: ${error instanceof Error ? error.message : 'Unknown error'}`);
    }
  }

  /**
   * Get bookmarks by category
   * 
   * @param category - Category to filter by
   * @returns Array of bookmarks in category
   */
  getBookmarksByCategory(category: string): HelpBookmark[] {
    return Array.from(this.bookmarks.values()).filter(bookmark => bookmark.category === category);
  }

  /**
   * Get bookmark categories
   * 
   * @returns Array of unique categories
   */
  getCategories(): string[] {
    const categories = new Set<string>();
    for (const bookmark of this.bookmarks.values()) {
      if (bookmark.category) {
        categories.add(bookmark.category);
      }
    }
    return Array.from(categories).sort();
  }

  /**
   * Search bookmarks
   * 
   * @param query - Search query
   * @returns Array of matching bookmarks
   */
  searchBookmarks(query: string): HelpBookmark[] {
    if (!query || query.trim().length === 0) {
      return this.getBookmarks();
    }

    const searchTerm = query.toLowerCase().trim();
    return Array.from(this.bookmarks.values()).filter(bookmark => 
      bookmark.title.toLowerCase().includes(searchTerm) ||
      bookmark.topicId.toLowerCase().includes(searchTerm) ||
      (bookmark.notes && bookmark.notes.toLowerCase().includes(searchTerm)) ||
      (bookmark.tags && bookmark.tags.some(tag => tag.toLowerCase().includes(searchTerm))) ||
      (bookmark.category && bookmark.category.toLowerCase().includes(searchTerm))
    );
  }

  /**
   * Get bookmark statistics
   * 
   * @returns Bookmark statistics
   */
  getBookmarkStats(): { total: number; byCategory: Record<string, number>; oldest: Date | null; newest: Date | null } {
    const bookmarks = Array.from(this.bookmarks.values());
    const byCategory: Record<string, number> = {};
    let oldest: Date | null = null;
    let newest: Date | null = null;

    for (const bookmark of bookmarks) {
      // Count by category
      const category = bookmark.category || 'uncategorized';
      byCategory[category] = (byCategory[category] || 0) + 1;

      // Track oldest and newest
      if (!oldest || bookmark.dateAdded < oldest) {
        oldest = bookmark.dateAdded;
      }
      if (!newest || bookmark.dateAdded > newest) {
        newest = bookmark.dateAdded;
      }
    }

    return {
      total: bookmarks.length,
      byCategory,
      oldest,
      newest
    };
  }

  /**
   * Clear all bookmarks
   * 
   * @returns Promise that resolves when bookmarks are cleared
   */
  async clearAllBookmarks(): Promise<void> {
    try {
      this.bookmarks.clear();
      await this.saveBookmarks();
    } catch (error) {
      throw new Error(`Failed to clear bookmarks: ${error instanceof Error ? error.message : 'Unknown error'}`);
    }
  }

  /**
   * Generate unique bookmark ID
   * 
   * @returns Unique bookmark ID
   */
  private generateBookmarkId(): string {
    return `bookmark_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
  }

  /**
   * Get bookmark by ID
   * 
   * @param bookmarkId - Bookmark ID
   * @returns Bookmark or null if not found
   */
  private getBookmarkById(bookmarkId: string): HelpBookmark | null {
    for (const bookmark of this.bookmarks.values()) {
      if (bookmark.id === bookmarkId) {
        return bookmark;
      }
    }
    return null;
  }

  /**
   * Sort bookmarks
   * 
   * @param sortBy - Sort field
   * @param sortOrder - Sort order
   * @returns Sorted bookmarks array
   */
  private sortBookmarks(sortBy: 'title' | 'dateAdded' | 'category', sortOrder: 'asc' | 'desc'): HelpBookmark[] {
    const bookmarks = Array.from(this.bookmarks.values());
    
    return bookmarks.sort((a, b) => {
      let comparison = 0;
      
      switch (sortBy) {
        case 'title':
          comparison = a.title.localeCompare(b.title);
          break;
        case 'dateAdded':
          comparison = a.dateAdded.getTime() - b.dateAdded.getTime();
          break;
        case 'category':
          comparison = (a.category || '').localeCompare(b.category || '');
          break;
      }
      
      return sortOrder === 'desc' ? -comparison : comparison;
    });
  }

  /**
   * Validate bookmark
   * 
   * @param bookmark - Bookmark to validate
   * @returns True if bookmark is valid
   */
  private validateBookmark(bookmark: any): bookmark is HelpBookmark {
    return (
      bookmark &&
      typeof bookmark === 'object' &&
      typeof bookmark.id === 'string' &&
      typeof bookmark.topicId === 'string' &&
      typeof bookmark.title === 'string' &&
      bookmark.dateAdded instanceof Date &&
      (bookmark.category === undefined || typeof bookmark.category === 'string') &&
      (bookmark.notes === undefined || typeof bookmark.notes === 'string') &&
      (bookmark.tags === undefined || (Array.isArray(bookmark.tags) && bookmark.tags.every((tag: any) => typeof tag === 'string')))
    );
  }

  /**
   * Date replacer for JSON serialization
   * 
   * @param key - JSON key
   * @param value - JSON value
   * @returns Serialized value
   */
  private dateReplacer(_key: string, value: any): any {
    if (value instanceof Date) {
      return { __type: 'Date', value: value.toISOString() };
    }
    return value;
  }

  /**
   * Date reviver for JSON deserialization
   * 
   * @param key - JSON key
   * @param value - JSON value
   * @returns Deserialized value
   */
  private dateReviver(_key: string, value: any): any {
    if (value && typeof value === 'object' && value.__type === 'Date') {
      return new Date(value.value);
    }
    return value;
  }
}
