import type { KernelInterface, SystemInfo, CommandResult } from '../core/types.js';

export class MockKernel implements KernelInterface {
	private bootTimestamp: number;

	constructor() {
		this.bootTimestamp = Date.now();
	}

	async getSystemInfo(): Promise<SystemInfo> {
		// Simulate network latency: 50-100ms
		await this.delay(50, 100);

		const uptimeSeconds = Math.floor((Date.now() - this.bootTimestamp) / 1000);
		const usedMemory = Math.floor(Math.random() * 1000) + 500; // 500-1500 MB

		return {
			osName: 'Abu OS 98',
			version: '1.0.0',
			uptime: uptimeSeconds,
			totalMemory: 2048,
			usedMemory
		};
	}

	async executeCommand(cmd: string): Promise<CommandResult> {
		// Simulate command execution latency: 100-300ms
		const executionStart = Date.now();
		await this.delay(100, 300);
		const executionTime = Date.now() - executionStart;

		const trimmedCmd = cmd.trim();

		// Parse command
		if (trimmedCmd.startsWith('ping ') || trimmedCmd === 'ping') {
			const host = trimmedCmd.startsWith('ping ') 
				? trimmedCmd.substring(5).trim()
				: '';
			return this.handlePing(host, executionTime);
		}

		if (trimmedCmd === 'dir') {
			return {
				exitCode: 0,
				stdout:
					'Volume in drive C has no label.\n' +
					' Directory of C:\\\n\n' +
					'10/14/2025  06:00 PM    <DIR>          Windows\n' +
					'10/14/2025  06:00 PM    <DIR>          Program Files\n' +
					'10/14/2025  06:00 PM    <DIR>          Users\n' +
					'               0 File(s)              0 bytes\n' +
					'               3 Dir(s)  12,345,678,912 bytes free',
				stderr: '',
				executionTime
			};
		}

		if (trimmedCmd === 'ipconfig') {
			return {
				exitCode: 0,
				stdout:
					'Windows IP Configuration\n\n' +
					'Ethernet adapter Local Area Connection:\n\n' +
					'   Connection-specific DNS Suffix  . : \n' +
					'   IPv4 Address. . . . . . . . . . . : 192.168.1.100\n' +
					'   Subnet Mask . . . . . . . . . . . : 255.255.255.0\n' +
					'   Default Gateway . . . . . . . . . : 192.168.1.1',
				stderr: '',
				executionTime
			};
		}

		// Unknown command
		return {
			exitCode: 127,
			stdout: '',
			stderr: `'${trimmedCmd}' is not recognized as an internal or external command,\noperable program or batch file.`,
			executionTime
		};
	}

	private handlePing(host: string, executionTime: number): CommandResult {
		// Simple validation: check if host looks valid
		const isValid =
			host.length > 0 &&
			(host.includes('.') || host === 'localhost') &&
			!host.includes(' ');

		if (isValid) {
			return {
				exitCode: 0,
				stdout: `Reply from ${host}: bytes=32 time=15ms TTL=64`,
				stderr: '',
				executionTime
			};
		} else {
			return {
				exitCode: 1,
				stdout: '',
				stderr: `Ping request could not find host ${host}. Please check the name and try again.`,
				executionTime
			};
		}
	}

	private delay(minMs: number, maxMs: number): Promise<void> {
		const delayMs = Math.floor(Math.random() * (maxMs - minMs + 1)) + minMs;
		return new Promise((resolve) => setTimeout(resolve, delayMs));
	}
}

