<script lang="ts">
	import { onMount, onDestroy } from 'svelte';

	interface Props {
		windowId: string;
	}

	let { windowId }: Props = $props();

	// Connection state
	type ConnectionStatus = 'disconnected' | 'connecting' | 'connected' | 'error';
	let connectionStatus = $state<ConnectionStatus>('disconnected');
	let showDialog = $state(true);
	let host = $state('abupi.local');
	let port = $state('7681');
	let username = $state('pi');
	let password = $state('');
	let errorMessage = $state('');
	let bytesReceived = $state(0);

	// Terminal state
	let terminalOutput = $state<string[]>([]);
	let cursorVisible = $state(true);
	let websocket: WebSocket | null = null;
	let outputElement = $state<HTMLDivElement | null>(null);
	let connectionTime = $state(0);
	let cursorInterval: number | undefined;

	// Computed
	const websocketUrl = $derived(`ws://${host}:${port}/ws`);
	const isConnected = $derived(connectionStatus === 'connected');
	const isConnecting = $derived(connectionStatus === 'connecting');

	// Add boot messages when connected or connecting
	$effect(() => {
		if ((isConnected || isConnecting) && terminalOutput.length === 0) {
			addOutput('Microsoft(R) Windows 98');
			addOutput('(C)Copyright Microsoft Corp 1981-1999');
			addOutput('');
		}
	});

	// Cursor blink (530ms - authentic DOS rate)
	$effect(() => {
		if (isConnected) {
			cursorInterval = window.setInterval(() => {
				cursorVisible = !cursorVisible;
			}, 530);
		} else {
			if (cursorInterval) {
				window.clearInterval(cursorInterval);
			}
			cursorVisible = true;
		}
		
		return () => {
			if (cursorInterval) {
				window.clearInterval(cursorInterval);
			}
		};
	});

	// Auto-scroll terminal
	function scrollToBottom() {
		if (outputElement) {
			// Force scroll to bottom - use a large number to ensure we scroll to the bottom
			// This works even when scrollHeight is 0 in test environments
			outputElement.scrollTop = 999999;
			requestAnimationFrame(() => {
				if (outputElement) {
					outputElement.scrollTop = 999999;
				}
			});
		}
	}

	// Add output line
	function addOutput(text: string) {
		if (!text) return;
		
		// Handle different line endings
		const lines = text.split(/\r?\n/);
		
		// If we have existing content and the first line should append to last line
		if (terminalOutput.length > 0 && !text.startsWith('\n') && !text.startsWith('\r')) {
			// Check if last character was a line break
			const lastOutput = terminalOutput[terminalOutput.length - 1];
			if (lines[0]) {
				terminalOutput[terminalOutput.length - 1] = lastOutput + lines[0];
				lines.shift();
			}
		}
		
		// Add remaining lines
		lines.forEach(line => {
			terminalOutput.push(line);
		});
		
		// Limit buffer to 10,000 lines
		if (terminalOutput.length > 10000) {
			terminalOutput = terminalOutput.slice(-10000);
		}
		
		scrollToBottom();
	}

	// Connect to ttyd server
	async function handleConnect() {
		if (!host || !username) {
			errorMessage = 'Host and username are required';
			connectionStatus = 'error';
			return;
		}

		// Keep dialog open while connecting to show progress
		errorMessage = '';
		terminalOutput = [];
		connectionTime = Date.now();
		connectionStatus = 'connecting';
		
		// Delay hiding dialog to allow button text to update
		setTimeout(() => {
			if (connectionStatus === 'connecting') {
				showDialog = false;
			}
		}, 0);

		try {
			// Try to fetch auth token first (ttyd may require it)
			let wsUrl = websocketUrl;
			try {
				const tokenResponse = await fetch(`http://${host}:${port}/token`);
				if (tokenResponse.ok) {
					const { token } = await tokenResponse.json();
					wsUrl = `${websocketUrl}?token=${token}`;
				}
			} catch (e) {
				// Token not required or CORS issue, try without token
				console.log('No token required or CORS blocked, connecting directly...');
			}

			// Establish WebSocket connection
			websocket = new WebSocket(wsUrl);
			
			websocket.onopen = () => {
				connectionStatus = 'connected';
				showDialog = false; // Hide dialog when connected
				console.log('WebSocket connected, terminal ready');
				
				// Add global keyboard event listener
				const handleGlobalKeyDown = (e: KeyboardEvent) => {
					handleKeyDown(e);
				};
				window.addEventListener('keydown', handleGlobalKeyDown);
				
				// Send password if provided
				if (password && websocket) {
					websocket.send(password + '\n');
				}
			};

			websocket.onmessage = async (event) => {
				const data = event.data;
				
				// Handle both text and binary data
				let text = '';
				if (typeof data === 'string') {
					text = data;
					bytesReceived += data.length;
				} else if (data instanceof Blob) {
					text = await data.text();
					bytesReceived += text.length;
				} else if (data instanceof ArrayBuffer) {
					text = new TextDecoder().decode(data);
					bytesReceived += data.byteLength;
				}
				
				// Add terminal output
				if (text) {
					console.log('Received:', text.length, 'bytes');
					addOutput(text);
				}
			};

			websocket.onerror = (error) => {
				console.error('WebSocket error:', error);
				errorMessage = 'Connection error occurred';
				connectionStatus = 'error';
				// Keep terminal visible during error state
				showDialog = false;
				addOutput('ERROR: Connection failed');
				console.log('Added ERROR message to terminal output');
			};

			websocket.onclose = (event) => {
				connectionStatus = 'disconnected';
				showDialog = true;
				websocket = null;
			};

		} catch (error) {
			errorMessage = `Connection failed: ${error}`;
			connectionStatus = 'error';
		}
	}

	// Disconnect
	function handleDisconnect() {
		if (websocket) {
			websocket.close();
			websocket = null;
		}
		addOutput('');
		addOutput('Connection closed');
		connectionStatus = 'disconnected';
	}

	// Focus terminal input on mount when connected
	$effect(() => {
		if (isConnected && outputElement) {
			// Make the terminal screen focusable
			outputElement.tabIndex = 0;
			outputElement.focus();
		}
	});


	// Handle keyboard input
	function handleKeyDown(e: KeyboardEvent) {
		if (!isConnected || !websocket || websocket.readyState !== 1) {
			return;
		}

		// Special keys
		if (e.ctrlKey && e.key === 'v') {
			// Paste - handled by browser
			return;
		}

		if (e.ctrlKey && e.key === 'c') {
			// If there's a selection, let browser handle copy
			const selection = window.getSelection();
			if (selection && selection.toString().length > 0) {
				return;
			}
			// Otherwise send Ctrl+C to terminal
			// Fall through to send the control code
		}

		// Prevent default for most keys when connected
		if (!e.ctrlKey || (e.ctrlKey && e.key !== 'c' && e.key !== 'v')) {
			e.preventDefault();
		}

		// Send key to terminal
		let data = '';
		
		// Handle Ctrl combinations first
		if (e.ctrlKey && e.key.length === 1 && !e.altKey && !e.metaKey) {
			const char = e.key.toLowerCase();
			if (char >= 'a' && char <= 'z') {
				data = String.fromCharCode(char.charCodeAt(0) - 96);
			}
		} else if (e.key.length === 1 && !e.ctrlKey && !e.altKey && !e.metaKey) {
			// Regular character
			data = e.key;
		} else {
			// Special keys
			switch (e.key) {
				case 'Enter': data = '\r'; break;
				case 'Backspace': data = '\x7F'; break;
				case 'Tab': data = '\t'; break;
				case 'Escape': data = '\x1B'; break;
				case 'ArrowUp': data = '\x1B[A'; break;
				case 'ArrowDown': data = '\x1B[B'; break;
				case 'ArrowRight': data = '\x1B[C'; break;
				case 'ArrowLeft': data = '\x1B[D'; break;
				case 'Home': data = '\x1B[H'; break;
				case 'End': data = '\x1B[F'; break;
				case 'PageUp': data = '\x1B[5~'; break;
				case 'PageDown': data = '\x1B[6~'; break;
				case 'Delete': data = '\x1B[3~'; break;
				case 'Insert': data = '\x1B[2~'; break;
			}
		}

		if (data && websocket && websocket.readyState === 1) {
			websocket.send(data);
		}
	}

	// Handle paste
	function handlePaste(e: ClipboardEvent) {
		if (!isConnected || !websocket || websocket.readyState !== WebSocket.OPEN) return;
		
		e.preventDefault();
		const text = e.clipboardData?.getData('text');
		if (text && websocket.readyState === WebSocket.OPEN) {
			websocket.send(text);
		}
	}

	// Clear screen
	function handleClear() {
		terminalOutput = [];
		// Also clear any cursor line
		if (outputElement) {
			const cursorLine = outputElement.querySelector('.cursor');
			if (cursorLine && cursorLine.parentElement) {
				cursorLine.parentElement.remove();
			}
		}
	}

	// Retry connection
	function handleRetry() {
		errorMessage = '';
		connectionStatus = 'disconnected';
		showDialog = true;
	}

	// Format bytes
	function formatBytes(bytes: number): string {
		if (bytes < 1024) return `${bytes} B`;
		if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
		return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
	}

	// Cleanup on unmount
	onDestroy(() => {
		if (websocket) {
			websocket.close();
		}
		if (cursorInterval) {
			window.clearInterval(cursorInterval);
		}
	});
</script>

<div class="msdos-console">
	{#if showDialog}
		<!-- Windows 98 Connection Dialog -->
		<div class="connection-dialog">
			<div class="dialog-overlay">
				<div class="win98-dialog">
					<div class="dialog-header">
						<span class="titlebar-text">Microsoft(R) Windows 98</span>
						<span class="copyright">(C)Copyright Microsoft Corp 1981-1999</span>
					</div>
					<div class="win98-dialog-content">
						{#if errorMessage}
							<div class="error-message">
								<span class="error-icon">⚠</span>
								<span>{errorMessage}</span>
							</div>
						{/if}

						<div class="info-text">
							WebSocket URL: {websocketUrl}
						</div>

						<div class="help-text">
							Connect to a ttyd or websockify server
						</div>

						<div class="dialog-field">
							<label for="host-{windowId}">Host:</label>
							<input
								id="host-{windowId}"
								type="text"
								bind:value={host}
								placeholder="abupi.local"
								disabled={isConnecting}
							/>
						</div>

						<div class="dialog-field">
							<label for="port-{windowId}">Port:</label>
							<input
								id="port-{windowId}"
								type="text"
								bind:value={port}
								placeholder="7681"
								disabled={isConnecting}
							/>
						</div>

						<div class="dialog-field">
							<label for="username-{windowId}">Username:</label>
							<input
								id="username-{windowId}"
								type="text"
								bind:value={username}
								placeholder="pi"
								disabled={isConnecting}
							/>
						</div>

						<div class="dialog-field">
							<label for="password-{windowId}">Password:</label>
							<input
								id="password-{windowId}"
								type="password"
								bind:value={password}
								placeholder=""
								disabled={isConnecting}
							/>
						</div>

						<div class="dialog-buttons">
							{#if connectionStatus === 'error'}
								<button type="button" class="msdos-button" onclick={handleRetry}>
									Retry
								</button>
							{:else}
								<button type="button" class="msdos-button" onclick={handleConnect}>
									{connectionStatus === 'connecting' ? 'Connecting...' : 'Connect'}
								</button>
							{/if}
							<button type="button" class="msdos-button" onclick={() => {errorMessage = ''}}>
								Cancel
							</button>
						</div>
					</div>
				</div>
			</div>
		</div>
	{/if}
	{#if !showDialog || connectionStatus === 'connecting'}
		<!-- Terminal Screen -->
		<div 
			class="msdos-screen" 
			bind:this={outputElement}
			onkeydown={handleKeyDown}
			onpaste={handlePaste}
			tabindex="0"
		>
			<div class="terminal-output">
				{#each terminalOutput as line}
					<div class="terminal-line">{line}</div>
				{/each}
				{#if terminalOutput.length === 0}
					<div class="terminal-line">
						{#if cursorVisible}
							<span class="cursor">█</span>
						{/if}
					</div>
				{:else}
					{#if cursorVisible}
						<span class="cursor">█</span>
					{/if}
				{/if}
			</div>
		</div>

		<!-- Status Bar -->
		<div class="status-bar">
			<div class="status-left">
				<span class="status-indicator connected">●</span>
				<span>Connected: {username}@{host}:{port}</span>
			</div>
			<div class="status-center">
				<span>Rx: {formatBytes(bytesReceived)}</span>
			</div>
			<div class="status-right">
				<button type="button" class="status-button" onclick={handleDisconnect}>Disconnect</button>
				<button type="button" class="status-button" onclick={handleClear}>Clear</button>
			</div>
		</div>
	{/if}
</div>

