<script lang="ts">
	interface Props {
		value: string;
		placeholder?: string;
		disabled?: boolean;
		readonly?: boolean;
		required?: boolean;
		type?: 'text' | 'password' | 'number' | 'email' | 'url' | 'tel' | 'search';
		'aria-label'?: string;
		'aria-invalid'?: boolean;
		oninput: (value: string) => void;
		onchange?: (value: string) => void;
	}

	let {
		value = $bindable(),
		placeholder = '',
		disabled = false,
		readonly = false,
		required = false,
		type = 'text',
		'aria-label': ariaLabel,
		'aria-invalid': ariaInvalid,
		oninput,
		onchange
	}: Props = $props();

	function handleInput(e: Event) {
		const target = e.target as HTMLInputElement;
		value = target.value;
		oninput(value);
	}

	function handleChange(e: Event) {
		const target = e.target as HTMLInputElement;
		onchange?.(target.value);
	}
</script>

<input
	class="win98-input"
	{type}
	bind:value
	{placeholder}
	{disabled}
	{readonly}
	{required}
	role="textbox"
	aria-label={ariaLabel}
	aria-invalid={ariaInvalid}
	oninput={handleInput}
	onchange={handleChange}
/>

