<!--
  Windows 98 F1 Help System - Tab Bar Component
  
  This component provides the Windows 98 style tab bar with Contents, Index,
  Search, Favorites, and History tabs.
  
  @fileoverview Tab bar component for help system
-->

<script lang="ts">
  import { createEventDispatcher } from 'svelte';
  import type { HelpTab } from '../index.js';

  // Props
  let { activeTab = 'contents' }: { activeTab?: HelpTab } = $props();

  // Event dispatcher
  const dispatch = createEventDispatcher();

  // Tab definitions
  const tabs = [
    { id: 'contents', label: 'Contents', icon: '📖' },
    { id: 'index', label: 'Index', icon: '📋' },
    { id: 'search', label: 'Search', icon: '🔍' },
    { id: 'favorites', label: 'Favorites', icon: '⭐' },
    { id: 'history', label: 'History', icon: '🕒' }
  ] as const;

  // Handle tab click
  function handleTabClick(tabId: HelpTab) {
    if (tabId !== activeTab) {
      dispatch('tab-change', tabId);
    }
  }

  // Handle keyboard navigation
  function handleKeydown(event: KeyboardEvent) {
    const currentIndex = tabs.findIndex(tab => tab.id === activeTab);
    
    if (event.key === 'ArrowLeft' && currentIndex > 0) {
      event.preventDefault();
      handleTabClick(tabs[currentIndex - 1].id);
    } else if (event.key === 'ArrowRight' && currentIndex < tabs.length - 1) {
      event.preventDefault();
      handleTabClick(tabs[currentIndex + 1].id);
    } else if (event.key === 'Home') {
      event.preventDefault();
      handleTabClick(tabs[0].id);
    } else if (event.key === 'End') {
      event.preventDefault();
      handleTabClick(tabs[tabs.length - 1].id);
    }
  }
</script>

<svelte:window on:keydown={handleKeydown} />

<!-- Tab Bar -->
<div class="help-tab-bar">
  {#each tabs as tab}
    <button 
      class="help-tab"
      class:active={activeTab === tab.id}
      on:click={() => handleTabClick(tab.id)}
      on:keydown={(e) => e.key === 'Enter' && handleTabClick(tab.id)}
      title={tab.label}
    >
      <span class="tab-icon">{tab.icon}</span>
      <span class="tab-label">{tab.label}</span>
    </button>
  {/each}
</div>

<style>
  .help-tab-bar {
    display: flex;
    height: 24px;
    background-color: #c0c0c0;
    border-bottom: 1px solid #808080;
  }

  .help-tab {
    display: flex;
    align-items: center;
    gap: 4px;
    padding: 2px 12px;
    font-family: 'MS Sans Serif', 'Microsoft Sans Serif', 'Segoe UI', sans-serif;
    font-size: 11px;
    color: #000000;
    background-color: #c0c0c0;
    border: 1px outset #c0c0c0;
    border-bottom: none;
    cursor: pointer;
    margin-right: 2px;
    min-width: 80px;
    justify-content: center;
  }

  .help-tab:hover:not(.active) {
    background-color: #d0d0d0;
  }

  .help-tab.active {
    background-color: #c0c0c0;
    border: 1px inset #c0c0c0;
    border-bottom: 1px solid #c0c0c0;
    margin-bottom: -1px;
    z-index: 1;
    position: relative;
  }

  .tab-icon {
    font-size: 12px;
    line-height: 1;
  }

  .tab-label {
    font-weight: normal;
    white-space: nowrap;
  }

  /* Windows 98 tab styling */
  .help-tab:not(.active) {
    border: 1px outset #c0c0c0;
  }

  .help-tab:not(.active):hover {
    border: 1px outset #d0d0d0;
  }

  .help-tab:not(.active):active {
    border: 1px inset #c0c0c0;
  }

  /* Focus styles for accessibility */
  .help-tab:focus {
    outline: 2px solid #000080;
    outline-offset: 1px;
  }

  /* Responsive design */
  @media (max-width: 768px) {
    .help-tab {
      padding: 2px 8px;
      min-width: 60px;
    }
    
    .tab-label {
      display: none;
    }
    
    .tab-icon {
      font-size: 14px;
    }
  }

  @media (max-width: 480px) {
    .help-tab {
      padding: 2px 4px;
      min-width: 40px;
    }
    
    .tab-icon {
      font-size: 12px;
    }
  }
</style>

