<!--
  Windows 98 F1 Help System - Toolbar Component
  
  This component provides the Windows 98 style toolbar with navigation
  buttons (Back, Forward, Stop, Home) and action buttons (Search, Contents, Index).
  
  @fileoverview Toolbar component for help system
-->

<script lang="ts">
  import { createEventDispatcher } from 'svelte';
  import type { HelpSystemManager } from '../index.js';

  // Props
  let { helpManager }: { helpManager: HelpSystemManager } = $props();

  // State
  let canGoBack = $state(false);
  let canGoForward = $state(false);

  // Event dispatcher
  const dispatch = createEventDispatcher();

  // Update navigation state
  function updateNavigationState() {
    if (helpManager) {
      canGoBack = helpManager.getHistory().length > 0 && helpManager.getCurrentIndex() > 0;
      canGoForward = helpManager.getCurrentIndex() < helpManager.getHistory().length - 1;
    }
  }

  // Handle back button
  function handleGoBack() {
    if (canGoBack) {
      dispatch('go-back');
    }
  }

  // Handle forward button
  function handleGoForward() {
    if (canGoForward) {
      dispatch('go-forward');
    }
  }

  // Handle stop button
  function handleStop() {
    // TODO: Implement stop functionality
    console.log('Stop');
  }

  // Handle home button
  function handleGoHome() {
    dispatch('go-home');
  }

  // Handle search button
  function handleSearch() {
    helpManager?.setActiveTab('search');
  }

  // Handle contents button
  function handleContents() {
    helpManager?.setActiveTab('contents');
  }

  // Handle index button
  function handleIndex() {
    helpManager?.setActiveTab('index');
  }

  // Update state when help manager changes
  $effect(() => {
    if (helpManager) {
      updateNavigationState();
      
      // Listen for state changes
      const unsubscribe = helpManager.on('state:changed', () => {
        updateNavigationState();
      });
      
      // Clean up on destroy
      return unsubscribe;
    }
  });

  // Handle keyboard shortcuts
  function handleKeydown(event: KeyboardEvent) {
    if (event.altKey) {
      switch (event.key) {
        case 'ArrowLeft':
          event.preventDefault();
          handleGoBack();
          break;
        case 'ArrowRight':
          event.preventDefault();
          handleGoForward();
          break;
        case 'Home':
          event.preventDefault();
          handleGoHome();
          break;
      }
    }
  }
</script>

<svelte:window on:keydown={handleKeydown} />

<!-- Toolbar -->
<div class="help-toolbar">
  <!-- Navigation Buttons -->
  <div class="toolbar-group">
    <button 
      class="toolbar-button"
      class:disabled={!canGoBack}
      on:click={handleGoBack}
      title="Go Back (Alt+Left)"
    >
      <span class="toolbar-icon">◄</span>
    </button>
    
    <button 
      class="toolbar-button"
      class:disabled={!canGoForward}
      on:click={handleGoForward}
      title="Go Forward (Alt+Right)"
    >
      <span class="toolbar-icon">►</span>
    </button>
    
    <button 
      class="toolbar-button"
      on:click={handleStop}
      title="Stop"
    >
      <span class="toolbar-icon">■</span>
    </button>
    
    <button 
      class="toolbar-button"
      on:click={handleGoHome}
      title="Go Home (Alt+Home)"
    >
      <span class="toolbar-icon">🏠</span>
    </button>
  </div>
  
  <!-- Separator -->
  <div class="toolbar-separator"></div>
  
  <!-- Action Buttons -->
  <div class="toolbar-group">
    <button 
      class="toolbar-button"
      on:click={handleSearch}
      title="Search"
    >
      <span class="toolbar-icon">🔍</span>
    </button>
    
    <button 
      class="toolbar-button"
      on:click={handleContents}
      title="Contents"
    >
      <span class="toolbar-icon">📖</span>
    </button>
    
    <button 
      class="toolbar-button"
      on:click={handleIndex}
      title="Index"
    >
      <span class="toolbar-icon">📋</span>
    </button>
  </div>
</div>

