import { persistState, restoreState } from '../core/storage/persistence.svelte.js';
import type { DesktopItem, Position } from '../core/types.js';
import { validatePosition } from '../core/validation.js';

let items = $state<DesktopItem[]>([]);
let selectedItemId = $state<string | null>(null);
let gridEnabled = $state(true);
let initialized = false;

const selectedItem = $derived(items.find((item) => item.id === selectedItemId) ?? null);

const sortedItems = $derived(
	[...items].sort((a, b) => {
		if (!a.position || !b.position) return 0;
		if (a.position.y !== b.position.y) return a.position.y - b.position.y;
		return a.position.x - b.position.x;
	})
);

/**
 *
 */
function persist(): void {
	if (!initialized) return;

	const state = restoreState();
	state.desktop.layout = gridEnabled ? 'grid' : 'custom';
	state.desktop.icons = items.map((item) => ({
		id: item.id,
		label: item.label,
		iconClass: item.iconClass,
		type: item.type,
		position: item.position
	}));

	persistState(state);
}

export const desktop = {
	get items(): DesktopItem[] {
		return items;
	},

	get selectedItemId(): string | null {
		return selectedItemId;
	},

	get selected(): DesktopItem | null {
		return selectedItem;
	},

	get sortedItems(): DesktopItem[] {
		return sortedItems;
	},

	get gridEnabled(): boolean {
		return gridEnabled;
	},

	getItem(itemId: string): DesktopItem | null {
		return items.find((item) => item.id === itemId) ?? null;
	},

	addItem(item: DesktopItem): void {
		if (items.some((i) => i.id === item.id)) {
			throw new Error(`Desktop item with id "${item.id}" already exists`);
		}

		items.push(item);
		persist();
	},

	removeItem(itemId: string): void {
		const index = items.findIndex((item) => item.id === itemId);
		if (index === -1) return;

		items.splice(index, 1);

		if (selectedItemId === itemId) {
			selectedItemId = null;
		}
		
		persist();
	},

	moveItem(itemId: string, position: Position): void {
		validatePosition(position);

		const item = items.find((i) => i.id === itemId);
		if (!item) return;

		item.position = position;
		gridEnabled = false;
		persist();
	},

	selectItem(itemId: string): void {
		const item = items.find((i) => i.id === itemId);
		if (!item) return;

		selectedItemId = itemId;
	},

	clearSelection(): void {
		selectedItemId = null;
	},

	activate(itemId: string): void {
		const item = items.find((i) => i.id === itemId);
		if (!item) return;

		item.action();
	},

	setGridEnabled(enabled: boolean): void {
		gridEnabled = enabled;
		persist();
	},

	init(initialItems: DesktopItem[] = []): void {
		if (initialized) return;

		const state = restoreState();

		// Start with initial items (these have proper action functions!)
		items = [...initialItems];
		selectedItemId = null;
		gridEnabled = state.desktop.layout === 'grid';

		// Restore ONLY positions from localStorage for matching items
		// DO NOT add new items from localStorage (they don't have action functions)
		for (const storedIcon of state.desktop.icons) {
			const existingItem = items.find((i) => i.id === storedIcon.id);
			if (existingItem && storedIcon.position) {
				// Update position of existing item only
				existingItem.position = storedIcon.position;
			}
		}

		initialized = true;
	},

	clear(): void {
		items = [];
		selectedItemId = null;
		persist();
	},

	_reset(): void {
		items = [];
		selectedItemId = null;
		gridEnabled = true;
		initialized = false;
	}
};

