<script lang="ts">
	import { onMount, onDestroy } from 'svelte';

	// Types
	interface CommandHandler {
		execute: (args: string[], context: CommandContext) => CommandResult;
		help?: string;
		syntax?: string;
	}

	interface CommandRegistry {
		[command: string]: CommandHandler;
	}

	interface CommandContext {
		terminal: TerminalAPI;
		currentDirectory?: string;
		environment?: Record<string, string>;
	}

	interface CommandResult {
		output: string[];
		exitCode: number;
		error?: string;
	}

	interface TerminalAPI {
		write: (text: string) => void;
		writeLine: (text: string) => void;
		writeError: (text: string) => void;
		writeLines: (lines: string[]) => void;
		sendInput: (data: string) => void;
		sendKeys: (keys: string) => void;
		clear: () => void;
		reset: () => void;
		focus: () => void;
		attachStream: (stream: ReadableStream<string>) => void;
		detachStream: () => void;
		getOutput: () => string[];
		getHistory: () => string[];
		getMode: () => 'dos' | 'stream';
		executeCommand: (command: string) => Promise<CommandResult>;
		navigateHistory: (direction: number) => void;
		getCurrentInput: () => string;
	}

	interface Props {
		// Mode
		mode?: 'dos' | 'stream';

		// DOS mode settings
		prompt?: string;
		bootMessage?: string[];
		enableCommandHistory?: boolean;
		maxHistorySize?: number;

		// Stream mode settings
		stream?: ReadableStream<string>;
		enableInput?: boolean;
		onInput?: (data: string) => void;

		// Display settings
		maxLines?: number;
		cursorBlinkRate?: number;
		autoScroll?: boolean;

		// Command execution (DOS mode)
		commands?: CommandRegistry;

		// Event handlers
		onCommand?: (command: string, args: string[]) => CommandResult;
		onReady?: () => void;
		onClear?: () => void;

		// API binding
		api?: (api: TerminalAPI) => void;
	}

	let {
		mode = 'dos',
		prompt = 'C:\\>',
		bootMessage = [
			'Microsoft(R) Windows 98',
			'   (C)Copyright Microsoft Corp 1981-1999.',
			''
		],
		enableCommandHistory = true,
		maxHistorySize = 100,
		stream = undefined,
		enableInput = false,
		onInput = undefined,
		maxLines = 10000,
		cursorBlinkRate = 530,
		autoScroll = true,
		commands = {},
		onCommand = undefined,
		onReady = undefined,
		onClear = undefined,
		api = undefined
	}: Props = $props();

	// State
	let output = $state<string[]>([]);
	let currentInput = $state('');
	let commandHistory = $state<string[]>([]);
	let historyIndex = $state(-1);
	let cursorVisible = $state(true);
	let scrollElement = $state<HTMLDivElement | null>(null);
	let streamReader: ReadableStreamDefaultReader<string> | null = null;
	let cursorInterval: number | undefined;

	// Derived
	const isInputMode = $derived(mode === 'dos');
	const currentLine = $derived(isInputMode ? `${prompt}${currentInput}` : '');

	// Expose API and fire ready callback immediately for unit tests
	if (api) {
		api(createAPI());
	}
	if (onReady) {
		onReady();
	}

	// Default commands
	const defaultCommands: CommandRegistry = {
		echo: {
			execute: (args) => ({
				output: args.length > 0 ? [args.join(' ')] : [''],
				exitCode: 0
			}),
			help: 'Displays messages',
			syntax: 'echo [message]'
		}
	};

	// Merge default and custom commands
	const allCommands = $derived({ ...defaultCommands, ...commands });

	// Initialize
	onMount(async () => {
		if (mode === 'dos') {
			// Add boot message
			output.push(...bootMessage, prompt);
		}

		// Start cursor blinking
		startCursorBlink();

		// Attach stream if provided
		if (stream) {
			attachStreamInternal(stream);
		}

		// Wait for next tick to ensure DOM is ready
		await Promise.resolve();
		
		// Add keydown event listener programmatically for better test compatibility
		if (scrollElement) {
			scrollElement.addEventListener('keydown', handleKeyDown);
		}

	});

	onDestroy(() => {
		stopCursorBlink();
		if (streamReader) {
			streamReader.releaseLock();
		}
		if (scrollElement) {
			scrollElement.removeEventListener('keydown', handleKeyDown);
		}
	});

	// Cursor blinking
	function startCursorBlink() {
		cursorInterval = window.setInterval(() => {
			cursorVisible = !cursorVisible;
		}, cursorBlinkRate);
	}

	function stopCursorBlink() {
		if (cursorInterval) {
			window.clearInterval(cursorInterval);
		}
	}

	// Auto-scroll
	$effect(() => {
		if (autoScroll && scrollElement && output.length > 0) {
			setTimeout(() => {
				if (scrollElement) {
					scrollElement.scrollTop = scrollElement.scrollHeight;
				}
			}, 0);
		}
	});

	// Output management
	function addOutput(text: string) {
		const lines = text.split(/\r?\n/);
		output.push(...lines);

		// Trim if exceeds max
		if (output.length > maxLines) {
			output = output.slice(-maxLines);
		}
	}

	function addOutputLine(text: string) {
		output.push(text);

		if (output.length > maxLines) {
			output = output.slice(-maxLines);
		}
	}

	// Command execution
	async function executeCommand(input: string): Promise<CommandResult> {
		const trimmed = input.trim();
		if (!trimmed) {
			return { output: [], exitCode: 0 };
		}

		// Parse command
		const parts = trimmed.split(/\s+/);
		const command = parts[0].toLowerCase();
		const args = parts.slice(1);

		// Check for custom handler
		if (onCommand) {
			return onCommand(command, args);
		}

		// Check registered commands
		const handler = allCommands[command];
		if (handler) {
			try {
				return handler.execute(args, { terminal: createAPI() });
			} catch (error) {
				return {
					output: [`Error executing command: ${error}`],
					exitCode: 1,
					error: String(error)
				};
			}
		}

		// Unknown command
		return {
			output: [
				`'${command}' is not recognized as an internal or external`,
				`command, operable program or batch file.`
			],
			exitCode: 1,
			error: 'Command not found'
		};
	}

	// Keyboard handling (DOS mode)
	function handleKeyDown(e: KeyboardEvent) {
		if (!isInputMode) {
			if (enableInput && onInput) {
				handleStreamInput(e);
			}
			return;
		}

		// DOS mode keyboard handling
		if (e.key === 'Enter') {
			e.preventDefault();
			handleEnter();
		} else if (e.key === 'Backspace') {
			e.preventDefault();
			if (currentInput.length > 0) {
				currentInput = currentInput.slice(0, -1);
			}
		} else if (e.key === 'ArrowUp') {
			e.preventDefault();
			navigateHistory(-1);
		} else if (e.key === 'ArrowDown') {
			e.preventDefault();
			navigateHistory(1);
		} else if (e.ctrlKey && e.key === 'c') {
			e.preventDefault();
			// Cancel current input
			currentInput = '';
			addOutputLine('');
			addOutputLine(prompt);
		} else if (e.ctrlKey && e.key === 'l') {
			e.preventDefault();
			clearScreen();
		} else if (e.key.length === 1 && !e.ctrlKey && !e.altKey && !e.metaKey) {
			e.preventDefault();
			currentInput += e.key;
		}
	}

	// Handle stream mode input
	function handleStreamInput(e: KeyboardEvent) {
		if (!onInput) return;

		let data = '';

		if (e.ctrlKey && e.key.length === 1) {
			// Control characters
			const char = e.key.toLowerCase();
			if (char >= 'a' && char <= 'z') {
				data = String.fromCharCode(char.charCodeAt(0) - 96);
			}
		} else if (e.key.length === 1) {
			data = e.key;
		} else {
			switch (e.key) {
				case 'Enter':
					data = '\r';
					break;
				case 'Backspace':
					data = '\x7F';
					break;
				case 'Tab':
					data = '\t';
					break;
				case 'Escape':
					data = '\x1B';
					break;
				case 'ArrowUp':
					data = '\x1B[A';
					break;
				case 'ArrowDown':
					data = '\x1B[B';
					break;
				case 'ArrowRight':
					data = '\x1B[C';
					break;
				case 'ArrowLeft':
					data = '\x1B[D';
					break;
			}
		}

		if (data) {
			onInput(data);
		}
	}

	// Handle Enter key
	async function handleEnter() {
		const input = currentInput;

		// Add command to output
		addOutputLine(prompt + input);

		// Add to history
		if (enableCommandHistory && input.trim()) {
			commandHistory.push(input);
			if (commandHistory.length > maxHistorySize) {
				// Use splice to trim in-place instead of reassignment to preserve reactivity
				const removeCount = commandHistory.length - maxHistorySize;
				commandHistory.splice(0, removeCount);
			}
		}

		// Reset history index
		historyIndex = -1;

		// Clear input
		currentInput = '';

		// Execute command
		if (input.trim()) {
			try {
				const result = await executeCommand(input);
				result.output.forEach((line) => addOutputLine(line));
			} catch (error) {
				addOutputLine(`Error: ${error}`);
			}
		}

		// Add new prompt
		addOutputLine('');
		addOutputLine(prompt);
	}

	// History navigation
	// direction: -1 = go back in history (older), 1 = go forward in history (newer)
	function navigateHistory(direction: number) {
		if (commandHistory.length === 0) return;

		// historyIndex: -1 = current (not in history), 0+ = index in history (0 = most recent)
		const newIndex = historyIndex - direction; // Invert direction to match history index

		// Clamp to valid range: -1 (current) to commandHistory.length - 1 (oldest)
		if (newIndex < -1) {
			// Don't go below -1 (current input)
			historyIndex = -1;
			currentInput = '';
		} else if (newIndex >= commandHistory.length) {
			// Don't go beyond the oldest command
			historyIndex = commandHistory.length - 1;
			currentInput = commandHistory[0]; // Oldest command
		} else if (newIndex === -1) {
			// Back to current input (empty)
			historyIndex = -1;
			currentInput = '';
		} else {
			// Valid history index
			historyIndex = newIndex;
			currentInput = commandHistory[commandHistory.length - 1 - historyIndex];
		}
	}

	// Clear screen
	function clearScreen() {
		output = [prompt];
		if (onClear) {
			onClear();
		}
	}

	// Reset terminal
	function resetTerminal() {
		output = [];
		currentInput = '';
		commandHistory = [];
		historyIndex = -1;

		if (mode === 'dos') {
			output.push(...bootMessage, prompt);
		}
	}

	// Stream handling
	async function attachStreamInternal(s: ReadableStream<string>) {
		streamReader = s.getReader();

		try {
			while (true) {
				const { done, value } = await streamReader.read();
				if (done) break;
				addOutput(value);
			}
		} catch (error) {
			console.error('Stream error:', error);
		} finally {
			streamReader.releaseLock();
			streamReader = null;
		}
	}

	function detachStreamInternal() {
		if (streamReader) {
			streamReader.releaseLock();
			streamReader = null;
		}
	}

	// Focus terminal
	function focusTerminal() {
		if (scrollElement) {
			scrollElement.focus();
		}
	}

	// API implementation
	function createAPI(): TerminalAPI {
		return {
			write: (text: string) => addOutput(text),
			writeLine: (text: string) => addOutputLine(text),
			writeError: (text: string) => addOutputLine(text),
			writeLines: (lines: string[]) => lines.forEach((line) => addOutputLine(line)),
			sendInput: (data: string) => {
				if (onInput) onInput(data);
			},
			sendKeys: (keys: string) => {
				if (onInput) onInput(keys);
			},
			clear: clearScreen,
			reset: resetTerminal,
			focus: focusTerminal,
			attachStream: attachStreamInternal,
			detachStream: detachStreamInternal,
			getOutput: () => output,
			getHistory: () => [...commandHistory],
			getMode: () => mode,
			executeCommand: executeCommand,
			navigateHistory: navigateHistory,
			getCurrentInput: () => currentInput + '' // Force string copy to avoid closure issues
		};
	}
</script>

<div class="terminal" data-testid="terminal">
	<div
		class="terminal-screen builtin-terminal"
		data-testid="terminal-screen"
		role="textbox"
		bind:this={scrollElement}
		tabindex="0"
	>
		<div class="terminal-output" data-testid="terminal-output">
			{#each output as line, i}
				<div class="terminal-line" data-testid="terminal-line-{i}">{line}</div>
			{/each}
			{#if isInputMode}
				<div class="terminal-input-line">
					<span class="terminal-prompt" data-testid="terminal-prompt">{prompt}</span>
					<span class="terminal-input" data-testid="terminal-input">{currentInput}</span>
					<span class="terminal-cursor" data-testid="terminal-cursor" style:opacity={cursorVisible ? 1 : 0}>█</span>
				</div>
			{:else}
				<span class="terminal-cursor" data-testid="terminal-cursor" style:opacity={cursorVisible ? 1 : 0}>█</span>
			{/if}
		</div>
	</div>
</div>

<style>
	.terminal {
		display: flex;
		flex-direction: column;
		width: 100%;
		height: 100%;
		background: #000000;
		font-family: 'Courier New', monospace;
		overflow: hidden;
	}

	.terminal-screen {
		flex: 1;
		background: #000000;
		color: #aaaaaa;
		padding: 16px;
		overflow-y: auto;
		font-size: 16px;
		line-height: 19px;
		-webkit-font-smoothing: none;
		-moz-osx-font-smoothing: grayscale;
		font-smooth: never;
		outline: none;
		cursor: text;
	}

	.terminal-screen:focus {
		outline: none;
	}

	.terminal-output {
		white-space: pre-wrap;
		word-wrap: break-word;
	}

	.terminal-line {
		min-height: 19px;
	}

	.terminal-input-line {
		display: inline;
	}

	.terminal-prompt {
		color: #ffffff;
		font-weight: bold;
	}

	.terminal-input {
		color: #aaaaaa;
	}

	.terminal-cursor {
		color: #ffffff;
		background: #ffffff;
		display: inline-block;
		width: 9px;
		height: 16px;
		vertical-align: text-bottom;
	}
</style>

