import { writable } from 'svelte/store';
import type { Writable } from 'svelte/store';
import { desktop } from './desktop.svelte.js';
import { dialogManager } from './dialogManager.svelte.js';

export interface ContextMenuData {
	items: Array<{
		label?: string;
		icon?: string;
		shortcut?: string;
		hasSubmenu?: boolean;
		disabled?: boolean;
		type?: 'standard' | 'separator' | 'header';
		onclick?: () => void;
		submenu?: ContextMenuData['items'];
	}>;
	x: number;
	y: number;
	label?: string;
}

interface ContextMenuState {
	visible: boolean;
	data: ContextMenuData | null;
}

// Create the context menu store
const initialState: ContextMenuState = {
	visible: false,
	data: null
};

const contextMenuStore: Writable<ContextMenuState> = writable(initialState);

// Context menu manager class
class ContextMenuManager {
	private store = contextMenuStore;

	constructor() {
		// Prevent default context menu globally
		this.setupGlobalHandlers();
	}

	private setupGlobalHandlers() {
		// Prevent default context menu on the entire document, but allow browser menu with Ctrl+Right-click
		document.addEventListener('contextmenu', (event) => {
			// Allow normal browser context menu when Ctrl is held
			if (event.ctrlKey) {
				return; // Don't prevent default, let browser handle it
			}

			event.preventDefault();

			// Determine what was right-clicked and show appropriate menu
			const target = event.target as HTMLElement;
			this.showContextMenuForElement(target, event.clientX, event.clientY);
		});

		// Close context menu on left click outside
		document.addEventListener('click', (event) => {
			const target = event.target as HTMLElement;
			const menu = target.closest('.win98-context-menu');
			if (!menu) {
				this.close();
			}
		});

		// Close context menu on escape key
		document.addEventListener('keydown', (event) => {
			if (event.key === 'Escape') {
				this.close();
			}
		});
	}

	private showContextMenuForElement(element: HTMLElement, x: number, y: number) {
		// Check for specific context menu types
		if (element.classList.contains('desktop-icon')) {
			this.showDesktopIconContextMenu(x, y, element);
		} else if (element.classList.contains('win98-desktop')) {
			this.showDesktopContextMenu(x, y);
		} else if (element.classList.contains('win98-titlebar')) {
			this.showWindowContextMenu(x, y);
		} else if (element.classList.contains('win98-window-content')) {
			this.showWindowContentContextMenu(x, y);
		} else if (element.tagName === 'INPUT' || element.tagName === 'TEXTAREA') {
			this.showTextSelectionContextMenu(x, y);
		} else {
			// Default context menu
			this.showDefaultContextMenu(x, y);
		}
	}

	private showDesktopIconContextMenu(x: number, y: number, targetElement?: HTMLElement) {
		// Helper function to find desktop icon
		const findDesktopIcon = () => {
			if (targetElement) {
				return targetElement.closest('.desktop-icon') as HTMLElement | null;
			}

			try {
				const target = document.elementFromPoint(x, y) as HTMLElement;
				return target?.closest('.desktop-icon') as HTMLElement | null;
			} catch (e) {
				return null;
			}
		};

		const menuData: ContextMenuData = {
			items: [
				{
					label: 'Open',
					onclick: () => {
						const desktopIcon = findDesktopIcon();
						if (desktopIcon) {
							const itemId = desktopIcon.getAttribute('data-item-id');
							if (itemId) {
								desktop.activate(itemId);
							}
						}
					}
				},
				{
					label: 'Open With',
					hasSubmenu: true,
					submenu: [
						{
							label: 'Notepad',
							onclick: () => {
								const desktopIcon = findDesktopIcon();
								if (desktopIcon) {
									const itemId = desktopIcon.getAttribute('data-item-id');
									if (itemId) {
										desktop.activate(itemId);
									}
								}
							}
						},
						{
							label: 'WordPad',
							onclick: () => {
								const desktopIcon = findDesktopIcon();
								if (desktopIcon) {
									const itemId = desktopIcon.getAttribute('data-item-id');
									if (itemId) {
										desktop.activate(itemId);
									}
								}
							}
						}
					]
				},
				{ type: 'separator' },
				{
					label: 'Cut',
					shortcut: 'Ctrl+X',
					onclick: () => {
						const desktopIcon = findDesktopIcon();
						if (desktopIcon) {
							const itemId = desktopIcon.getAttribute('data-item-id');
							if (itemId) {
								desktop.selectItem(itemId);
								sessionStorage.setItem('clipboard-action', 'cut');
								sessionStorage.setItem('clipboard-item', itemId);
							}
						}
					}
				},
				{
					label: 'Copy',
					shortcut: 'Ctrl+C',
					onclick: () => {
						const desktopIcon = findDesktopIcon();
						if (desktopIcon) {
							const itemId = desktopIcon.getAttribute('data-item-id');
							if (itemId) {
								desktop.selectItem(itemId);
								sessionStorage.setItem('clipboard-action', 'copy');
								sessionStorage.setItem('clipboard-item', itemId);
							}
						}
					}
				},
				{
					label: 'Create Shortcut',
					onclick: () => {
						const desktopIcon = findDesktopIcon();
						if (desktopIcon) {
							const itemId = desktopIcon.getAttribute('data-item-id');
							if (itemId) {
								const originalItem = desktop.items.find(item => item.id === itemId);
								if (originalItem) {
									const shortcutId = `${itemId}-shortcut-${Date.now()}`;
									desktop.addItem({
										id: shortcutId,
										label: `${originalItem.label} Shortcut`,
										iconClass: originalItem.iconClass,
										type: 'shortcut' as const,
										action: originalItem.action
									});
								}
							}
						}
					}
				},
				{ type: 'separator' },
				{
					label: 'Delete',
					onclick: () => {
						const desktopIcon = findDesktopIcon();
						if (desktopIcon) {
							const itemId = desktopIcon.getAttribute('data-item-id');
							if (itemId) {
								const item = desktop.items.find(item => item.id === itemId);
								const itemName = item ? item.label : 'this item';
								if (confirm(`Are you sure you want to delete "${itemName}"?`)) {
									desktop.removeItem(itemId);
								}
							}
						}
					}
				},
				{
					label: 'Rename',
					onclick: () => {
						const desktopIcon = findDesktopIcon();
						if (desktopIcon) {
							const labelElement = desktopIcon.querySelector('.desktop-icon-label') as HTMLElement;
							const currentLabel = labelElement.textContent || '';
							const newLabel = prompt('Enter new name:', currentLabel);
							if (newLabel && newLabel !== currentLabel && newLabel.trim()) {
								const itemId = desktopIcon.getAttribute('data-item-id');
								if (itemId) {
									const item = desktop.items.find(item => item.id === itemId);
									if (item) {
										item.label = newLabel.trim();
									}
								}
							}
						}
					}
				},
				{ type: 'separator' },
				{
					label: 'Properties',
					onclick: () => {
						const desktopIcon = findDesktopIcon();
						if (desktopIcon) {
							const itemId = desktopIcon.getAttribute('data-item-id');
							if (itemId) {
								const item = desktop.items.find(item => item.id === itemId);
								if (item) {
									dialogManager.alert(
										`Properties for "${item.label}"\n\nType: ${item.type}\nIcon: ${item.iconClass}`,
										'Properties'
									);
								}
							}
						}
					}
				}
			],
			x,
			y,
			label: 'Desktop icon context menu'
		};
		this.show(menuData);
	}

	private showDesktopContextMenu(x: number, y: number) {
		const menuData: ContextMenuData = {
			items: [
				{ label: 'Arrange Icons', hasSubmenu: true, submenu: [
					{ label: 'by Name', onclick: () => console.log('Arrange by Name') },
					{ label: 'by Type', onclick: () => console.log('Arrange by Type') },
					{ label: 'by Size', onclick: () => console.log('Arrange by Size') },
					{ label: 'by Date', onclick: () => console.log('Arrange by Date') }
				]},
				{ label: 'Line up Icons', onclick: () => console.log('Line up Icons') },
				{ type: 'separator' },
				{ label: 'Refresh', onclick: () => console.log('Refresh') },
				{ label: 'Paste', onclick: () => console.log('Paste') },
				{ label: 'Paste Shortcut', onclick: () => console.log('Paste Shortcut') },
				{ type: 'separator' },
				{ label: 'New', hasSubmenu: true, submenu: [
					{ label: 'Folder', onclick: () => console.log('New Folder') },
					{ label: 'Text Document', onclick: () => console.log('New Text Document') },
					{ label: 'Shortcut', onclick: () => console.log('New Shortcut') }
				]},
				{ type: 'separator' },
				{ label: 'Properties', onclick: () => console.log('Desktop Properties') }
			],
			x,
			y,
			label: 'Desktop context menu'
		};
		this.show(menuData);
	}

	private showWindowContextMenu(x: number, y: number) {
		const menuData: ContextMenuData = {
			items: [
				{ label: 'Restore', onclick: () => console.log('Restore') },
				{ label: 'Move', onclick: () => console.log('Move') },
				{ label: 'Size', onclick: () => console.log('Size') },
				{ label: 'Minimize', onclick: () => console.log('Minimize') },
				{ label: 'Maximize', onclick: () => console.log('Maximize') },
				{ type: 'separator' },
				{ label: 'Close', shortcut: 'Alt+F4', onclick: () => console.log('Close') }
			],
			x,
			y,
			label: 'Window context menu'
		};
		this.show(menuData);
	}

	private showWindowContentContextMenu(x: number, y: number) {
		const menuData: ContextMenuData = {
			items: [
				{ label: 'Cut', shortcut: 'Ctrl+X', onclick: () => console.log('Cut') },
				{ label: 'Copy', shortcut: 'Ctrl+C', onclick: () => console.log('Copy') },
				{ label: 'Paste', shortcut: 'Ctrl+V', onclick: () => console.log('Paste') },
				{ type: 'separator' },
				{ label: 'Select All', shortcut: 'Ctrl+A', onclick: () => console.log('Select All') }
			],
			x,
			y,
			label: 'Window content context menu'
		};
		this.show(menuData);
	}

	private showTextSelectionContextMenu(x: number, y: number) {
		const menuData: ContextMenuData = {
			items: [
				{ label: 'Cut', shortcut: 'Ctrl+X', onclick: () => console.log('Cut') },
				{ label: 'Copy', shortcut: 'Ctrl+C', onclick: () => console.log('Copy') },
				{ label: 'Paste', shortcut: 'Ctrl+V', onclick: () => console.log('Paste') },
				{ type: 'separator' },
				{ label: 'Delete', onclick: () => console.log('Delete') },
				{ type: 'separator' },
				{ label: 'Select All', shortcut: 'Ctrl+A', onclick: () => console.log('Select All') }
			],
			x,
			y,
			label: 'Text selection context menu'
		};
		this.show(menuData);
	}

	private showDefaultContextMenu(x: number, y: number) {
		const menuData: ContextMenuData = {
			items: [
				{ label: 'Cut', shortcut: 'Ctrl+X', onclick: () => console.log('Cut') },
				{ label: 'Copy', shortcut: 'Ctrl+C', onclick: () => console.log('Copy') },
				{ label: 'Paste', shortcut: 'Ctrl+V', onclick: () => console.log('Paste') },
				{ type: 'separator' },
				{ label: 'Select All', shortcut: 'Ctrl+A', onclick: () => console.log('Select All') }
			],
			x,
			y,
			label: 'Default context menu'
		};
		this.show(menuData);
	}

	show(data: ContextMenuData) {
		this.store.set({
			visible: true,
			data
		});
	}

	close() {
		this.store.set({
			visible: false,
			data: null
		});
	}

	hideContextMenu() {
		this.close();
	}

	// Public method to show custom context menu
	showCustom(items: ContextMenuData['items'], x: number, y: number, label?: string) {
		this.show({
			items,
			x,
			y,
			label: label || 'Custom context menu'
		});
	}

	// Get the current store for components to subscribe to
	getStore() {
		return this.store;
	}
}

// Create and export the singleton instance
export const contextMenuManager = new ContextMenuManager();

// Export the store for components to use
export const contextMenu = contextMenuManager.getStore();
