  /**
   * Calculate content checksum
   * 
   * @param content - Content to calculate checksum for
   * @returns Content checksum
   */
  private calculateChecksum(content: string): string {
    // Simple hash function for content integrity
    let hash = 0;
    for (let i = 0; i < content.length; i++) {
      const char = content.charCodeAt(i);
      hash = ((hash << 5) - hash) + char;
      hash = hash & hash; // Convert to 32-bit integer
    }
    return hash.toString(16);
  }

  /**
   * Extract table of contents from content
   * 
   * @param content - Content to extract TOC from
   * @returns Table of contents
   */
  private extractTableOfContents(content: string): TableOfContents {
    const items: TOCItem[] = [];
    const lines = content.split('\n');
    
    for (const line of lines) {
      const headerMatch = line.match(/^(#{1,6})\s+(.+)$/);
      if (headerMatch) {
        const level = headerMatch[1].length;
        const text = headerMatch[2];
        const id = this.generateHeadingId(text);
        
        items.push({
          id,
          text,
          level,
          children: []
        });
      }
    }
    
    return { items };
  }

  /**
   * Extract links from content
   * 
   * @param content - Content to extract links from
   * @returns Array of content links
   */
  private extractLinks(content: string): ContentLink[] {
    const links: ContentLink[] = [];
    const linkRegex = /\[([^\]]+)\]\(([^)]+)\)/g;
    let match;
    
    while ((match = linkRegex.exec(content)) !== null) {
      const text = match[1];
      const url = match[2];
      const type = url.startsWith('http') ? 'external' : 'internal';
      
      links.push({
        text,
        url,
        type
      });
    }
    
    return links;
  }

  /**
   * Extract images from content
   * 
   * @param content - Content to extract images from
   * @returns Array of content images
   */
  private extractImages(content: string): ContentImage[] {
    const images: ContentImage[] = [];
    const imageRegex = /!\[([^\]]*)\]\(([^)]+)\)/g;
    let match;
    
    while ((match = imageRegex.exec(content)) !== null) {
      const alt = match[1];
      const src = match[2];
      
      images.push({
        src,
        alt
      });
    }
    
    return images;
  }

  /**
   * Extract code blocks from content
   * 
   * @param content - Content to extract code blocks from
   * @returns Array of code blocks
   */
  private extractCodeBlocks(content: string): CodeBlock[] {
    const codeBlocks: CodeBlock[] = [];
    const codeBlockRegex = /```(\w+)?\n([\s\S]*?)```/g;
    let match;
    
    while ((match = codeBlockRegex.exec(content)) !== null) {
      const language = match[1] || 'text';
      const code = match[2];
      
      codeBlocks.push({
        language,
        code
      });
    }
    
    return codeBlocks;
  }

  /**
   * Extract tables from content
   * 
   * @param content - Content to extract tables from
   * @returns Array of tables
   */
  private extractTables(content: string): Table[] {
    const tables: Table[] = [];
    const lines = content.split('\n');
    let currentTable: Table | null = null;
    
    for (const line of lines) {
      if (line.includes('|')) {
        const cells = line.split('|').map(cell => cell.trim()).filter(cell => cell);
        
        if (!currentTable) {
          currentTable = {
            headers: cells,
            rows: []
          };
        } else {
          currentTable.rows.push(cells);
        }
      } else if (currentTable) {
        tables.push(currentTable);
        currentTable = null;
      }
    }
    
    if (currentTable) {
      tables.push(currentTable);
    }
    
    return tables;
  }

  /**
   * Generate topic ID from title
   * 
   * @param title - Topic title
   * @returns Generated topic ID
   */
  private generateTopicId(title: string): string {
    return title
      .toLowerCase()
      .replace(/[^a-z0-9\s-]/g, '')
      .replace(/\s+/g, '-')
      .replace(/-+/g, '-')
      .replace(/^-|-$/g, '');
  }

  /**
   * Generate heading ID from text
   * 
   * @param text - Heading text
   * @returns Generated heading ID
   */
  private generateHeadingId(text: string): string {
    return text
      .toLowerCase()
      .replace(/[^a-z0-9\s-]/g, '')
      .replace(/\s+/g, '-')
      .replace(/-+/g, '-')
      .replace(/^-|-$/g, '');
  }

