<script lang="ts">
	type MenuItemType = 'standard' | 'separator' | 'header';

	interface Props {
		label?: string;
		icon?: string;
		shortcut?: string;
		hasSubmenu?: boolean;
		disabled?: boolean;
		type?: MenuItemType;
		onclick?: () => void;
	}

	let { 
		label = '', 
		icon, 
		shortcut, 
		hasSubmenu = false, 
		disabled = false, 
		type = 'standard',
		onclick
	}: Props = $props();

	// Handle click events
	function handleClick() {
		if (!disabled && type === 'standard' && onclick) {
			onclick();
		}
	}

	// Determine if item is interactive
	let isInteractive = $derived(() => {
		return !disabled && type === 'standard';
	});

	// Determine role based on type
	let role = $derived(() => {
		switch (type) {
			case 'separator':
				return 'separator';
			case 'header':
				return 'presentation';
			default:
				return 'menuitem';
		}
	});
</script>

<div 
	class="win98-menu-item"
	class:win98-menu-item--separator={type === 'separator'}
	class:win98-menu-item--header={type === 'header'}
	class:win98-menu-item--disabled={disabled}
	role={role()}
	tabindex={isInteractive() ? 0 : undefined}
	aria-label={label}
	aria-disabled={disabled}
	onclick={handleClick}
>
	{#if type === 'separator'}
		<!-- Separator: just a horizontal line -->
	{:else if type === 'header'}
		<!-- Header: bold text only -->
		<span class="win98-menu-item__label">{label}</span>
	{:else}
		<!-- Standard item: icon + label + shortcut + arrow -->
		{#if icon}
			<img 
				class="win98-menu-item__icon"
				src={icon}
				alt=""
				draggable="false"
			/>
		{/if}
		
		<span class="win98-menu-item__label">{label}</span>
		
		{#if shortcut}
			<span class="win98-menu-item__shortcut">{shortcut}</span>
		{/if}
		
		{#if hasSubmenu}
			<span class="win98-menu-item__arrow">►</span>
		{/if}
	{/if}
</div>

<style lang="scss">
	.win98-menu-item {
		/* Dimensions */
		height: 22px;
		padding: 2px 4px;
		
		/* Layout */
		display: flex;
		align-items: center;
		
		/* Colors */
		background: var(--menu-item-bg, #C0C0C0);
		color: var(--menu-item-text, #000000);
		
		/* Typography */
		font-family: 'MS Sans Serif', sans-serif;
		font-size: 11px;
		font-weight: 400;
		-webkit-font-smoothing: none;
		-moz-osx-font-smoothing: grayscale;
		text-rendering: optimizeSpeed;
		
		/* Interaction */
		cursor: pointer;
		user-select: none;
		
		/* Icon */
		&__icon {
			/* Dimensions */
			width: 16px;
			height: 16px;
			margin-right: 4px;
			
			/* Rendering - pixelated for Windows 98 style */
			image-rendering: pixelated;
			image-rendering: -moz-crisp-edges;
			image-rendering: crisp-edges;
		}
		
		/* Label text */
		&__label {
			flex: 1;
			overflow: hidden;
			text-overflow: ellipsis;
			white-space: nowrap;
		}
		
		/* Keyboard shortcut */
		&__shortcut {
			margin-left: auto;
			margin-right: 8px;
			color: #808080;
		}
		
		/* Submenu arrow */
		&__arrow {
			margin-left: auto;
		}
		
		/* Hover state */
		&:hover:not(.win98-menu-item--disabled):not(.win98-menu-item--separator):not(.win98-menu-item--header) {
			background: var(--menu-item-hover-bg, #000080);
			color: var(--menu-item-hover-text, #FFFFFF);
		}
		
		/* Separator type */
		&--separator {
			height: 1px;
			background: #808080;
			cursor: default;
		}
		
		/* Header type */
		&--header {
			font-weight: 700;
			cursor: default;
		}
		
		/* Disabled state */
		&--disabled {
			color: var(--menu-item-disabled-text, #808080);
			text-shadow: 1px 1px 0 var(--menu-item-disabled-shadow, #FFFFFF);
			cursor: not-allowed;
		}
		
		/* Focus state */
		&:focus-visible {
			outline: 1px dotted var(--menu-item-text, #000000);
			outline-offset: -2px;
		}
	}
</style>

