<!--
  Windows 98 F1 Help System - Toolbar Component
  
  This component provides the main toolbar with navigation buttons, search box,
  and other commonly used functions following Windows 98 toolbar conventions.
  
  @fileoverview Toolbar component for help system
-->

<script lang="ts">
  import { createEventDispatcher } from 'svelte';
  import type { 
    HelpSystemManager, 
    HelpTopic
  } from '../types.js';

  // Props
  let { 
    helpSystem,
    currentTopic = $bindable(null),
    canGoBack = $bindable(false),
    canGoForward = $bindable(false)
  }: {
    helpSystem: HelpSystemManager;
    currentTopic?: HelpTopic | null;
    canGoBack?: boolean;
    canGoForward?: boolean;
  } = $props();

  // State
  let searchQuery = '';
  let showSearchSuggestions = false;
  let searchSuggestions: string[] = [];
  let selectedSuggestionIndex = -1;

  // Event dispatcher
  const dispatch = createEventDispatcher();

  // Toolbar button configurations
  const toolbarButtons = [
    {
      id: 'back',
      label: 'Back',
      icon: '◀',
      disabled: !canGoBack,
      action: () => dispatch('go-back'),
      tooltip: 'Go back (Alt+Left)'
    },
    {
      id: 'forward',
      label: 'Forward',
      icon: '▶',
      disabled: !canGoForward,
      action: () => dispatch('go-forward'),
      tooltip: 'Go forward (Alt+Right)'
    },
    {
      id: 'home',
      label: 'Home',
      icon: '🏠',
      disabled: false,
      action: () => dispatch('go-home'),
      tooltip: 'Go to home topic (Alt+Home)'
    },
    {
      id: 'separator1',
      type: 'separator'
    },
    {
      id: 'bookmark',
      label: 'Bookmark',
      icon: '⭐',
      disabled: !currentTopic,
      action: () => addBookmark(),
      tooltip: 'Add bookmark (Ctrl+D)'
    },
    {
      id: 'print',
      label: 'Print',
      icon: '🖨️',
      disabled: !currentTopic,
      action: () => printTopic(),
      tooltip: 'Print topic (Ctrl+P)'
    },
    {
      id: 'separator2',
      type: 'separator'
    },
    {
      id: 'refresh',
      label: 'Refresh',
      icon: '🔄',
      disabled: false,
      action: () => refresh(),
      tooltip: 'Refresh (F5)'
    }
  ];

  // Search handlers
  async function handleSearchInput(event: Event) {
    const target = event.target as HTMLInputElement;
    searchQuery = target.value;
    
    if (searchQuery.length >= 2) {
      try {
        searchSuggestions = await helpSystem.getSearchSuggestions(searchQuery);
        showSearchSuggestions = searchSuggestions.length > 0;
        selectedSuggestionIndex = -1;
      } catch (error) {
        console.warn('Failed to get search suggestions:', error);
        searchSuggestions = [];
        showSearchSuggestions = false;
      }
    } else {
      searchSuggestions = [];
      showSearchSuggestions = false;
    }
  }

  async function handleSearchSubmit(event: Event) {
    event.preventDefault();
    if (searchQuery.trim()) {
      dispatch('search', { query: searchQuery.trim() });
      showSearchSuggestions = false;
    }
  }

  function handleSearchKeydown(event: KeyboardEvent) {
    if (!showSearchSuggestions) return;

    switch (event.key) {
      case 'ArrowDown':
        event.preventDefault();
        selectedSuggestionIndex = Math.min(selectedSuggestionIndex + 1, searchSuggestions.length - 1);
        break;
      case 'ArrowUp':
        event.preventDefault();
        selectedSuggestionIndex = Math.max(selectedSuggestionIndex - 1, -1);
        break;
      case 'Enter':
        event.preventDefault();
        if (selectedSuggestionIndex >= 0) {
          searchQuery = searchSuggestions[selectedSuggestionIndex];
          dispatch('search', { query: searchQuery });
        } else {
          dispatch('search', { query: searchQuery.trim() });
        }
        showSearchSuggestions = false;
        break;
      case 'Escape':
        showSearchSuggestions = false;
        selectedSuggestionIndex = -1;
        break;
    }
  }

  function selectSuggestion(suggestion: string) {
    searchQuery = suggestion;
    dispatch('search', { query: suggestion });
    showSearchSuggestions = false;
  }

  function clearSearch() {
    searchQuery = '';
    showSearchSuggestions = false;
    searchSuggestions = [];
    selectedSuggestionIndex = -1;
  }

  // Button handlers
  function addBookmark() {
    if (currentTopic) {
      dispatch('bookmark', { topicId: currentTopic.id });
    }
  }

  function printTopic() {
    if (currentTopic) {
      // In a real implementation, this would open a print dialog
      window.print();
    }
  }

  async function refresh() {
    try {
      await helpSystem.refresh();
    } catch (error) {
      console.error('Failed to refresh:', error);
    }
  }

  // Close suggestions when clicking outside
  function handleClickOutside(event: MouseEvent) {
    if (!(event.target as Element).closest('.search-container')) {
      showSearchSuggestions = false;
    }
  }

  // Keyboard shortcuts
  function handleKeydown(event: KeyboardEvent) {
    if (event.ctrlKey || event.altKey) {
      switch (event.key) {
        case 'd':
          if (event.ctrlKey) {
            event.preventDefault();
            addBookmark();
          }
          break;
        case 'p':
          if (event.ctrlKey) {
            event.preventDefault();
            printTopic();
          }
          break;
        case 'f':
          if (event.ctrlKey) {
            event.preventDefault();
            // Focus search box
            const searchInput = document.querySelector('.search-input') as HTMLInputElement;
            if (searchInput) {
              searchInput.focus();
            }
          }
          break;
      }
    }

    // Function keys
    switch (event.key) {
      case 'F5':
        event.preventDefault();
        refresh();
        break;
    }

    // Arrow keys for navigation
    if (event.altKey) {
      switch (event.key) {
        case 'ArrowLeft':
          event.preventDefault();
          if (canGoBack) {
            dispatch('go-back');
          }
          break;
        case 'ArrowRight':
          event.preventDefault();
          if (canGoForward) {
            dispatch('go-forward');
          }
          break;
        case 'Home':
          event.preventDefault();
          dispatch('go-home');
          break;
      }
    }
  }
</script>

<svelte:window on:keydown={handleKeydown} on:click={handleClickOutside} />

<div class="toolbar">
  <!-- Navigation Buttons -->
  <div class="toolbar-section">
    {#each toolbarButtons as button}
      {#if button.type === 'separator'}
        <div class="toolbar-separator"></div>
      {:else}
        <button
          class="toolbar-button"
          class:disabled={button.disabled}
          on:click={button.action}
          title={button.tooltip}
        >
          <span class="toolbar-icon">{button.icon}</span>
          <span class="toolbar-label">{button.label}</span>
        </button>
      {/if}
    {/each}
  </div>

  <!-- Search Section -->
  <div class="toolbar-section search-container">
    <form on:submit={handleSearchSubmit} class="search-form">
      <div class="search-input-container">
        <input
          type="text"
          class="search-input"
          placeholder="Search help topics..."
          bind:value={searchQuery}
          on:input={handleSearchInput}
          on:keydown={handleSearchKeydown}
        />
        {#if searchQuery}
          <button
            type="button"
            class="search-clear"
            on:click={clearSearch}
            title="Clear search"
          >
            ×
          </button>
        {/if}
      </div>
      
      <!-- Search Suggestions -->
      {#if showSearchSuggestions && searchSuggestions.length > 0}
        <div class="search-suggestions">
          {#each searchSuggestions as suggestion, index}
            <button
              type="button"
              class="search-suggestion"
              class:selected={index === selectedSuggestionIndex}
              on:click={() => selectSuggestion(suggestion)}
            >
              {suggestion}
            </button>
          {/each}
        </div>
      {/if}
    </form>
  </div>

  <!-- Status Section -->
  <div class="toolbar-section status-section">
    <div class="status-indicators">
      {#if currentTopic}
        <span class="status-item" title="Current topic">
          📄 {currentTopic.title}
        </span>
      {/if}
      
      {#if helpSystem}
        <span class="status-item" title="System status">
          {helpSystem.isSystemInitialized() ? '🟢' : '🟡'} 
          {helpSystem.isSystemInitialized() ? 'Ready' : 'Loading...'}
        </span>
      {/if}
    </div>
  </div>
</div>

<style>
  .toolbar {
    display: flex;
    align-items: center;
    background: #c0c0c0;
    border-bottom: 1px inset #c0c0c0;
    padding: 2px 4px;
    gap: 4px;
    font-size: 11px;
    user-select: none;
  }

  .toolbar-section {
    display: flex;
    align-items: center;
    gap: 2px;
  }

  .toolbar-button {
    display: flex;
    align-items: center;
    gap: 4px;
    padding: 2px 6px;
    border: 1px outset #c0c0c0;
    background: #c0c0c0;
    color: black;
    cursor: pointer;
    font-size: 11px;
    font-family: 'MS Sans Serif', sans-serif;
    white-space: nowrap;
  }

  .toolbar-button:hover:not(.disabled) {
    background: #d4d0c8;
  }

  .toolbar-button:active:not(.disabled) {
    border: 1px inset #c0c0c0;
  }

  .toolbar-button.disabled {
    color: #808080;
    cursor: default;
    background: #c0c0c0;
  }

  .toolbar-icon {
    font-size: 12px;
    line-height: 1;
  }

  .toolbar-label {
    font-size: 11px;
  }

  .toolbar-separator {
    width: 1px;
    height: 20px;
    background: #808080;
    margin: 0 2px;
  }

  /* Search Section */
  .search-container {
    position: relative;
    flex: 1;
    max-width: 300px;
  }

  .search-form {
    width: 100%;
  }

  .search-input-container {
    position: relative;
    display: flex;
    align-items: center;
  }

  .search-input {
    width: 100%;
    padding: 2px 4px;
    border: 1px inset #c0c0c0;
    background: white;
    color: black;
    font-size: 11px;
    font-family: 'MS Sans Serif', sans-serif;
  }

  .search-input:focus {
    outline: 1px dotted #000;
  }

  .search-clear {
    position: absolute;
    right: 2px;
    width: 16px;
    height: 16px;
    border: none;
    background: transparent;
    color: #666;
    cursor: pointer;
    font-size: 12px;
    display: flex;
    align-items: center;
    justify-content: center;
  }

  .search-clear:hover {
    color: #000;
    background: #e0e0e0;
  }

  .search-suggestions {
    position: absolute;
    top: 100%;
    left: 0;
    right: 0;
    background: #c0c0c0;
    border: 1px outset #c0c0c0;
    max-height: 200px;
    overflow-y: auto;
    z-index: 1000;
    box-shadow: 2px 2px 4px rgba(0, 0, 0, 0.3);
  }

  .search-suggestion {
    display: block;
    width: 100%;
    padding: 4px 8px;
    border: none;
    background: transparent;
    color: black;
    cursor: pointer;
    font-size: 11px;
    font-family: 'MS Sans Serif', sans-serif;
    text-align: left;
  }

  .search-suggestion:hover,
  .search-suggestion.selected {
    background: #a6caf0;
  }

  /* Status Section */
  .status-section {
    margin-left: auto;
  }

  .status-indicators {
    display: flex;
    align-items: center;
    gap: 8px;
  }

  .status-item {
    font-size: 10px;
    color: #666;
    white-space: nowrap;
  }

  /* Responsive adjustments */
  @media (max-width: 600px) {
    .toolbar-label {
      display: none;
    }
    
    .toolbar-icon {
      font-size: 14px;
    }
    
    .search-container {
      max-width: 200px;
    }
    
    .status-item {
      font-size: 9px;
    }
  }
</style>
