<script lang="ts">
	import { theme } from '../stores/theme.svelte.js';
	import { audio } from '../stores/audio.svelte.js';
	import { desktop } from '../stores/desktop.svelte.js';
	import Button from '../components/controls/Button.svelte';
	import Checkbox from '../components/controls/Checkbox.svelte';

	interface Props {
		windowId: string;
	}

	let { windowId }: Props = $props();

	let currentTheme = $state(theme.current);
	let currentVolume = $state(audio.volume * 100);
	let isMuted = $state(audio.muted);
	let gridEnabled = $state(desktop.gridEnabled);

	function handleThemeChange() {
		theme.toggle();
		currentTheme = theme.current;
	}

	function handleVolumeChange(value: number) {
		audio.setVolume(value / 100);
		currentVolume = value;
	}

	function handleMuteChange(checked: boolean) {
		if (checked !== audio.muted) {
			audio.toggleMute();
		}
		isMuted = checked;
	}

	function handleGridToggle(checked: boolean) {
		desktop.setGridEnabled(checked);
		gridEnabled = checked;
	}
</script>

<div class="settings-window">
	<div class="settings-section">
		<h2 class="section-title">Display</h2>
		<div class="setting-item">
			<label class="setting-label">Theme:</label>
			<div class="setting-control">
				<span class="theme-indicator">{currentTheme === 'dark' ? 'Dark' : 'Light'}</span>
				<Button label="Toggle Theme" onclick={handleThemeChange} />
			</div>
		</div>
	</div>

	<div class="settings-divider"></div>

	<div class="settings-section">
		<h2 class="section-title">Audio</h2>
		<div class="setting-item">
			<label class="setting-label">Volume:</label>
			<div class="setting-control">
				<input
					type="range"
					min="0"
					max="100"
					value={currentVolume}
					oninput={(e) => handleVolumeChange(Number((e.target as HTMLInputElement).value))}
					class="volume-slider"
					disabled={isMuted}
				/>
				<span class="volume-value">{Math.round(currentVolume)}%</span>
			</div>
		</div>
		<div class="setting-item">
			<Checkbox
				checked={isMuted}
				label="Mute"
				onchange={handleMuteChange}
			/>
		</div>
	</div>

	<div class="settings-divider"></div>

	<div class="settings-section">
		<h2 class="section-title">Desktop</h2>
		<div class="setting-item">
			<Checkbox
				checked={gridEnabled}
				label="Auto-arrange icons in grid"
				onchange={handleGridToggle}
			/>
		</div>
	</div>

	<div class="settings-footer">
		<p class="settings-note">Settings are automatically saved</p>
	</div>
</div>

