<script lang="ts">
	interface MessageBoxButton {
		label: string;
		action: () => void;
	}

	interface Props {
		title: string;
		message: string;
		type: 'error' | 'warning' | 'info' | 'question';
		buttons: MessageBoxButton[];
		onclose: () => void;
	}

	let { title, message, type, buttons, onclose }: Props = $props();

	const iconMap = {
		error: '⚠️',
		warning: '⚠️',
		info: 'ℹ️',
		question: '❓'
	};

	function handleButtonClick(button: MessageBoxButton) {
		button.action();
		onclose();
	}
</script>

<div class="messagebox-backdrop" onclick={onclose}>
	<div class="messagebox" onclick={(e) => e.stopPropagation()} role="dialog" aria-label={title}>
		<div class="messagebox-titlebar">
			<div class="messagebox-title">
				<span class="messagebox-title-text">{title}</span>
			</div>
			<button
				type="button"
				class="messagebox-close"
				onclick={onclose}
				aria-label="Close"
			>
				<span class="close-icon">×</span>
			</button>
		</div>

		<div class="messagebox-content">
			<div class="messagebox-icon">{iconMap[type]}</div>
			<div class="messagebox-message">{message}</div>
		</div>

		<div class="messagebox-buttons">
			{#each buttons as button}
				<button
					type="button"
					class="messagebox-button"
					onclick={() => handleButtonClick(button)}
				>
					{button.label}
				</button>
			{/each}
		</div>
	</div>
</div>

