<!--
  Windows 98 F1 Help System - Topic Tree Component
  
  This component displays the hierarchical topic tree in a Windows 98 style
  tree view with expand/collapse functionality and navigation.
  
  @fileoverview Topic tree component for help system
-->

<script lang="ts">
  import { createEventDispatcher, onMount } from 'svelte';
  import type { 
    HelpSystemManager, 
    HelpTopic
  } from '../types.js';
  import TreeNode from './TreeNode.svelte';

  // Props
  let { 
    helpSystem,
    currentTopic = $bindable(null)
  }: {
    helpSystem: HelpSystemManager;
    currentTopic?: HelpTopic | null;
  } = $props();

  // State
  let topics: HelpTopic[] = [];
  let expandedNodes: Set<string> = new Set();
  let isLoading = true;
  let error: string | null = null;

  // Event dispatcher
  const dispatch = createEventDispatcher();

  onMount(async () => {
    try {
      await loadTopics();
    } catch (err) {
      error = err instanceof Error ? err.message : 'Failed to load topics';
    } finally {
      isLoading = false;
    }
  });

  async function loadTopics() {
    try {
      topics = helpSystem.getTopicTree();
      
      // Auto-expand nodes that contain the current topic
      if (currentTopic) {
        expandToTopic(currentTopic.id);
      }
    } catch (err) {
      throw new Error(`Failed to load topics: ${err instanceof Error ? err.message : 'Unknown error'}`);
    }
  }

  function expandToTopic(topicId: string) {
    // Find the path to the topic and expand all parent nodes
    const path = findTopicPath(topics, topicId);
    for (const nodeId of path) {
      expandedNodes.add(nodeId);
    }
  }

  function findTopicPath(nodes: HelpTopic[], targetId: string, currentPath: string[] = []): string[] {
    for (const node of nodes) {
      const newPath = [...currentPath, node.id];
      
      if (node.id === targetId) {
        return newPath;
      }
      
      if (node.children && node.children.length > 0) {
        const childPath = findTopicPath(node.children, targetId, newPath);
        if (childPath.length > 0) {
          return childPath;
        }
      }
    }
    return [];
  }

  function toggleNode(nodeId: string) {
    if (expandedNodes.has(nodeId)) {
      expandedNodes.delete(nodeId);
    } else {
      expandedNodes.add(nodeId);
    }
    expandedNodes = expandedNodes; // Trigger reactivity
  }

  function isExpanded(nodeId: string): boolean {
    return expandedNodes.has(nodeId);
  }

  function hasChildren(node: HelpTopic): boolean {
    return node.children && node.children.length > 0;
  }

  function handleTopicClick(topic: HelpTopic) {
    dispatch('navigate', { topicId: topic.id });
  }

  function handleTopicKeydown(event: KeyboardEvent, topic: HelpTopic) {
    switch (event.key) {
      case 'Enter':
      case ' ':
        event.preventDefault();
        handleTopicClick(topic);
        break;
      case 'ArrowRight':
        if (hasChildren(topic) && !isExpanded(topic.id)) {
          event.preventDefault();
          toggleNode(topic.id);
        }
        break;
      case 'ArrowLeft':
        if (hasChildren(topic) && isExpanded(topic.id)) {
          event.preventDefault();
          toggleNode(topic.id);
        }
        break;
    }
  }

  function expandAll() {
    const allNodeIds = new Set<string>();
    collectAllNodeIds(topics, allNodeIds);
    expandedNodes = allNodeIds;
  }

  function collapseAll() {
    expandedNodes.clear();
  }

  function collectAllNodeIds(nodes: HelpTopic[], nodeIds: Set<string>) {
    for (const node of nodes) {
      nodeIds.add(node.id);
      if (node.children && node.children.length > 0) {
        collectAllNodeIds(node.children, nodeIds);
      }
    }
  }

  function getNodeIcon(topic: HelpTopic): string {
    if (hasChildren(topic)) {
      return isExpanded(topic.id) ? '📂' : '📁';
    } else {
      return '📄';
    }
  }

  // Refresh topics when current topic changes
  $effect(() => {
    if (currentTopic) {
      expandToTopic(currentTopic.id);
    }
  });
</script>

<div class="topic-tree">
  <!-- Tree Header -->
  <div class="tree-header">
    <div class="tree-title">Contents</div>
    <div class="tree-controls">
      <button 
        class="tree-control-button" 
        on:click={expandAll}
        title="Expand all"
      >
        +
      </button>
      <button 
        class="tree-control-button" 
        on:click={collapseAll}
        title="Collapse all"
      >
        -
      </button>
    </div>
  </div>

  <!-- Tree Content -->
  <div class="tree-content">
    {#if isLoading}
      <div class="tree-loading">
        <div class="loading-spinner"></div>
        <div class="loading-text">Loading topics...</div>
      </div>
    {:else if error}
      <div class="tree-error">
        <div class="error-icon">⚠️</div>
        <div class="error-text">{error}</div>
        <button class="retry-button" on:click={() => { isLoading = true; error = null; loadTopics(); }}>
          Retry
        </button>
      </div>
    {:else}
      <div class="tree-nodes">
        {#each topics as topic}
          <TreeNode 
            {topic} 
            {currentTopic}
            {expandedNodes}
            {isExpanded}
            {hasChildren}
            {toggleNode}
            {handleTopicClick}
            {handleTopicKeydown}
            {getNodeIcon}
            level={0}
          />
        {/each}
      </div>
    {/if}
  </div>
</div>


