<!--
  Windows 98 F1 Help System - Favorites Panel Component
  
  This component displays bookmarked topics in the Favorites tab,
  allowing users to manage and navigate their bookmarks.
  
  @fileoverview Favorites panel component for help system
-->

<script lang="ts">
  import { createEventDispatcher, onMount } from 'svelte';
  import type { HelpSystemManager, HelpBookmark, HelpTopic } from '../index.js';

  // Props
  let { helpManager }: { helpManager: HelpSystemManager } = $props();

  // State
  let bookmarks: HelpBookmark[] = $state([]);
  let bookmarkTopics: Map<string, HelpTopic> = $state(new Map());
  let isLoading = $state(true);
  let error: string | null = $state(null);
  let sortBy: 'title' | 'dateAdded' | 'category' = $state('title');
  let sortOrder: 'asc' | 'desc' = $state('asc');
  let filterCategory: string | null = $state(null);

  // Event dispatcher
  const dispatch = createEventDispatcher();

  // Load bookmarks and topics
  async function loadBookmarks() {
    try {
      isLoading = true;
      error = null;
      
      const bookmarkList = helpManager.getBookmarks();
      bookmarks = bookmarkList;
      
      // Load topic details for bookmarks
      bookmarkTopics.clear();
      for (const bookmark of bookmarkList) {
        const topic = helpManager.getTopic(bookmark.topicId);
        if (topic) {
          bookmarkTopics.set(bookmark.topicId, topic);
        }
      }
      
    } catch (err) {
      error = `Failed to load bookmarks: ${err instanceof Error ? err.message : 'Unknown error'}`;
      console.error('Error loading bookmarks:', err);
    } finally {
      isLoading = false;
    }
  }

  // Handle bookmark click
  function handleBookmarkClick(bookmark: HelpBookmark) {
    dispatch('topic-select', bookmark.topicId);
  }

  // Handle bookmark remove
  function handleRemoveBookmark(bookmark: HelpBookmark) {
    dispatch('bookmark-toggle', bookmark.topicId);
  }

  // Handle sort change
  function handleSortChange(newSortBy: 'title' | 'dateAdded' | 'category') {
    if (sortBy === newSortBy) {
      sortOrder = sortOrder === 'asc' ? 'desc' : 'asc';
    } else {
      sortBy = newSortBy;
      sortOrder = 'asc';
    }
  }

  // Handle category filter
  function handleCategoryFilter(category: string | null) {
    filterCategory = category;
  }

  // Handle clear all bookmarks
  function handleClearAll() {
    if (confirm('Are you sure you want to remove all bookmarks?')) {
      for (const bookmark of bookmarks) {
        helpManager.removeBookmark(bookmark.topicId);
      }
      loadBookmarks();
    }
  }

  // Handle keyboard navigation
  function handleKeydown(event: KeyboardEvent, bookmark: HelpBookmark) {
    if (event.key === 'Enter' || event.key === ' ') {
      event.preventDefault();
      handleBookmarkClick(bookmark);
    } else if (event.key === 'Delete') {
      event.preventDefault();
      handleRemoveBookmark(bookmark);
    }
  }

   // Get sorted and filtered bookmarks
   let sortedBookmarks = $derived((() => {
     let filtered = bookmarks;
    
    // Filter by category
    if (filterCategory) {
      filtered = filtered.filter(bookmark => {
        const topic = bookmarkTopics.get(bookmark.topicId);
        return topic?.category === filterCategory;
      });
    }
    
    // Sort bookmarks
    return filtered.sort((a, b) => {
      let comparison = 0;
      
      switch (sortBy) {
        case 'title':
          comparison = a.title.localeCompare(b.title);
          break;
        case 'dateAdded':
          comparison = a.dateAdded.getTime() - b.dateAdded.getTime();
          break;
        case 'category':
          const topicA = bookmarkTopics.get(a.topicId);
          const topicB = bookmarkTopics.get(b.topicId);
          const categoryA = topicA?.category || '';
          const categoryB = topicB?.category || '';
          comparison = categoryA.localeCompare(categoryB);
          break;
      }
      
      return sortOrder === 'desc' ? -comparison : comparison;
    });
  })());

  // Get available categories
  let categories = $derived(Array.from(new Set(
    bookmarks
      .map(bookmark => bookmarkTopics.get(bookmark.topicId)?.category)
      .filter(Boolean)
  )).sort());

  // Initialize component
  onMount(() => {
    loadBookmarks();
    
    // Listen for bookmark changes
    const unsubscribeAdded = helpManager?.on('bookmark:added', () => {
      loadBookmarks();
    });
    
    const unsubscribeRemoved = helpManager?.on('bookmark:removed', () => {
      loadBookmarks();
    });
    
    return () => {
      unsubscribeAdded?.();
      unsubscribeRemoved?.();
    };
  });
</script>

<!-- Favorites Panel Container -->
<div class="help-favorites-panel">
  {#if isLoading}
    <!-- Loading State -->
    <div class="favorites-loading">
      <div class="loading-spinner"></div>
      <p>Loading bookmarks...</p>
    </div>
  {:else if error}
    <!-- Error State -->
    <div class="favorites-error">
      <p>{error}</p>
      <button on:click={loadBookmarks}>Retry</button>
    </div>
  {:else if bookmarks.length === 0}
    <!-- Empty State -->
    <div class="favorites-empty">
      <div class="empty-content">
        <h3>No Bookmarks</h3>
        <p>You haven't bookmarked any topics yet.</p>
        <p>Click the star icon (⭐) next to any topic to add it to your favorites.</p>
      </div>
    </div>
  {:else}
    <!-- Favorites Interface -->
    <div class="favorites-interface">
      <!-- Controls -->
      <div class="favorites-controls">
        <div class="sort-controls">
          <label>Sort by:</label>
          <button
            class="sort-button"
            class:active={sortBy === 'title'}
            on:click={() => handleSortChange('title')}
          >
            Title {sortBy === 'title' ? (sortOrder === 'asc' ? '↑' : '↓') : ''}
          </button>
          <button
            class="sort-button"
            class:active={sortBy === 'dateAdded'}
            on:click={() => handleSortChange('dateAdded')}
          >
            Date {sortBy === 'dateAdded' ? (sortOrder === 'asc' ? '↑' : '↓') : ''}
          </button>
          <button
            class="sort-button"
            class:active={sortBy === 'category'}
            on:click={() => handleSortChange('category')}
          >
            Category {sortBy === 'category' ? (sortOrder === 'asc' ? '↑' : '↓') : ''}
          </button>
        </div>
        
        <div class="filter-controls">
          <label>Filter:</label>
          <select
            bind:value={filterCategory}
            on:change={(e) => handleCategoryFilter(e.target.value || null)}
            class="category-filter"
          >
            <option value="">All Categories</option>
            {#each categories as category}
              <option value={category}>{category}</option>
            {/each}
          </select>
        </div>
        
        <div class="action-controls">
          <button
            class="clear-all-button"
            on:click={handleClearAll}
            title="Remove all bookmarks"
          >
            Clear All
          </button>
        </div>
      </div>
      
      <!-- Bookmarks List -->
      <div class="bookmarks-list">
        <div class="bookmarks-header">
          <span>{sortedBookmarks.length} bookmark{sortedBookmarks.length !== 1 ? 's' : ''}</span>
        </div>
        
        {#if sortedBookmarks.length === 0}
          <div class="no-matches">
            <p>No bookmarks match the current filter.</p>
          </div>
        {:else}
          <div class="bookmarks-items">
            {#each sortedBookmarks as bookmark}
              {@const topic = bookmarkTopics.get(bookmark.topicId)}
              <div
                class="bookmark-item"
                on:click={() => handleBookmarkClick(bookmark)}
                on:keydown={(e) => handleKeydown(e, bookmark)}
                tabindex="0"
                role="button"
                title="Click to open, Delete to remove"
              >
                <div class="bookmark-content">
                  <div class="bookmark-header">
                    <span class="bookmark-icon">⭐</span>
                    <span class="bookmark-title">{bookmark.title}</span>
                    <button
                      class="remove-button"
                      on:click|stopPropagation={() => handleRemoveBookmark(bookmark)}
                      title="Remove bookmark"
                    >
                      ✕
                    </button>
                  </div>
                  
                  <div class="bookmark-meta">
                    <span class="bookmark-category">{topic?.category || 'Unknown'}</span>
                    <span class="bookmark-date">
                      Added {bookmark.dateAdded.toLocaleDateString()}
                    </span>
                  </div>
                  
                  {#if bookmark.notes}
                    <div class="bookmark-notes">
                      {bookmark.notes}
                    </div>
                  {/if}
                </div>
              </div>
            {/each}
          </div>
        {/if}
      </div>
    </div>
  {/if}
</div>

