<!--
  Windows 98 F1 Help System - History Panel Component
  
  This component displays navigation history in the History tab,
  showing recently visited topics with timestamps and navigation options.
  
  @fileoverview History panel component for help system
-->

<script lang="ts">
  import { createEventDispatcher, onMount } from 'svelte';
  import type { HelpSystemManager, HelpTopic } from '../index.js';

  // Props
  let { helpManager }: { helpManager: HelpSystemManager } = $props();

  // State
  let history: string[] = $state([]);
  let historyTopics: Map<string, HelpTopic> = $state(new Map());
  let isLoading = $state(true);
  let error: string | null = $state(null);
  let currentIndex = $state(-1);
  let showStats = $state(false);

  // Event dispatcher
  const dispatch = createEventDispatcher();

  // Load history and topics
  async function loadHistory() {
    try {
      isLoading = true;
      error = null;
      
      const historyList = helpManager.getHistory();
      history = historyList;
      currentIndex = helpManager.getCurrentIndex();
      
      // Load topic details for history
      historyTopics.clear();
      for (const topicId of historyList) {
        const topic = helpManager.getTopic(topicId);
        if (topic) {
          historyTopics.set(topicId, topic);
        }
      }
      
    } catch (err) {
      error = `Failed to load history: ${err instanceof Error ? err.message : 'Unknown error'}`;
      console.error('Error loading history:', err);
    } finally {
      isLoading = false;
    }
  }

  // Handle history item click
  function handleHistoryClick(topicId: string, index: number) {
    // Navigate to the specific point in history
    while (helpManager.getCurrentIndex() < index) {
      helpManager.goForward();
    }
    while (helpManager.getCurrentIndex() > index) {
      helpManager.goBack();
    }
    dispatch('topic-select', topicId);
  }

  // Handle clear history
  function handleClearHistory() {
    if (confirm('Are you sure you want to clear all history?')) {
      helpManager.clearHistory();
      loadHistory();
    }
  }

  // Handle remove from history
  function handleRemoveFromHistory(topicId: string) {
    helpManager.removeFromHistory(topicId);
    loadHistory();
  }

  // Handle keyboard navigation
  function handleKeydown(event: KeyboardEvent, topicId: string, index: number) {
    if (event.key === 'Enter' || event.key === ' ') {
      event.preventDefault();
      handleHistoryClick(topicId, index);
    } else if (event.key === 'Delete') {
      event.preventDefault();
      handleRemoveFromHistory(topicId);
    }
  }

  // Toggle stats display
  function toggleStats() {
    showStats = !showStats;
  }

   // Get history statistics
   let stats = $derived((() => {
     const uniqueTopics = new Set(history).size;
     const totalVisits = history.length;
    const mostVisited = helpManager.getMostVisited().slice(0, 5);
    
    return {
      uniqueTopics,
      totalVisits,
      mostVisited
    };
  })());

  // Initialize component
  onMount(() => {
    loadHistory();
    
    // Listen for history changes
    const unsubscribe = helpManager?.on('history:updated', () => {
      loadHistory();
    });
    
    return unsubscribe;
  });
</script>

<!-- History Panel Container -->
<div class="help-history-panel">
  {#if isLoading}
    <!-- Loading State -->
    <div class="history-loading">
      <div class="loading-spinner"></div>
      <p>Loading history...</p>
    </div>
  {:else if error}
    <!-- Error State -->
    <div class="history-error">
      <p>{error}</p>
      <button on:click={loadHistory}>Retry</button>
    </div>
  {:else if history.length === 0}
    <!-- Empty State -->
    <div class="history-empty">
      <div class="empty-content">
        <h3>No History</h3>
        <p>You haven't visited any topics yet.</p>
        <p>Navigate through help topics to build your history.</p>
      </div>
    </div>
  {:else}
    <!-- History Interface -->
    <div class="history-interface">
      <!-- Controls -->
      <div class="history-controls">
        <div class="history-info">
          <span>{history.length} entries</span>
          <button
            class="stats-button"
            on:click={toggleStats}
            title="Show statistics"
          >
            📊
          </button>
        </div>
        
        <div class="history-actions">
          <button
            class="clear-button"
            on:click={handleClearHistory}
            title="Clear all history"
          >
            Clear All
          </button>
        </div>
      </div>
      
      <!-- Statistics -->
      {#if showStats}
        <div class="history-stats">
          <h4>History Statistics</h4>
          <div class="stats-grid">
            <div class="stat-item">
              <span class="stat-label">Total Visits:</span>
              <span class="stat-value">{stats.totalVisits}</span>
            </div>
            <div class="stat-item">
              <span class="stat-label">Unique Topics:</span>
              <span class="stat-value">{stats.uniqueTopics}</span>
            </div>
          </div>
          
          {#if stats.mostVisited.length > 0}
            <div class="most-visited">
              <h5>Most Visited Topics:</h5>
              <ul>
                {#each stats.mostVisited as topicId}
                  {@const topic = historyTopics.get(topicId)}
                  {#if topic}
                    <li>
                      <button
                        class="most-visited-link"
                        on:click={() => dispatch('topic-select', topicId)}
                      >
                        {topic.title}
                      </button>
                    </li>
                  {/if}
                {/each}
              </ul>
            </div>
          {/if}
        </div>
      {/if}
      
      <!-- History List -->
      <div class="history-list">
        <div class="history-items">
          {#each history as topicId, index}
            {@const topic = historyTopics.get(topicId)}
            {#if topic}
              <div
                class="history-item"
                class:current={index === currentIndex}
                on:click={() => handleHistoryClick(topicId, index)}
                on:keydown={(e) => handleKeydown(e, topicId, index)}
                tabindex="0"
                role="button"
                title="Click to navigate, Delete to remove"
              >
                <div class="history-content">
                  <div class="history-header">
                    <span class="history-icon">📄</span>
                    <span class="history-title">{topic.title}</span>
                    <button
                      class="remove-button"
                      on:click|stopPropagation={() => handleRemoveFromHistory(topicId)}
                      title="Remove from history"
                    >
                      ✕
                    </button>
                  </div>
                  
                  <div class="history-meta">
                    <span class="history-category">{topic.category}</span>
                    <span class="history-position">
                      {index + 1} of {history.length}
                    </span>
                  </div>
                  
                  {#if index === currentIndex}
                    <div class="current-indicator">
                      ← Current position
                    </div>
                  {/if}
                </div>
              </div>
            {/if}
          {/each}
        </div>
      </div>
    </div>
  {/if}
</div>

