<!--
  Windows 98 F1 Help System - Content Area Component
  
  This component displays the content of the selected help topic with
  Windows 98 styling, including proper formatting, links, and images.
  
  @fileoverview Content area component for help system
-->

<script lang="ts">
  import { createEventDispatcher, onMount } from 'svelte';
  import type { HelpSystemManager, HelpTopic } from '../index.js';

  // Props
  let { helpManager, topic = null }: { helpManager: HelpSystemManager; topic?: HelpTopic | null } = $props();

  // State
  let contentElement: HTMLElement = $state();
  let isBookmarked = $state(false);
  let relatedTopics: HelpTopic[] = $state([]);

  // Event dispatcher
  const dispatch = createEventDispatcher();

  // Update bookmark status
  function updateBookmarkStatus() {
    if (topic) {
      isBookmarked = helpManager?.isBookmarked(topic.id) || false;
    }
  }

  // Update related topics
  function updateRelatedTopics() {
    if (topic) {
      relatedTopics = helpManager?.getRelatedTopics(topic.id) || [];
    }
  }

  // Handle bookmark toggle
  function handleBookmarkToggle() {
    if (topic) {
      dispatch('bookmark-toggle', topic.id);
    }
  }

  // Handle related topic click
  function handleRelatedTopicClick(relatedTopic: HelpTopic) {
    dispatch('topic-select', relatedTopic.id);
  }

  // Handle content link click
  function handleContentLinkClick(event: MouseEvent) {
    const target = event.target as HTMLElement;
    if (target.tagName === 'A') {
      const href = target.getAttribute('href');
      if (href && href.startsWith('#')) {
        // Internal link - navigate to topic
        event.preventDefault();
        const topicId = href.substring(1);
        dispatch('topic-select', topicId);
      }
      // External links will open normally
    }
  }

  // Process content for display
  function processContent(content: string): string {
    // Convert markdown-style links to internal links
    let processedContent = content
      .replace(/\[([^\]]+)\]\(([^)]+)\)/g, '<a href="$2">$1</a>')
      // Convert line breaks to HTML
      .replace(/\n/g, '<br>')
      // Convert bold text
      .replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>')
      // Convert italic text
      .replace(/\*(.*?)\*/g, '<em>$1</em>')
      // Convert code blocks
      .replace(/```([\s\S]*?)```/g, '<pre><code>$1</code></pre>')
      // Convert inline code
      .replace(/`(.*?)`/g, '<code>$1</code>');

    return processedContent;
  }

  // Update state when topic changes
  $effect(() => {
    if (topic) {
      updateBookmarkStatus();
      updateRelatedTopics();
    }
  });

  // Initialize component
  onMount(() => {
    // Listen for bookmark changes
    const unsubscribe = helpManager?.on('bookmark:added', (data) => {
      if (topic && data.bookmark.topicId === topic.id) {
        isBookmarked = true;
      }
    });
    
    const unsubscribeRemoved = helpManager?.on('bookmark:removed', (data) => {
      if (topic && data.topicId === topic.id) {
        isBookmarked = false;
      }
    });
    
    return () => {
      unsubscribe?.();
      unsubscribeRemoved?.();
    };
  });
</script>

<!-- Content Area Container -->
<div class="help-content-area">
  {#if !topic}
    <!-- No Topic Selected -->
    <div class="content-empty">
      <div class="empty-content">
        <h2>Welcome to Help</h2>
        <p>Select a topic from the Contents tab to view help information.</p>
        <div class="empty-actions">
          <button on:click={() => dispatch('topic-select', 'getting-started')}>
            Getting Started
          </button>
        </div>
      </div>
    </div>
  {:else}
    <!-- Topic Content -->
    <div class="content-header">
      <div class="content-title">
        <h1>{topic.title}</h1>
        <div class="content-meta">
          <span class="topic-category">{topic.category}</span>
          {#if topic.metadata?.estimatedReadTime}
            <span class="read-time">{topic.metadata.estimatedReadTime} min read</span>
          {/if}
        </div>
      </div>
      <div class="content-actions">
        <button 
          class="bookmark-button"
          class:bookmarked={isBookmarked}
          on:click={handleBookmarkToggle}
          title={isBookmarked ? 'Remove bookmark' : 'Add bookmark'}
        >
          {isBookmarked ? '⭐' : '☆'}
        </button>
      </div>
    </div>
    
    <div class="content-body">
      <div 
        class="content-text"
        bind:this={contentElement}
        on:click={handleContentLinkClick}
        innerHTML={processContent(topic.content)}
      ></div>
      
      {#if relatedTopics.length > 0}
        <div class="related-topics">
          <h3>Related Topics</h3>
          <ul>
            {#each relatedTopics as relatedTopic}
              <li>
                <button 
                  class="related-topic-link"
                  on:click={() => handleRelatedTopicClick(relatedTopic)}
                >
                  {relatedTopic.title}
                </button>
              </li>
            {/each}
          </ul>
        </div>
      {/if}
    </div>
  {/if}
</div>

