<!--
  Windows 98 F1 Help System - Favorites Panel Component
  
  This component displays the favorites/bookmarks panel where users can manage
  their favorite help topics and quick access links.
  
  @fileoverview Favorites panel component for help system
-->

<script lang="ts">
  import { createEventDispatcher } from 'svelte';
  import type { HelpTopic, HelpBookmark } from '../types.js';

  // Props
  let { 
    favorites = [],
    currentTopic = null
  }: {
    favorites?: HelpBookmark[];
    currentTopic?: HelpTopic | null;
  } = $props();

  // State
  let isExpanded = $state(true);
  let searchQuery = $state('');
  let showAddDialog = $state(false);
  let newBookmarkTitle = $state('');
  let newBookmarkUrl = $state('');

  // Event dispatcher
  const dispatch = createEventDispatcher<{
    'favorite-select': { bookmark: HelpBookmark };
    'favorite-add': { title: string; url: string };
    'favorite-remove': { id: string };
    'favorite-edit': { id: string; title: string; url: string };
  }>();

  // Computed values
  const filteredFavorites = $derived(() => {
    if (!searchQuery.trim()) return favorites;
    const query = searchQuery.toLowerCase();
    return favorites.filter(bookmark => 
      bookmark.title.toLowerCase().includes(query) ||
      bookmark.url.toLowerCase().includes(query)
    );
  });

  const hasFavorites = $derived(favorites.length > 0);

  // Event handlers
  function handleFavoriteClick(bookmark: HelpBookmark) {
    dispatch('favorite-select', { bookmark });
  }

  function handleRemoveFavorite(id: string, event: Event) {
    event.stopPropagation();
    dispatch('favorite-remove', { id });
  }

  function handleEditFavorite(bookmark: HelpBookmark, event: Event) {
    event.stopPropagation();
    newBookmarkTitle = bookmark.title;
    newBookmarkUrl = bookmark.url;
    showAddDialog = true;
  }

  function handleAddFavorite() {
    if (newBookmarkTitle.trim() && newBookmarkUrl.trim()) {
      dispatch('favorite-add', { 
        title: newBookmarkTitle.trim(), 
        url: newBookmarkUrl.trim() 
      });
      newBookmarkTitle = '';
      newBookmarkUrl = '';
      showAddDialog = false;
    }
  }

  function handleCancelAdd() {
    newBookmarkTitle = '';
    newBookmarkUrl = '';
    showAddDialog = false;
  }

  function handleKeydown(event: KeyboardEvent) {
    if (event.key === 'Enter') {
      handleAddFavorite();
    } else if (event.key === 'Escape') {
      handleCancelAdd();
    }
  }

  function toggleExpanded() {
    isExpanded = !isExpanded;
  }
</script>

<div class="favorites-panel win98-panel">
  <div class="panel-header" onclick={toggleExpanded}>
    <div class="panel-title">
      <span class="panel-icon">⭐</span>
      Favorites
    </div>
    <div class="panel-controls">
      <button 
        class="panel-button add-button"
        onclick={(e) => { e.stopPropagation(); showAddDialog = true; }}
        title="Add to Favorites"
      >
        +
      </button>
      <button 
        class="panel-button toggle-button"
        class:expanded={isExpanded}
        title={isExpanded ? 'Collapse' : 'Expand'}
      >
        {isExpanded ? '−' : '+'}
      </button>
    </div>
  </div>

  {#if isExpanded}
    <div class="panel-content">
      {#if hasFavorites}
        <div class="search-container">
          <input
            type="text"
            class="search-input"
            placeholder="Search favorites..."
            bind:value={searchQuery}
          />
        </div>

        <div class="favorites-list">
          {#each filteredFavorites as bookmark (bookmark.id)}
            <div 
              class="favorite-item"
              class:current={currentTopic?.id === bookmark.url}
              onclick={() => handleFavoriteClick(bookmark)}
              role="button"
              tabindex="0"
            >
              <div class="favorite-content">
                <div class="favorite-title">{bookmark.title}</div>
                <div class="favorite-url">{bookmark.url}</div>
              </div>
              <div class="favorite-actions">
                <button
                  class="action-button edit-button"
                  onclick={(e) => handleEditFavorite(bookmark, e)}
                  title="Edit favorite"
                >
                  ✏️
                </button>
                <button
                  class="action-button remove-button"
                  onclick={(e) => handleRemoveFavorite(bookmark.id, e)}
                  title="Remove favorite"
                >
                  ×
                </button>
              </div>
            </div>
          {/each}
        </div>
      {:else}
        <div class="empty-state">
          <div class="empty-icon">⭐</div>
          <div class="empty-title">No Favorites</div>
          <div class="empty-message">
            Add topics to your favorites for quick access.
          </div>
          <button 
            class="add-first-button"
            onclick={() => showAddDialog = true}
          >
            Add First Favorite
          </button>
        </div>
      {/if}
    </div>
  {/if}
</div>

<!-- Add/Edit Dialog -->
{#if showAddDialog}
  <div class="dialog-overlay" onclick={handleCancelAdd}>
    <div class="dialog" onclick={(e) => e.stopPropagation()}>
      <div class="dialog-header">
        <div class="dialog-title">Add to Favorites</div>
        <button class="dialog-close" onclick={handleCancelAdd}>×</button>
      </div>
      <div class="dialog-content">
        <div class="form-group">
          <label for="bookmark-title">Title:</label>
          <input
            id="bookmark-title"
            type="text"
            class="form-input"
            bind:value={newBookmarkTitle}
            placeholder="Enter bookmark title"
            onkeydown={handleKeydown}
          />
        </div>
        <div class="form-group">
          <label for="bookmark-url">URL:</label>
          <input
            id="bookmark-url"
            type="text"
            class="form-input"
            bind:value={newBookmarkUrl}
            placeholder="Enter bookmark URL"
            onkeydown={handleKeydown}
          />
        </div>
      </div>
      <div class="dialog-buttons">
        <button class="dialog-button" onclick={handleCancelAdd}>Cancel</button>
        <button class="dialog-button primary" onclick={handleAddFavorite}>Add</button>
      </div>
    </div>
  </div>
{/if}

