<script lang="ts">
	import { desktop } from '../../stores/desktop.svelte.js';
	import { TASKBAR_HEIGHT, DESKTOP_ICON_SIZE, DESKTOP_ICON_SPACING } from '../../core/constants.js';

	const ICON_SIZE = DESKTOP_ICON_SIZE;
	const ICON_GAP = DESKTOP_ICON_SPACING;
	const MARGIN = 8;

	let draggingItemId = $state<string | null>(null);
	let dragOffset = $state({ x: 0, y: 0 });
	let clickTimer: number | null = null;

	// Calculate grid position for an item
	function getGridPosition(index: number) {
		const viewportHeight = window.innerHeight - TASKBAR_HEIGHT;
		const iconsPerColumn = Math.floor((viewportHeight - 2 * MARGIN) / (ICON_SIZE + ICON_GAP));

		const column = Math.floor(index / iconsPerColumn);
		const row = index % iconsPerColumn;

		return {
			x: MARGIN + column * (ICON_SIZE + ICON_GAP),
			y: MARGIN + row * (ICON_SIZE + ICON_GAP)
		};
	}

	function handleDesktopClick(e: MouseEvent) {
		if ((e.target as HTMLElement).closest('.desktop-icon')) {
			return; // Don't clear selection if clicking on an icon
		}
		desktop.clearSelection();
	}

	function handleIconClick(e: MouseEvent, itemId: string) {
		e.stopPropagation();
		
		// Clear any pending single-click action
		if (clickTimer) {
			clearTimeout(clickTimer);
			clickTimer = null;
		}
		
		// Delay selection to allow double-click to interrupt
		clickTimer = window.setTimeout(() => {
			desktop.selectItem(itemId);
			clickTimer = null;
		}, 200);
	}

	function handleIconDoubleClick(e: MouseEvent, itemId: string) {
		e.stopPropagation();
		
		// Cancel pending single-click selection
		if (clickTimer) {
			clearTimeout(clickTimer);
			clickTimer = null;
		}
		
		// Activate immediately
		desktop.activate(itemId);
	}

	function handleIconDragStart(e: MouseEvent, itemId: string) {
		const icon = (e.currentTarget as HTMLElement);
		const rect = icon.getBoundingClientRect();
		
		draggingItemId = itemId;
		dragOffset = {
			x: e.clientX - rect.left,
			y: e.clientY - rect.top
		};

		desktop.selectItem(itemId);
		e.preventDefault();
	}

	function handleMouseMove(e: MouseEvent) {
		if (draggingItemId) {
			const newX = e.clientX - dragOffset.x;
			const newY = e.clientY - dragOffset.y;

			desktop.moveItem(draggingItemId, { x: newX, y: newY });
		}
	}

	function handleMouseUp() {
		draggingItemId = null;
	}

	$effect(() => {
		if (draggingItemId) {
			window.addEventListener('mousemove', handleMouseMove);
			window.addEventListener('mouseup', handleMouseUp);

			return () => {
				window.removeEventListener('mousemove', handleMouseMove);
				window.removeEventListener('mouseup', handleMouseUp);
			};
		}
	});
</script>

<div class="desktop win98-desktop" onclick={handleDesktopClick}>
	{#each desktop.sortedItems as item, index}
		{@const position = item.position || (desktop.gridEnabled ? getGridPosition(index) : getGridPosition(index))}
		<div
			class="desktop-icon"
			class:selected={item.id === desktop.selectedItemId}
			data-item-id={item.id}
			style="left: {position.x}px; top: {position.y}px;"
			onclick={(e) => handleIconClick(e, item.id)}
			ondblclick={(e) => handleIconDoubleClick(e, item.id)}
			onmousedown={(e) => handleIconDragStart(e, item.id)}
			role="button"
			tabindex="0"
			aria-label={item.label}
		>
			<div class="desktop-icon-image {item.iconClass}"></div>
			<div class="desktop-icon-label">{item.label}</div>
		</div>
	{/each}
</div>

<style>
	.desktop {
		position: absolute;
		top: 0;
		left: 0;
		right: 0;
		bottom: 28px;
		background: var(--color-desktop);
		overflow: hidden;
	}

	.desktop-icon {
