<!--
  Windows 98 F1 Help System - Topic Tree Component
  
  This component displays the hierarchical topic tree in the Contents tab,
  showing folders and documents with expand/collapse functionality.
  
  @fileoverview Topic tree component for help system
-->

<script lang="ts">
  import { createEventDispatcher, onMount } from 'svelte';
  import type { HelpSystemManager, HelpTopic } from '../index.js';

  // Props
  let { helpManager }: { helpManager: HelpSystemManager } = $props();

  // State
  let topicTree: HelpTopic[] = $state([]);
  let expandedNodes: Set<string> = $state(new Set());
  let selectedTopicId: string | null = $state(null);
  let isLoading = $state(true);
  let error: string | null = $state(null);

  // Event dispatcher
  const dispatch = createEventDispatcher();

  // Load topic tree
  async function loadTopicTree() {
    try {
      isLoading = true;
      error = null;
      
      const tree = await helpManager.loadTopicTree();
      topicTree = tree;
      
      // Expand root nodes by default
      for (const topic of tree) {
        if (topic.children.length > 0) {
          expandedNodes.add(topic.id);
        }
      }
      
      // Set selected topic from current state
      const currentState = helpManager.getState();
      selectedTopicId = currentState.currentTopic;
      
    } catch (err) {
      error = `Failed to load topic tree: ${err instanceof Error ? err.message : 'Unknown error'}`;
      console.error('Error loading topic tree:', err);
    } finally {
      isLoading = false;
    }
  }

  // Toggle node expansion
  function toggleNode(topicId: string) {
    if (expandedNodes.has(topicId)) {
      expandedNodes.delete(topicId);
    } else {
      expandedNodes.add(topicId);
    }
    expandedNodes = expandedNodes; // Trigger reactivity
  }

  // Handle topic selection
  function handleTopicSelect(topic: HelpTopic) {
    selectedTopicId = topic.id;
    dispatch('topic-select', topic.id);
  }

  // Handle keyboard navigation
  function handleKeydown(event: KeyboardEvent, topic: HelpTopic) {
    switch (event.key) {
      case 'Enter':
      case ' ':
        event.preventDefault();
        if (topic.children.length > 0) {
          toggleNode(topic.id);
        } else {
          handleTopicSelect(topic);
        }
        break;
      case 'ArrowRight':
        event.preventDefault();
        if (topic.children.length > 0 && !expandedNodes.has(topic.id)) {
          toggleNode(topic.id);
        }
        break;
      case 'ArrowLeft':
        event.preventDefault();
        if (topic.children.length > 0 && expandedNodes.has(topic.id)) {
          toggleNode(topic.id);
        }
        break;
    }
  }

  // Get icon for topic
  function getTopicIcon(topic: HelpTopic): string {
    if (topic.children.length > 0) {
      return expandedNodes.has(topic.id) ? '📁' : '📂';
    }
    return '📄';
  }

  // Check if topic is bookmarked
  function isBookmarked(topicId: string): boolean {
    return helpManager?.isBookmarked(topicId) || false;
  }

  // Handle bookmark toggle
  function handleBookmarkToggle(event: MouseEvent, topicId: string) {
    event.stopPropagation();
    dispatch('bookmark-toggle', topicId);
  }

  // Initialize component
  onMount(() => {
    loadTopicTree();
    
    // Listen for state changes
    const unsubscribe = helpManager?.on('state:changed', (state) => {
      selectedTopicId = state.currentTopic;
    });
    
    return unsubscribe;
  });

  // Recursive topic rendering
  function renderTopic(topic: HelpTopic, level: number = 0): HelpTopic[] {
    const result: HelpTopic[] = [topic];
    
    if (expandedNodes.has(topic.id)) {
      for (const child of topic.children) {
        result.push(...renderTopic(child, level + 1));
      }
    }
    
    return result;
  }

  // Get all visible topics
  let visibleTopics = $derived(topicTree.flatMap(topic => renderTopic(topic)));
</script>

<!-- Topic Tree Container -->
<div class="help-topic-tree">
  {#if isLoading}
    <!-- Loading State -->
    <div class="tree-loading">
      <div class="loading-spinner"></div>
      <p>Loading topics...</p>
    </div>
  {:else if error}
    <!-- Error State -->
    <div class="tree-error">
      <p>{error}</p>
      <button on:click={loadTopicTree}>Retry</button>
    </div>
  {:else if topicTree.length === 0}
    <!-- Empty State -->
    <div class="tree-empty">
      <p>No topics available</p>
    </div>
  {:else}
    <!-- Topic Tree -->
    <div class="tree-content">
      {#each visibleTopics as topic}
        <div 
          class="tree-item"
          class:selected={selectedTopicId === topic.id}
          class:folder={topic.children.length > 0}
          class:document={topic.children.length === 0}
          style="padding-left: {(topic.parentId ? 16 : 0) + (visibleTopics.findIndex(t => t.id === topic.id) > 0 ? 16 : 0)}px;"
          on:click={() => handleTopicSelect(topic)}
          on:keydown={(e) => handleKeydown(e, topic)}
          tabindex="0"
          role="treeitem"
          aria-expanded={topic.children.length > 0 ? expandedNodes.has(topic.id) : undefined}
          aria-selected={selectedTopicId === topic.id}
        >
          <!-- Expand/Collapse Button -->
          {#if topic.children.length > 0}
            <button 
              class="expand-button"
              on:click|stopPropagation={() => toggleNode(topic.id)}
              aria-label={expandedNodes.has(topic.id) ? 'Collapse' : 'Expand'}
            >
              {expandedNodes.has(topic.id) ? '▼' : '▶'}
            </button>
          {:else}
            <span class="expand-spacer"></span>
          {/if}
          
          <!-- Topic Icon -->
          <span class="topic-icon">{getTopicIcon(topic)}</span>
          
          <!-- Topic Title -->
          <span class="topic-title" title={topic.title}>{topic.title}</span>
          
          <!-- Bookmark Button -->
          <button 
            class="bookmark-button"
            class:bookmarked={isBookmarked(topic.id)}
            on:click={(e) => handleBookmarkToggle(e, topic.id)}
            title={isBookmarked(topic.id) ? 'Remove bookmark' : 'Add bookmark'}
            aria-label={isBookmarked(topic.id) ? 'Remove bookmark' : 'Add bookmark'}
          >
            {isBookmarked(topic.id) ? '⭐' : '☆'}
          </button>
        </div>
      {/each}
    </div>
  {/if}
</div>

