import { persistState, restoreState } from '../core/storage/persistence.svelte.js';
import { validatePosition, validateSize, validatePluginId } from '../core/validation.js';
import type { WindowState, Position, Size } from '../core/types.js';
import {
	WINDOW_BASE_Z,
	DEFAULT_WINDOW_WIDTH,
	DEFAULT_WINDOW_HEIGHT,
	MAX_WINDOWS
} from '../core/constants.js';
import { pluginRegistry } from '../plugins/pluginRegistry.js';

let windows = $state<WindowState[]>([]);
let focusedWindowId = $state<string | null>(null);
let nextZIndex = $state(WINDOW_BASE_Z);
let initialized = false;

const visibleWindows = $derived(windows.filter((w) => !w.isMinimized));
const minimizedWindows = $derived(windows.filter((w) => w.isMinimized));
const focusedWindow = $derived(windows.find((w) => w.id === focusedWindowId) ?? null);

/**
 *
 */
function generateWindowId(): string {
	return `window-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;
}

/**
 *
 */
function getNextZIndex(): number {
	const current = nextZIndex;
	nextZIndex++;
	return current;
}

/**
 *
 * @param size
 */
function getCenteredPosition(size: Size): Position {
	const viewportWidth = typeof window !== 'undefined' ? window.innerWidth : 1024;
	const viewportHeight = typeof window !== 'undefined' ? window.innerHeight : 768;

	return {
		x: Math.max(0, Math.floor((viewportWidth - size.width) / 2)),
		y: Math.max(0, Math.floor((viewportHeight - size.height) / 2))
	};
}

/**
 *
 * @param immediate
 */
function persist(immediate = false): void {
	if (!initialized) return;

	const state = restoreState();
	state.windows.open = windows.map((w) => ({
		pluginId: w.pluginId,
		position: w.position,
		size: w.size,
		// Only persist minimized state, not maximized (maximized windows restore to normal)
		state: w.isMinimized ? 'minimized' : 'normal',
		preMaximizeBounds: w.preMaximizeBounds
	}));
	persistState(state, immediate);
}

export const windowManager = {
	get all(): WindowState[] {
		return windows;
	},

	get count(): number {
		return windows.length;
	},

	get focused(): WindowState | null {
		return focusedWindow;
	},

	get visible(): WindowState[] {
		return visibleWindows;
	},

	get minimized(): WindowState[] {
		return minimizedWindows;
	},

	get windows(): WindowState[] {
		return windows;
	},

	getWindow(windowId: string): WindowState | null {
		return windows.find((w) => w.id === windowId) ?? null;
	},

	// Add aliases for backward compatibility
	getWindowWithAliases(windowId: string): (WindowState & { minimized: boolean; maximized: boolean; focused: boolean }) | null {
		const window = windows.find((w) => w.id === windowId);
		if (!window) return null;
		
		return {
			...window,
			minimized: window.isMinimized,
			maximized: window.isMaximized,
			focused: window.isFocused
		};
	},

	// Deprecated: Plugin registry is now global, this method is kept for backwards compatibility
	setPluginRegistry(): void {
		// No-op: windowManager now uses global pluginRegistry
	},

	open(
		pluginId: string,
		options?: {
			position?: Position;
			size?: Size;
			title?: string;
		}
	): string {
		validatePluginId(pluginId);

		const plugin = pluginRegistry.get(pluginId);
		if (!plugin) {
			throw new Error(`Plugin not found: ${pluginId}`);
		}

		if (windows.length >= MAX_WINDOWS) {
			throw new Error(`Maximum number of windows (${MAX_WINDOWS}) reached`);
		}

		// Handle both WindowPlugin and CompositePlugin
		const isWindowPlugin = 'component' in plugin;
		const defaultSize = isWindowPlugin ? plugin.defaultSize : undefined;
		const defaultTitle = isWindowPlugin ? plugin.defaultTitle : plugin.name;
		const defaultIcon = isWindowPlugin ? plugin.defaultIcon : 'icon-apps-default';
		const isResizable = isWindowPlugin ? (plugin.isResizable ?? true) : true;

		const size = options?.size || defaultSize || {
			width: DEFAULT_WINDOW_WIDTH,
			height: DEFAULT_WINDOW_HEIGHT
		};

		validateSize(size);

		const position = options?.position || getCenteredPosition(size);
		validatePosition(position);

		const id = generateWindowId();

		const newWindow: WindowState = {
			id,
			pluginId,
			title: options?.title || defaultTitle,
			iconClass: defaultIcon,
			position,
			size,
			zIndex: getNextZIndex(),
			isMinimized: false,
			isMaximized: false,
			isFocused: false,
			isResizable
		};

		windows.push(newWindow);
		windowManager.focus(id);
		persist();

		return id;
	},

	close(windowId: string): void {
		const index = windows.findIndex((w) => w.id === windowId);
		if (index === -1) return;

		const closedWindow = windows[index];
		windows.splice(index, 1);

		if (focusedWindowId === windowId) {
			const topWindow = windows.length > 0 ? windows[windows.length - 1] : null;
			focusedWindowId = topWindow?.id ?? null;
			if (topWindow) {
				topWindow.isFocused = true;
			}
		}

		const state = restoreState();
		state.windows.history.unshift(closedWindow.pluginId);
		state.windows.history = state.windows.history.slice(0, 10);

		persist(true);
	},

	closeAll(): void {
		windows.forEach((window) => {
			const state = restoreState();
			state.windows.history.unshift(window.pluginId);
			state.windows.history = state.windows.history.slice(0, 10);
		});
		
		windows = [];
		focusedWindowId = null;
		persist(true);
	},

	minimize(windowId: string): void {
		const window = windows.find((w) => w.id === windowId);
		if (!window) return;

		window.isMinimized = true;
		window.isFocused = false;

		if (focusedWindowId === windowId) {
			const topVisible = visibleWindows[visibleWindows.length - 1];
			focusedWindowId = topVisible?.id ?? null;
			if (topVisible) {
				topVisible.isFocused = true;
			}
		}

		persist();
	},

	maximize(windowId: string): void {
		const window = windows.find((w) => w.id === windowId);
		if (!window) return;

		if (window.isMaximized) return;

		window.preMaximizeBounds = {
			x: window.position.x,
			y: window.position.y,
			width: window.size.width,
			height: window.size.height
		};

		const viewportWidth = typeof globalThis.window !== 'undefined' ? globalThis.window.innerWidth : 1024;
		const viewportHeight = typeof globalThis.window !== 'undefined' ? globalThis.window.innerHeight : 768;

		window.position = { x: 0, y: 0 };
		window.size = { width: viewportWidth, height: viewportHeight };
		window.isMaximized = true;
		window.isMinimized = false;

		windowManager.focus(windowId);
		persist();
	},

	restore(windowId: string): void {
		const window = windows.find((w) => w.id === windowId);
		if (!window) return;

		if (window.isMinimized) {
			window.isMinimized = false;
			windowManager.focus(windowId);
		} else if (window.isMaximized && window.preMaximizeBounds) {
			window.position = { x: window.preMaximizeBounds.x, y: window.preMaximizeBounds.y };
			window.size = {
				width: window.preMaximizeBounds.width,
				height: window.preMaximizeBounds.height
			};
			window.isMaximized = false;
			window.preMaximizeBounds = undefined;
			windowManager.focus(windowId);
		}

		persist();
	},

	focus(windowId: string): void {
		const window = windows.find((w) => w.id === windowId);
		if (!window) return;

		windows.forEach((w) => {
			w.isFocused = false;
		});

		window.isFocused = true;
		window.zIndex = getNextZIndex();
		focusedWindowId = windowId;
	},

	clearAllFocus(): void {
		windows.forEach((w) => {
			w.isFocused = false;
		});
		focusedWindowId = null;
	},

	move(windowId: string, position: Position): void {
		validatePosition(position);

		const window = windows.find((w) => w.id === windowId);
		if (!window) return;

		if (window.isMaximized) return;

		window.position = position;
		persist();
	},

	resize(windowId: string, size: Size, position?: Position): void {
		validateSize(size);

		const window = windows.find((w) => w.id === windowId);
		if (!window) return;

		if (window.isMaximized) return;
		if (!window.isResizable) return;

		window.size = size;

		if (position) {
			validatePosition(position);
			window.position = position;
		}

		persist();
	},

	init(): void {
		if (initialized) return;

		const state = restoreState();

		windows = [];
		focusedWindowId = null;
		nextZIndex = WINDOW_BASE_Z;

		for (const stored of state.windows.open) {
			const plugin = pluginRegistry.get(stored.pluginId);
			if (!plugin) {
				console.warn(`Plugin ${stored.pluginId} not found, skipping window restore`);
				continue;
			}

			// Handle both WindowPlugin and CompositePlugin
			const isWindowPlugin = 'component' in plugin;
			const defaultTitle = isWindowPlugin ? plugin.defaultTitle : plugin.name;
			const defaultIcon = isWindowPlugin ? plugin.defaultIcon : 'icon-apps-default';
			const isResizable = isWindowPlugin ? (plugin.isResizable ?? true) : true;

			const id = generateWindowId();
			const newWindow: WindowState = {
				id,
				pluginId: stored.pluginId,
				title: defaultTitle,
				iconClass: defaultIcon,
				position: stored.position,
				size: stored.size,
				zIndex: getNextZIndex(),
				isMinimized: stored.state === 'minimized',
				isMaximized: stored.state === 'maximized',
				isFocused: false,
				isResizable,
				preMaximizeBounds: stored.preMaximizeBounds
			};

			windows.push(newWindow);
		}

		if (windows.length > 0) {
			const lastWindow = windows[windows.length - 1];
			lastWindow.isFocused = true;
			focusedWindowId = lastWindow.id;
		}

		initialized = true;
	},

	_reset(): void {
		windows = [];
		focusedWindowId = null;
		nextZIndex = WINDOW_BASE_Z;
		initialized = false;
	}
};

