<script lang="ts">
	interface SelectOption {
		value: string;
		label: string;
	}

	interface Props {
		value: string;
		options: SelectOption[];
		disabled?: boolean;
		onchange: (value: string) => void;
		'aria-label'?: string;
	}

	let { 
		value = $bindable(), 
		options, 
		disabled = false, 
		onchange,
		'aria-label': ariaLabel
	}: Props = $props();

	function handleChange(event: Event) {
		if (!disabled) {
			const target = event.target as HTMLSelectElement;
			value = target.value;
			onchange(value);
		}
	}
</script>

<select 
	class="win98-select" 
	{value}
	{disabled} 
	onchange={handleChange}
	aria-label={ariaLabel}
	tabindex="0"
>
	{#each options as option}
		<option value={option.value}>{option.label}</option>
	{/each}
</select>

