<script lang="ts">
	import { onMount } from 'svelte';
	import type { WindowPlugin, KernelInterface } from '../../core/types.js';
	import { pluginRegistry } from '../../plugins/pluginRegistry.js';
	import { builtinPlugins } from '../../plugins/builtins.js';
	import { windowManager } from '../../stores/windowManager.svelte.js';
	import { desktop } from '../../stores/desktop.svelte.js';
	import { theme } from '../../stores/theme.svelte.js';
	import { audio } from '../../stores/audio.svelte.js';
	import { dialogManager } from '../../stores/dialogManager.svelte.js';
	import Desktop from './Desktop.svelte';
	import Taskbar from './Taskbar.svelte';
	import StartMenu from './StartMenu.svelte';
	import Window from '../windows/Window.svelte';
	import MessageBox from '../dialogs/MessageBox.svelte';
	import GlobalContextMenu from '../menus/GlobalContextMenu.svelte';

	interface Props {
		plugins?: WindowPlugin[];
		kernel?: KernelInterface;
	}

	let { plugins = [], kernel }: Props = $props();

	let showStartMenu = $state(false);
	let initialized = $state(false);
	
	// Get active dialog reactively
	const activeDialog = $derived(dialogManager.activeDialog);

	onMount(() => {
		// Register built-in plugins first (only if not already registered)
		builtinPlugins.forEach((plugin) => {
			try {
				// Check if plugin is already registered
				if (!pluginRegistry.get(plugin.id)) {
					pluginRegistry.registerWindow(plugin);
				}
			} catch (error) {
				console.error(`Failed to register built-in plugin ${plugin.id}:`, error);
			}
		});

		// Register user-provided plugins
		plugins.forEach((plugin) => {
			try {
				// Check if plugin is already registered
				if (!pluginRegistry.get(plugin.id)) {
					pluginRegistry.registerWindow(plugin);
				}
			} catch (error) {
				console.error(`Failed to register plugin ${plugin.id}:`, error);
			}
		});

		// Initialize stores (restore from localStorage)
		windowManager.init();
		theme.init();
		audio.init();

		// Add default desktop icons BEFORE calling desktop.init()
		// This ensures they have proper action functions
		const defaultIcons = [
			{
				id: 'my-computer',
				label: 'My Computer',
				iconClass: 'icon-system-computer',
				type: 'program' as const,
				action: () => windowManager.open('builtin-control-panel')
			},
		{
			id: 'recycle-bin',
			label: 'Recycle Bin',
			iconClass: 'icon-system-recycle-bin-empty',
			type: 'program' as const,
				action: () => dialogManager.alert('No items to display', 'Recycle Bin')
			},
		{
			id: 'control-panel',
			label: 'Control Panel',
			iconClass: 'icon-system-control-panel',
			type: 'program' as const,
				action: () => windowManager.open('builtin-control-panel')
			},
		{
			id: 'internet-explorer',
			label: 'Internet Explorer',
			iconClass: 'icon-apps-internet-internet-explorer',
			type: 'program' as const,
			action: () => windowManager.open('builtin-browser')
		},
		{
			id: 'ssh-terminal',
			label: 'SSH Terminal',
			iconClass: 'icon-ui-misc-ms-dos',
			type: 'program' as const,
			action: () => windowManager.open('builtin-msdos')
		},
		{
			id: 'terminal',
			label: 'Terminal',
			iconClass: 'icon-ui-misc-ms-dos',
			type: 'program' as const,
			action: () => windowManager.open('builtin-terminal')
		}
		];

		// Initialize desktop with default icons
		// This will restore positions from localStorage but keep our action functions
		desktop.init(defaultIcons);

		initialized = true;
	});

	function handleStartMenuToggle(show: boolean) {
		showStartMenu = show;
	}

	function closeStartMenu() {
		showStartMenu = false;
	}

	function handleShellClick(e: MouseEvent) {
		const target = e.target as HTMLElement;
		
		// Only clear focus if clicking on desktop background (not windows/taskbar)
		if (target.classList.contains('shell') || 
		    target.classList.contains('desktop')) {
			windowManager.clearAllFocus();
			showStartMenu = false;
		}
	}
</script>

<div class="shell" onclick={handleShellClick}>
	{#if initialized}
		<Desktop />

		{#each windowManager.all as window (window.id)}
			<Window {window} />
		{/each}

		<Taskbar 
			isStartMenuOpen={showStartMenu} 
			onStartMenuToggle={handleStartMenuToggle} 
		/>
		<StartMenu show={showStartMenu} onClose={closeStartMenu} />
		
		{#if activeDialog}
			<MessageBox
				title={activeDialog.title}
				message={activeDialog.message}
				type={activeDialog.type}
				buttons={activeDialog.buttons.map(btn => ({
					label: btn.label,
					action: () => dialogManager.close(btn.value)
				}))}
				onclose={() => dialogManager.close(undefined)}
			/>
		{/if}

		<!-- Global context menu -->
		<GlobalContextMenu />
	{:else}
		<div class="shell-loading">Loading Abu OS 98...</div>
	{/if}
</div>

<style>
	.shell {
		position: fixed;
		top: 0;
		left: 0;
		right: 0;
		bottom: 0;
		overflow: hidden;
		font-family: 'MS Sans Serif', Arial, sans-serif;
		background: var(--color-desktop);
	}

	.shell-loading {
		display: flex;
		align-items: center;
		justify-content: center;
		width: 100%;
		height: 100%;
		color: white;
		font-size: 16px;
		font-weight: bold;
	}

	:global(body) {
		margin: 0;
		padding: 0;
		overflow: hidden;
	}
</style>

