<script lang="ts">
	import { windowManager } from '../../stores/windowManager.svelte.js';
	import { audio } from '../../stores/audio.svelte.js';
	import { theme } from '../../stores/theme.svelte.js';

	let currentTime = $state(new Date());

	interface Props {
		isStartMenuOpen?: boolean;
		onStartMenuToggle?: (show: boolean) => void;
	}

	let { isStartMenuOpen = false, onStartMenuToggle }: Props = $props();

	function handleStartClick(e: MouseEvent) {
		e.stopPropagation(); // Prevent shell click handler from interfering
		// Emit the toggled state - parent owns the state
		onStartMenuToggle?.(!isStartMenuOpen);
	}

	function handleWindowButtonClick(windowId: string) {
		const window = windowManager.all.find(w => w.id === windowId);
		if (!window) return;

		if (window.isFocused && !window.isMinimized) {
			windowManager.minimize(windowId);
		} else {
			if (window.isMinimized) {
				windowManager.restore(windowId);
			}
			windowManager.focus(windowId);
		}
	}

	function handleVolumeToggle(e: MouseEvent) {
		e.stopPropagation(); // Prevent shell click handler from interfering
		audio.toggleMute();
	}

	function handleThemeToggle(e: MouseEvent) {
		e.stopPropagation(); // Prevent shell click handler from interfering
		theme.toggle();
	}

	// Update clock every second
	$effect(() => {
		const interval = setInterval(() => {
			currentTime = new Date();
		}, 1000);

		return () => clearInterval(interval);
	});

	const timeString = $derived(() => {
		return currentTime.toLocaleTimeString('en-US', {
			hour: 'numeric',
			minute: '2-digit',
			hour12: true
		});
	});
</script>

<div class="taskbar">
	<button
		type="button"
		class="taskbar-start-button"
		class:pressed={isStartMenuOpen}
		onclick={(e) => handleStartClick(e)}
	>
		<i class="icon icon-ui-misc-start size-16"></i>
		<span class="start-text">Start</span>
	</button>

	<div class="taskbar-windows">
		{#each windowManager.all.filter(w => !w.isMinimized) as window}
			<button
				type="button"
				class="taskbar-window-button"
				class:active={window.isFocused}
				onclick={() => handleWindowButtonClick(window.id)}
				title={window.title}
			>
				<i class="icon {window.iconClass} size-16"></i>
				<span class="window-title">{window.title}</span>
			</button>
		{/each}
	</div>

	<div class="taskbar-tray">
		<button
			type="button"
			class="tray-button"
			onclick={(e) => handleVolumeToggle(e)}
			title={audio.muted ? 'Unmute' : 'Mute'}
		>
			<i class="icon {audio.muted ? 'icon-control-audio' : 'icon-control-audio'} size-16"></i>
		</button>

		<button
			type="button"
			class="tray-button"
			onclick={(e) => handleThemeToggle(e)}
			title={theme.isDark ? 'Switch to Light Theme' : 'Switch to Dark Theme'}
		>
			<i class="icon icon-hardware-devices-display-properties size-16"></i>
		</button>

		<div class="taskbar-clock">{timeString()}</div>
	</div>
</div>

