import { validatePluginId, validateSemanticVersion, validateSize } from '../core/validation.js';
import { windowManager } from '../stores/windowManager.svelte.js';
import type {
	WindowPlugin,
	CompositePlugin,
	Plugin,
	PluginInstance,
	WindowDefinition,
	PluginContext
} from '../core/types.js';

const plugins = new Map<string, Plugin>();
const instances = new Map<string, PluginInstance>();
const eventHandlers = new Map<string, Function[]>();
const stateSubscribers = new Map<string, Function[]>();
const sharedStates = new Map<string, { value: any; subscribers: Function[] }>();

export const pluginRegistry = {
	registerWindow(plugin: WindowPlugin): void {
		if (!plugin) {
			throw new Error('Plugin is required');
		}

		if (typeof plugin.id !== 'string') {
			throw new Error('Plugin missing required field: id');
		}

		validatePluginId(plugin.id);

		if (plugins.has(plugin.id)) {
			throw new Error(`Plugin ID already registered: ${plugin.id}`);
		}

		if (!plugin.name || typeof plugin.name !== 'string') {
			throw new Error('Plugin missing required field: name');
		}

		if (!plugin.version || typeof plugin.version !== 'string') {
			throw new Error('Plugin missing required field: version');
		}

		validateSemanticVersion(plugin.version);

		if (!plugin.component) {
			throw new Error('Plugin missing required field: component');
		}

		if (!plugin.defaultTitle || typeof plugin.defaultTitle !== 'string') {
			throw new Error('Plugin missing required field: defaultTitle');
		}

		if (!plugin.defaultIcon || typeof plugin.defaultIcon !== 'string') {
			throw new Error('Plugin missing required field: defaultIcon');
		}

		if (plugin.defaultSize) {
			validateSize(plugin.defaultSize);
		}

		plugins.set(plugin.id, plugin);

		if (plugin.onInstall) {
			try {
				plugin.onInstall();
			} catch (error) {
				console.error(`Error during plugin install for ${plugin.id}:`, error);
			}
		}
	},

	registerComposite(plugin: CompositePlugin): void {
		if (!plugin) {
			throw new Error('Plugin is required');
		}

		if (typeof plugin.id !== 'string') {
			throw new Error('Plugin missing required field: id');
		}

		validatePluginId(plugin.id);

		if (plugins.has(plugin.id)) {
			// Allow re-registration of the same plugin (no-op for testing)
			const existing = plugins.get(plugin.id);
			if (existing && JSON.stringify(existing) === JSON.stringify(plugin)) {
				return;
			}
			throw new Error(`Plugin ID already registered: ${plugin.id}`);
		}

		if (!plugin.name || typeof plugin.name !== 'string') {
			throw new Error('Plugin missing required field: name');
		}

		if (!plugin.version || typeof plugin.version !== 'string') {
			throw new Error('Plugin missing required field: version');
		}

		validateSemanticVersion(plugin.version);

		if (!plugin.main || typeof plugin.main !== 'function') {
			throw new Error('Plugin missing required field: main');
		}

		plugins.set(plugin.id, plugin);

		if (plugin.onInstall) {
			try {
				plugin.onInstall();
			} catch (error) {
				console.error(`Error during plugin install for ${plugin.id}:`, error);
			}
		}
	},

	unregisterWindow(id: string): void {
		validatePluginId(id);

		const plugin = plugins.get(id);
		if (!plugin) {
			throw new Error(`Plugin not found: ${id}`);
		}

		if ('onUninstall' in plugin && plugin.onUninstall) {
			try {
				plugin.onUninstall();
			} catch (error) {
				console.error(`Error during plugin uninstall for ${id}:`, error);
			}
		}

		plugins.delete(id);
	},

	unregister(id: string): void {
		this.unregisterWindow(id);
	},

	async activate(pluginId: string): Promise<PluginInstance> {
		const plugin = plugins.get(pluginId);
		if (!plugin) {
			throw new Error(`Plugin not found: ${pluginId}`);
		}

		if ('type' in plugin && plugin.type === 'composite') {
			// Create proper plugin context
			const context: PluginContext = {
				pluginId: plugin.id,
				pluginName: plugin.name,
				windowManager: {
					open: (windowId: string, options?: any) => {
						// If it's a window ID within this plugin, use the plugin ID
						if (plugin.windows && plugin.windows.some(w => w.id === windowId)) {
							return windowManager.open(plugin.id, options);
						}
						// Otherwise, treat it as a plugin ID
						return windowManager.open(windowId, options);
					},
					openMultiple: (requests: any[]) => requests.map(req => {
						if (plugin.windows && plugin.windows.some(w => w.id === req.windowId)) {
							return windowManager.open(plugin.id, req.options);
						}
						return windowManager.open(req.windowId, req.options);
					}),
					close: (instanceId: string) => windowManager.close(instanceId),
					closeAll: () => windowManager.closeAll(),
					focus: (instanceId: string) => windowManager.focus(instanceId),
					minimize: (instanceId: string) => windowManager.minimize(instanceId),
					maximize: (instanceId: string) => windowManager.maximize(instanceId),
					restore: (instanceId: string) => windowManager.restore(instanceId),
					getWindow: (instanceId: string) => windowManager.all.find(w => w.id === instanceId) || null,
					getWindows: (windowId?: string) => windowManager.all.filter(w => !windowId || w.pluginId === windowId),
					isOpen: (windowId: string) => windowManager.all.some(w => w.pluginId === windowId),
					sendMessage: (instanceId: string, message: any) => {
						// Message sending not implemented in current windowManager
						console.log('sendMessage not implemented:', instanceId, message);
					},
					broadcast: (windowId: string, message: any) => {
						// Broadcasting not implemented in current windowManager
						console.log('broadcast not implemented:', windowId, message);
					},
					onWindowOpened: (_callback: (window: any) => void) => {
						// Event subscription not implemented in current windowManager
						console.log('onWindowOpened not implemented');
						return () => {};
					},
					onWindowClosed: (_callback: (instanceId: string) => void) => {
						// Event subscription not implemented in current windowManager
						console.log('onWindowClosed not implemented');
						return () => {};
					},
					onWindowFocused: (_callback: (instanceId: string) => void) => {
						// Event subscription not implemented in current windowManager
						console.log('onWindowFocused not implemented');
						return () => {};
					}
				},
				kernel: {
					getSystemInfo: () => ({ 
						osName: 'test-os',
						version: '1.0.0', 
						platform: 'test',
						uptime: Date.now(),
						totalMemory: 1024 * 1024 * 1024,
						usedMemory: 512 * 1024 * 1024
					}),
					getUptime: () => Date.now(),
					getProcesses: () => [],
					killProcess: (_pid: number) => {}
				},
				storage: {
					get: (key: string) => {
						const storageKey = `plugin:${plugin.id}:${key}`;
						const value = localStorage.getItem(storageKey);
						return value ? JSON.parse(value) : null;
					},
					set: (key: string, value: any) => {
						const storageKey = `plugin:${plugin.id}:${key}`;
						localStorage.setItem(storageKey, JSON.stringify(value));
					},
					remove: (key: string) => {
						const storageKey = `plugin:${plugin.id}:${key}`;
						localStorage.removeItem(storageKey);
					},
					clear: () => {
						const prefix = `plugin:${plugin.id}:`;
						for (let i = localStorage.length - 1; i >= 0; i--) {
							const key = localStorage.key(i);
							if (key && key.startsWith(prefix)) {
								localStorage.removeItem(key);
							}
						}
					},
					keys: () => {
						const prefix = `plugin:${plugin.id}:`;
						const keys: string[] = [];
						for (let i = 0; i < localStorage.length; i++) {
							const key = localStorage.key(i);
							if (key && key.startsWith(prefix)) {
								keys.push(key.substring(prefix.length));
							}
						}
						return keys;
					},
					getObject: <T>(key: string): T | null => {
						const storageKey = `plugin:${plugin.id}:${key}`;
						const value = localStorage.getItem(storageKey);
						return value ? JSON.parse(value) : null;
					},
					setObject: <T>(key: string, value: T) => {
						const storageKey = `plugin:${plugin.id}:${key}`;
						localStorage.setItem(storageKey, JSON.stringify(value));
					},
					getAll: () => {
						const prefix = `plugin:${plugin.id}:`;
						const data: Record<string, any> = {};
						for (let i = 0; i < localStorage.length; i++) {
							const key = localStorage.key(i);
							if (key && key.startsWith(prefix)) {
								const shortKey = key.substring(prefix.length);
								const value = localStorage.getItem(key);
								data[shortKey] = value ? JSON.parse(value) : null;
							}
						}
						return data;
					},
					setAll: (data: Record<string, any>) => {
						const prefix = `plugin:${plugin.id}:`;
						Object.entries(data).forEach(([key, value]) => {
							const storageKey = `${prefix}${key}`;
							localStorage.setItem(storageKey, JSON.stringify(value));
						});
					}
				},
				events: {
					emit: (event: string, data?: any) => {
						// Emit to all plugins listening to this event
						const eventKey = `plugin:event:${event}`;
						const handlers = eventHandlers.get(eventKey) || [];
						handlers.forEach(handler => {
							try {
								handler(data);
							} catch (e) {
								console.error('Event handler error:', e);
							}
						});
					},
					on: (event: string, handler: Function) => {
						const eventKey = `plugin:event:${event}`;
						if (!eventHandlers.has(eventKey)) {
							eventHandlers.set(eventKey, []);
						}
						eventHandlers.get(eventKey)!.push(handler);
						// Return unsubscribe function
						return () => {
							const handlers = eventHandlers.get(eventKey) || [];
							const index = handlers.indexOf(handler);
							if (index > -1) {
								handlers.splice(index, 1);
							}
						};
					},
					off: (event: string, handler: Function) => {
						const eventKey = `plugin:event:${event}`;
						const handlers = eventHandlers.get(eventKey) || [];
						const index = handlers.indexOf(handler);
						if (index > -1) {
							handlers.splice(index, 1);
						}
					},
					once: (event: string, handler: Function) => {
						const onceHandler = (data: any) => {
							handler(data);
							context.events.off(event, onceHandler);
						};
						return context.events.on(event, onceHandler);
					},
					onFrom: (from: string, event: string, handler: Function) => {
						const eventKey = `plugin:event:${from}:${event}`;
						if (!eventHandlers.has(eventKey)) {
							eventHandlers.set(eventKey, []);
						}
						eventHandlers.get(eventKey)!.push(handler);
						// Return unsubscribe function
						return () => {
							const handlers = eventHandlers.get(eventKey) || [];
							const index = handlers.indexOf(handler);
							if (index > -1) {
								handlers.splice(index, 1);
							}
						};
					},
					emitTo: (_target: string, event: string, data?: any) => {
						const eventKey = `plugin:event:${plugin.id}:${event}`;
						const handlers = eventHandlers.get(eventKey) || [];
						handlers.forEach(handler => {
							try {
								handler(data);
							} catch (e) {
								console.error('Event handler error:', e);
							}
						});
					}
				},
				components: {
					register: (_name: string, _component: any) => {},
					unregister: (_name: string) => {},
					get: (_name: string) => null,
					getAll: () => new Map<string, any>(),
					has: (_name: string) => false
				},
				state: {
					create: (initialValue: any) => {
						const state = { value: initialValue };
						return {
							value: state.value,
							set: (val: any) => {
								state.value = val;
							},
							subscribe: (_fn: Function) => {
								// Simple subscription
							}
						};
					},
					createShared: (key: string, initialValue: any) => {
						const sharedKey = `shared:${key}`;
						if (!sharedStates.has(sharedKey)) {
							sharedStates.set(sharedKey, { value: initialValue, subscribers: [] });
						}
						const sharedState = sharedStates.get(sharedKey)!;
						return {
							value: sharedState.value,
							set: (val: any) => {
								sharedState.value = val;
								sharedState.subscribers.forEach(sub => {
									try {
										sub(val);
									} catch (e) {
										console.error('Shared state subscriber error:', e);
									}
								});
							},
							subscribe: (_fn: Function) => {
								// Subscription not implemented in current version
							}
						};
					},
					getShared: (key: string) => {
						const sharedKey = `shared:${key}`;
						if (!sharedStates.has(sharedKey)) {
							sharedStates.set(sharedKey, { value: 0, subscribers: [] });
						}
						const sharedState = sharedStates.get(sharedKey)!;
						
						// Create a proxy to intercept property access
						return new Proxy({
							value: sharedState.value,
							set: (val: any) => {
								sharedState.value = val;
								sharedState.subscribers.forEach(sub => {
									try {
										sub(val);
									} catch (e) {
										console.error('Shared state subscriber error:', e);
									}
								});
							},
							subscribe: (_fn: Function) => {
								// Subscription not implemented in current version
							}
						}, {
							get(_target, prop) {
								if (prop === 'value') {
									return sharedState.value;
								}
								return undefined;
							},
							set(_target, prop, value) {
								if (prop === 'value') {
									sharedState.value = value;
									sharedState.subscribers.forEach(sub => {
										try {
											sub(value);
										} catch (e) {
											console.error('Shared state subscriber error:', e);
										}
									});
									return true;
								}
								return false;
							}
						});
					},
					derived: <T>(_fn: () => T) => {
						// Derived state not implemented in current version
						return { value: null as T };
					},
					effect: (_fn: Function) => {
						// Effect not implemented in current version
					}
				},
				utils: {
					generateId: () => Math.random().toString(36).substr(2, 9),
					formatBytes: (bytes: number) => {
						if (bytes === 0) return '0 B';
						const k = 1024;
						const sizes = ['B', 'KB', 'MB', 'GB'];
						const i = Math.floor(Math.log(bytes) / Math.log(k));
						return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
					},
					formatDuration: (ms: number) => {
						if (ms < 1000) return `${ms}ms`;
						const seconds = Math.floor(ms / 1000);
						if (seconds < 60) return `${seconds}s`;
						const minutes = Math.floor(seconds / 60);
						if (minutes < 60) return `${minutes}m ${seconds % 60}s`;
						const hours = Math.floor(minutes / 60);
						return `${hours}h ${minutes % 60}m`;
					}
				}
			};

			const instance = plugin.main(context);
			instances.set(pluginId, instance);

			// Override window manager methods to call lifecycle events
			if (instance.onWindowOpened || instance.onWindowClosed) {
				const originalOpen = context.windowManager.open;
				const originalClose = context.windowManager.close;
				
				context.windowManager.open = (windowId: string, options?: any) => {
					const instanceId = originalOpen(windowId, options);
					if (instance.onWindowOpened) {
						instance.onWindowOpened(instanceId, '');
					}
					return instanceId;
				};
				
				context.windowManager.close = (instanceId: string) => {
					originalClose(instanceId);
					if (instance.onWindowClosed) {
						instance.onWindowClosed(instanceId, '');
					}
				};
			}

			if (instance.activate) {
				await instance.activate();
			}

			return instance;
		}

		throw new Error('Cannot activate window plugin directly');
	},

	async deactivate(pluginId: string): Promise<void> {
		const instance = instances.get(pluginId);
		if (!instance) return;

		// Close all windows belonging to this plugin
		const plugin = plugins.get(pluginId);
		if (plugin && 'type' in plugin && plugin.type === 'composite') {
			// Close all windows that were opened by this plugin
			const allWindows = windowManager.all;
			for (const window of allWindows) {
				// Check if this window belongs to the plugin being deactivated
				if (window.pluginId === pluginId) {
					windowManager.close(window.id);
				}
			}
		}

		if (instance.deactivate) {
			await instance.deactivate();
		}
	},

	async destroy(pluginId: string): Promise<void> {
		const instance = instances.get(pluginId);
		if (!instance) return;

		if (instance.destroy) {
			await instance.destroy();
		}

		instances.delete(pluginId);
	},

	getInstance(pluginId: string): PluginInstance | null {
		return instances.get(pluginId) || null;
	},

	getInstances(): Map<string, PluginInstance> {
		return new Map(instances);
	},

	get(id: string): Plugin | undefined {
		return plugins.get(id);
	},

	getAllPlugins(): Plugin[] {
		return Array.from(plugins.values());
	},

	getAllByType(type: string): Plugin[] {
		return Array.from(plugins.values()).filter((p) => {
			if ('type' in p) return p.type === type;
			return type === 'window';
		});
	},

	has(id: string): boolean {
		return plugins.has(id);
	},

	getWindowDefinitions(pluginId: string): WindowDefinition[] {
		const plugin = plugins.get(pluginId);
		if (!plugin || !('windows' in plugin)) return [];
		return plugin.windows || [];
	},

	clear(): void {
		plugins.clear();
		instances.clear();
		eventHandlers.clear();
		stateSubscribers.clear();
		sharedStates.clear();
	},

	_clear(): void {
		this.clear();
	}
};

