<!--
  Windows 98 F1 Help System - Tab Bar Component
  
  This component provides the tab bar with Contents, Index, Search, Favorites,
  and History tabs following Windows 98 tab conventions.
  
  @fileoverview Tab bar component for help system
-->

<script lang="ts">
  import { createEventDispatcher } from 'svelte';
  import type { HelpTab } from '../types.js';

  // Props
  let { 
    activeTab = $bindable('contents')
  }: {
    activeTab?: HelpTab;
  } = $props();

  // Event dispatcher
  const dispatch = createEventDispatcher();

  // Tab configurations
  const tabs = [
    {
      id: 'contents' as HelpTab,
      label: 'Contents',
      icon: '📚',
      tooltip: 'Table of contents'
    },
    {
      id: 'index' as HelpTab,
      label: 'Index',
      icon: '🔍',
      tooltip: 'Search index'
    },
    {
      id: 'search' as HelpTab,
      label: 'Search',
      icon: '🔎',
      tooltip: 'Search topics'
    },
    {
      id: 'favorites' as HelpTab,
      label: 'Favorites',
      icon: '⭐',
      tooltip: 'Bookmarked topics'
    },
    {
      id: 'history' as HelpTab,
      label: 'History',
      icon: '🕒',
      tooltip: 'Recently visited topics'
    }
  ];

  // Tab handlers
  function handleTabClick(tabId: HelpTab) {
    if (tabId !== activeTab) {
      dispatch('tab-change', { tab: tabId });
    }
  }

  function handleTabKeydown(event: KeyboardEvent, tabId: HelpTab) {
    if (event.key === 'Enter' || event.key === ' ') {
      event.preventDefault();
      handleTabClick(tabId);
    }
  }

  // Keyboard navigation
  function handleKeydown(event: KeyboardEvent) {
    if (event.ctrlKey && event.key >= '1' && event.key <= '5') {
      event.preventDefault();
      const tabIndex = parseInt(event.key) - 1;
      if (tabIndex >= 0 && tabIndex < tabs.length) {
        handleTabClick(tabs[tabIndex].id);
      }
    }
  }
</script>

<svelte:window on:keydown={handleKeydown} />

<div class="tab-bar">
  {#each tabs as tab}
    <button
      class="tab-button"
      class:active={activeTab === tab.id}
      on:click={() => handleTabClick(tab.id)}
      on:keydown={(e) => handleTabKeydown(e, tab.id)}
      title="{tab.tooltip} (Ctrl+{tabs.indexOf(tab) + 1})"
    >
      <span class="tab-icon">{tab.icon}</span>
      <span class="tab-label">{tab.label}</span>
    </button>
  {/each}
</div>

<style>
  .tab-bar {
    display: flex;
    background: #c0c0c0;
    border-bottom: 1px inset #c0c0c0;
    font-size: 11px;
    user-select: none;
  }

  .tab-button {
    display: flex;
    align-items: center;
    gap: 4px;
    padding: 4px 12px;
    border: 1px outset #c0c0c0;
    background: #c0c0c0;
    color: black;
    cursor: pointer;
    font-size: 11px;
    font-family: 'MS Sans Serif', sans-serif;
    white-space: nowrap;
    position: relative;
  }

  .tab-button:hover:not(.active) {
    background: #d4d0c8;
  }

  .tab-button:active:not(.active) {
    border: 1px inset #c0c0c0;
  }

  .tab-button.active {
    background: white;
    border-bottom: 1px solid white;
    z-index: 1;
  }

  .tab-button.active::after {
    content: '';
    position: absolute;
    bottom: -1px;
    left: 0;
    right: 0;
    height: 1px;
    background: white;
  }

  .tab-icon {
    font-size: 12px;
    line-height: 1;
  }

  .tab-label {
    font-size: 11px;
  }

  /* Responsive adjustments */
  @media (max-width: 600px) {
    .tab-label {
      display: none;
    }
    
    .tab-icon {
      font-size: 14px;
    }
    
    .tab-button {
      padding: 4px 8px;
    }
  }

  @media (max-width: 400px) {
    .tab-button {
      padding: 4px 6px;
    }
  }
</style>
