<!--
  Windows 98 F1 Help System - Main Component
  
  This is the main help system component that orchestrates all other components
  and provides the complete Windows 98 help system experience.
  
  @fileoverview Main help system component
-->

<script lang="ts">
  import { onMount, onDestroy } from 'svelte';
  import { HelpSystemManager } from '../HelpSystemManager.js';
  import type { 
    HelpSystemState, 
    HelpSystemConfig, 
    HelpTopic,
    HelpTab,
    WindowState,
    UserPreferences
  } from '../types.js';
  
  import MenuBar from './MenuBar.svelte';
  import Toolbar from './Toolbar.svelte';
  import TabBar from './TabBar.svelte';
  import TopicTree from './TopicTree.svelte';
  import ContentArea from './ContentArea.svelte';
  import StatusBar from './StatusBar.svelte';
  import SearchPanel from './SearchPanel.svelte';
  import FavoritesPanel from './FavoritesPanel.svelte';
  import HistoryPanel from './HelpHistoryPanel.svelte';

  // Props
  let { 
    config = $bindable({}),
    initialTopic = $bindable(null),
    windowTitle = $bindable('Windows 98 Help System')
  }: {
    config?: Partial<HelpSystemConfig>;
    initialTopic?: string | null;
    windowTitle?: string;
  } = $props();

  // State
  let helpSystem: HelpSystemManager;
  let systemState: HelpSystemState;
  let currentTopic: HelpTopic | null = null;
  let isLoading = true;
  let error: string | null = null;
  let windowState: WindowState;
  let isMaximized = false;
  let isMinimized = false;

  // Event handlers
  let unsubscribeFunctions: (() => void)[] = [];

  onMount(async () => {
    try {
      // Initialize help system
      helpSystem = new HelpSystemManager(config);
      
      // Set up event listeners
      setupEventListeners();
      
      // Initialize system
      await helpSystem.initialize();
      
      // Load initial topic if provided
      if (initialTopic) {
        await helpSystem.navigateTo(initialTopic);
      } else {
        // Navigate to home topic
        await helpSystem.goHome();
      }
      
      // Get initial state
      systemState = helpSystem.getState();
      currentTopic = systemState.currentTopic ? helpSystem.getTopic(systemState.currentTopic) : null;
      windowState = systemState.windowState;
      
      isLoading = false;
    } catch (err) {
      error = err instanceof Error ? err.message : 'Failed to initialize help system';
      isLoading = false;
    }
  });

  onDestroy(() => {
    // Clean up event listeners
    unsubscribeFunctions.forEach(unsubscribe => unsubscribe());
    
    // Destroy help system
    if (helpSystem) {
      helpSystem.destroy();
    }
  });

  function setupEventListeners() {
    if (!helpSystem) return;

    // State change listener
    const unsubscribeState = helpSystem.on('state:changed', (newState: HelpSystemState) => {
      systemState = newState;
      currentTopic = newState.currentTopic ? helpSystem.getTopic(newState.currentTopic) : null;
    });

    // Topic change listener
    const unsubscribeTopic = helpSystem.on('topic:changed', ({ topic }: { topic: HelpTopic }) => {
      currentTopic = topic;
    });

    // Error listener
    const unsubscribeError = helpSystem.on('error:occurred', ({ error: err }: { error: Error }) => {
      error = err.message;
    });

    unsubscribeFunctions.push(unsubscribeState, unsubscribeTopic, unsubscribeError);
  }

  // Navigation handlers
  async function handleNavigateTo(topicId: string) {
    try {
      error = null;
      await helpSystem.navigateTo(topicId);
    } catch (err) {
      error = err instanceof Error ? err.message : 'Navigation failed';
    }
  }

  async function handleGoBack() {
    try {
      error = null;
      await helpSystem.goBack();
    } catch (err) {
      error = err instanceof Error ? err.message : 'Go back failed';
    }
  }

  async function handleGoForward() {
    try {
      error = null;
      await helpSystem.goForward();
    } catch (err) {
      error = err instanceof Error ? err.message : 'Go forward failed';
    }
  }

  async function handleGoHome() {
    try {
      error = null;
      await helpSystem.goHome();
    } catch (err) {
      error = err instanceof Error ? err.message : 'Go home failed';
    }
  }

  // Search handlers
  async function handleSearch(query: string) {
    try {
      error = null;
      await helpSystem.search(query);
    } catch (err) {
      error = err instanceof Error ? err.message : 'Search failed';
    }
  }

  // Bookmark handlers
  async function handleAddBookmark(topicId: string) {
    try {
      error = null;
      await helpSystem.addBookmark(topicId);
    } catch (err) {
      error = err instanceof Error ? err.message : 'Failed to add bookmark';
    }
  }

  async function handleRemoveBookmark(topicId: string) {
    try {
      error = null;
      await helpSystem.removeBookmark(topicId);
    } catch (err) {
      error = err instanceof Error ? err.message : 'Failed to remove bookmark';
    }
  }

  // Tab handlers
  function handleTabChange(tab: HelpTab) {
    helpSystem.setActiveTab(tab);
  }

  // Window handlers
  function handleWindowResize(newSize: { width: number; height: number }) {
    helpSystem.setWindowState({ size: newSize });
  }

  function handleWindowMove(newPosition: { x: number; y: number }) {
    helpSystem.setWindowState({ position: newPosition });
  }

  function handleMaximize() {
    isMaximized = !isMaximized;
    helpSystem.setWindowState({ maximized: isMaximized });
  }

  function handleMinimize() {
    isMinimized = !isMinimized;
    // In a real implementation, this would minimize the window
  }

  function handleClose() {
    // In a real implementation, this would close the help system
    console.log('Help system closed');
  }

  // Splitter handlers
  function handleSplitterMove(position: number) {
    helpSystem.setWindowState({ splitterPosition: position });
  }

  // User preference handlers
  function handlePreferenceChange(preferences: Partial<UserPreferences>) {
    helpSystem.setUserPreferences(preferences);
  }
</script>

<div 
  class="help-system" 
  class:maximized={isMaximized}
  class:minimized={isMinimized}
  class:loading={isLoading}
  class:error={error}
  style="
    --window-width: {windowState.size.width}px;
    --window-height: {windowState.size.height}px;
    --splitter-position: {windowState.splitterPosition}px;
  "
>
  <!-- Window Title Bar -->
  {#if showWindowControls}
    <div class="title-bar" class:draggable={draggable}>
      <div class="title-bar-text">
        <span class="title-bar-icon">📖</span>
        {windowTitle}
      </div>
      <div class="title-bar-controls">
        <button 
          class="title-bar-button minimize" 
          on:click={handleMinimize}
          title="Minimize"
        >
          <span class="minimize-icon">_</span>
        </button>
        <button 
          class="title-bar-button maximize" 
          on:click={handleMaximize}
          title={isMaximized ? 'Restore' : 'Maximize'}
        >
          <span class="maximize-icon">{isMaximized ? '⧉' : '□'}</span>
        </button>
        <button 
          class="title-bar-button close" 
          on:click={handleClose}
          title="Close"
        >
          <span class="close-icon">×</span>
        </button>
      </div>
    </div>
  {/if}

  <!-- Menu Bar -->
  <MenuBar 
    {helpSystem}
    {currentTopic}
    on:navigate={handleNavigateTo}
    on:search={handleSearch}
    on:bookmark={handleAddBookmark}
    on:preference-change={handlePreferenceChange}
  />

  <!-- Toolbar -->
  <Toolbar 
    {helpSystem}
    {currentTopic}
    canGoBack={helpSystem?.canGoBack() || false}
    canGoForward={helpSystem?.canGoForward() || false}
    on:navigate={handleNavigateTo}
    on:go-back={handleGoBack}
    on:go-forward={handleGoForward}
    on:go-home={handleGoHome}
    on:search={handleSearch}
    on:bookmark={handleAddBookmark}
  />

  <!-- Tab Bar -->
  <TabBar 
    activeTab={systemState?.activeTab || 'contents'}
    on:tab-change={handleTabChange}
  />

  <!-- Main Content Area -->
  <div class="main-content">
    <!-- Left Panel -->
    <div class="left-panel">
      {#if systemState?.activeTab === 'contents'}
        <TopicTree 
          {helpSystem}
          {currentTopic}
          on:navigate={handleNavigateTo}
        />
      {:else if systemState?.activeTab === 'index'}
        <SearchPanel 
          {helpSystem}
          on:search={handleSearch}
          on:navigate={handleNavigateTo}
        />
      {:else if systemState?.activeTab === 'favorites'}
        <FavoritesPanel 
          {helpSystem}
          on:navigate={handleNavigateTo}
          on:bookmark={handleRemoveBookmark}
        />
      {:else if systemState?.activeTab === 'history'}
        <HistoryPanel 
          {helpSystem}
          on:navigate={handleNavigateTo}
        />
      {/if}
    </div>

    <!-- Splitter -->
    <div 
      class="splitter" 
      class:resizable={resizable}
      on:mousedown={handleSplitterMove}
    ></div>

    <!-- Right Panel (Content Area) -->
    <div class="right-panel">
      <ContentArea 
        {currentTopic}
        {isLoading}
        {error}
        on:navigate={handleNavigateTo}
      />
    </div>
  </div>

  <!-- Status Bar -->
  <StatusBar 
    {helpSystem}
    {currentTopic}
    {isLoading}
    {error}
  />

  <!-- Loading Overlay -->
  {#if isLoading}
    <div class="loading-overlay">
      <div class="loading-spinner"></div>
      <div class="loading-text">Loading help system...</div>
    </div>
  {/if}

  <!-- Error Overlay -->
  {#if error}
    <div class="error-overlay">
      <div class="error-content">
        <div class="error-icon">⚠️</div>
        <div class="error-title">Error</div>
        <div class="error-message">{error}</div>
        <button class="error-button" on:click={() => error = null}>
          OK
        </button>
      </div>
    </div>
  {/if}
</div>

