<script lang="ts">
	interface Props {
		windowId: string;
	}

	let { windowId }: Props = $props();

	// Browser state
	let currentUrl = $state('');
	let addressBarUrl = $state('');
	let history = $state<string[]>([]);
	let historyIndex = $state(-1);
	let isLoading = $state(false);
	let showFavorites = $state(false);
	let bookmarks = $state<Bookmark[]>([]);
	let iframeElement: HTMLIFrameElement | null = null;
	let loadError = $state(false);
	let statusText = $state('Ready');

	// Menu state
	let activeMenu = $state<string | null>(null);

	interface Bookmark {
		id: string;
		title: string;
		url: string;
		dateAdded: number;
	}

	// Computed states
	const canGoBack = $derived(historyIndex > 0);
	const canGoForward = $derived(historyIndex < history.length - 1);

	// Load bookmarks from localStorage
	$effect(() => {
		const stored = localStorage.getItem('abu-browser-bookmarks');
		if (stored) {
			try {
				bookmarks = JSON.parse(stored);
			} catch (e) {
				console.error('Failed to load bookmarks:', e);
				bookmarks = [];
			}
		}
	});

	// Save bookmarks to localStorage
	function saveBookmarks() {
		try {
			localStorage.setItem('abu-browser-bookmarks', JSON.stringify(bookmarks));
		} catch (e) {
			console.error('Failed to save bookmarks:', e);
		}
	}

	function normalizeUrl(url: string): string {
		if (!url.trim()) return 'about:blank';
		if (url === 'about:blank') return url;
		if (!url.match(/^https?:\/\//i)) {
			return `https://${url}`;
		}
		return url;
	}

	function navigate(url: string) {
		const normalizedUrl = normalizeUrl(url);
		
		if (historyIndex < history.length - 1) {
			history = history.slice(0, historyIndex + 1);
		}
		
		history = [...history, normalizedUrl];
		historyIndex = history.length - 1;
		
		if (history.length > 50) {
			history = history.slice(-50);
			historyIndex = history.length - 1;
		}
		
		currentUrl = normalizedUrl;
		addressBarUrl = normalizedUrl;
		isLoading = true;
		loadError = false;
		statusText = `Opening page ${normalizedUrl}...`;
	}

	function handleGo() {
		if (addressBarUrl.trim()) {
			navigate(addressBarUrl);
		}
	}

	function handleBack() {
		if (canGoBack) {
			historyIndex--;
			currentUrl = history[historyIndex];
			addressBarUrl = currentUrl;
			isLoading = true;
			loadError = false;
			statusText = `Opening page ${currentUrl}...`;
		}
	}

	function handleForward() {
		if (canGoForward) {
			historyIndex++;
			currentUrl = history[historyIndex];
			addressBarUrl = currentUrl;
			isLoading = true;
			loadError = false;
			statusText = `Opening page ${currentUrl}...`;
		}
	}

	function handleRefresh() {
		if (iframeElement) {
			isLoading = true;
			loadError = false;
			statusText = 'Refreshing...';
			iframeElement.src = currentUrl;
		}
	}

	function handleStop() {
		if (iframeElement && iframeElement.contentWindow) {
			iframeElement.contentWindow.stop();
			isLoading = false;
			statusText = 'Stopped';
		}
	}

	function handleHome() {
		navigate('about:blank');
	}

	function handleIframeLoad() {
		isLoading = false;
		loadError = false;
		statusText = 'Done';
	}

	function handleIframeError() {
		isLoading = false;
		loadError = true;
		statusText = 'Page cannot be displayed';
	}

	function toggleFavorites() {
		showFavorites = !showFavorites;
	}

	function addBookmark() {
		if (!currentUrl || currentUrl === 'about:blank') return;
		if (bookmarks.some(b => b.url === currentUrl)) return;
		
		const newBookmark: Bookmark = {
			id: `bm-${Date.now()}`,
			title: currentUrl,
			url: currentUrl,
			dateAdded: Date.now()
		};
		
		bookmarks = [...bookmarks, newBookmark];
		saveBookmarks();
	}

	function removeBookmark(id: string) {
		bookmarks = bookmarks.filter(b => b.id !== id);
		saveBookmarks();
	}

	function navigateToBookmark(url: string) {
		addressBarUrl = url;
		navigate(url);
		showFavorites = false;
	}

	function handleKeyDown(e: KeyboardEvent) {
		if (e.key === 'Enter') {
			handleGo();
		}
	}

	function handleMenuClick(menu: string) {
		activeMenu = activeMenu === menu ? null : menu;
	}

	function closeMenus() {
		activeMenu = null;
	}

	// Keyboard shortcuts
	function handleWindowKeyDown(e: KeyboardEvent) {
		if (e.altKey && e.key === 'ArrowLeft') {
			e.preventDefault();
			handleBack();
		} else if (e.altKey && e.key === 'ArrowRight') {
			e.preventDefault();
			handleForward();
		} else if (e.key === 'F5') {
			e.preventDefault();
			handleRefresh();
		} else if (e.key === 'Escape' && isLoading) {
			e.preventDefault();
			handleStop();
		} else if (e.ctrlKey && e.key === 'd') {
			e.preventDefault();
			addBookmark();
		}
	}
</script>

<svelte:window onkeydown={handleWindowKeyDown} />

<div class="ie-browser" onclick={closeMenus}>
	<!-- Menu Bar -->
	<div class="ie-menubar">
		<button type="button" class="ie-menu-item" class:active={activeMenu === 'file'} onclick={(e) => { e.stopPropagation(); handleMenuClick('file'); }}>
			<span class="ie-menu-text"><u>F</u>ile</span>
		</button>
		<button type="button" class="ie-menu-item" class:active={activeMenu === 'edit'} onclick={(e) => { e.stopPropagation(); handleMenuClick('edit'); }}>
			<span class="ie-menu-text"><u>E</u>dit</span>
		</button>
		<button type="button" class="ie-menu-item" class:active={activeMenu === 'view'} onclick={(e) => { e.stopPropagation(); handleMenuClick('view'); }}>
			<span class="ie-menu-text"><u>V</u>iew</span>
		</button>
		<button type="button" class="ie-menu-item" class:active={activeMenu === 'favorites'} onclick={(e) => { e.stopPropagation(); handleMenuClick('favorites'); }}>
			<span class="ie-menu-text">F<u>a</u>vorites</span>
		</button>
		<button type="button" class="ie-menu-item" class:active={activeMenu === 'tools'} onclick={(e) => { e.stopPropagation(); handleMenuClick('tools'); }}>
			<span class="ie-menu-text"><u>T</u>ools</span>
		</button>
		<button type="button" class="ie-menu-item" class:active={activeMenu === 'help'} onclick={(e) => { e.stopPropagation(); handleMenuClick('help'); }}>
			<span class="ie-menu-text"><u>H</u>elp</span>
		</button>

		<!-- Dropdown Menus -->
		{#if activeMenu === 'file'}
			<div class="ie-dropdown" style="left: 0px;" onclick={(e) => e.stopPropagation()}>
				<div class="ie-menu-dropdown-item disabled">New</div>
				<div class="ie-menu-dropdown-item disabled">Open...</div>
				<div class="ie-menu-dropdown-separator"></div>
				<div class="ie-menu-dropdown-item disabled">Save</div>
				<div class="ie-menu-dropdown-item disabled">Save As...</div>
			</div>
		{/if}

		{#if activeMenu === 'edit'}
			<div class="ie-dropdown" style="left: 31px;" onclick={(e) => e.stopPropagation()}>
				<div class="ie-menu-dropdown-item disabled">Cut</div>
				<div class="ie-menu-dropdown-item disabled">Copy</div>
				<div class="ie-menu-dropdown-item disabled">Paste</div>
				<div class="ie-menu-dropdown-separator"></div>
				<div class="ie-menu-dropdown-item disabled">Select All</div>
			</div>
		{/if}

		{#if activeMenu === 'view'}
			<div class="ie-dropdown" style="left: 67px;" onclick={(e) => e.stopPropagation()}>
				<div class="ie-menu-dropdown-item disabled">Toolbars</div>
				<div class="ie-menu-dropdown-item disabled">Status Bar</div>
				<div class="ie-menu-dropdown-separator"></div>
				<div class="ie-menu-dropdown-item" onclick={handleStop}>Stop</div>
				<div class="ie-menu-dropdown-item" onclick={handleRefresh}>Refresh</div>
				<div class="ie-menu-dropdown-separator"></div>
				<div class="ie-menu-dropdown-item disabled">Source</div>
				<div class="ie-menu-dropdown-item disabled">Full Screen</div>
			</div>
		{/if}

		{#if activeMenu === 'favorites'}
			<div class="ie-dropdown" style="left: 107px;" onclick={(e) => e.stopPropagation()}>
				<div class="ie-menu-dropdown-item" onclick={addBookmark}>Add to Favorites...</div>
				<div class="ie-menu-dropdown-separator"></div>
				{#if bookmarks.length > 0}
					{#each bookmarks as bookmark}
						<div class="ie-menu-dropdown-item" onclick={() => navigateToBookmark(bookmark.url)}>
							{bookmark.title}
						</div>
					{/each}
				{:else}
					<div class="ie-menu-dropdown-item disabled">(Empty)</div>
				{/if}
			</div>
		{/if}

		{#if activeMenu === 'tools'}
			<div class="ie-dropdown" style="left: 180px;" onclick={(e) => e.stopPropagation()}>
				<div class="ie-menu-dropdown-item disabled">Mail and News</div>
				<div class="ie-menu-dropdown-separator"></div>
				<div class="ie-menu-dropdown-item disabled">Internet Options...</div>
			</div>
		{/if}

		{#if activeMenu === 'help'}
			<div class="ie-dropdown" style="left: 229px;" onclick={(e) => e.stopPropagation()}>
				<div class="ie-menu-dropdown-item disabled">Contents and Index</div>
				<div class="ie-menu-dropdown-separator"></div>
				<div class="ie-menu-dropdown-item disabled">About Internet Explorer</div>
			</div>
		{/if}
	</div>

	<!-- Standard Buttons Toolbar -->
	<div class="ie-toolbar">
		<button type="button" class="ie-toolbar-btn" disabled={!canGoBack} onclick={handleBack} title="Back (Alt+Left Arrow)">
			<span class="ie-btn-icon">◄</span>
		</button>
		<button type="button" class="ie-toolbar-btn" disabled={!canGoForward} onclick={handleForward} title="Forward (Alt+Right Arrow)">
			<span class="ie-btn-icon">►</span>
		</button>
		<button type="button" class="ie-toolbar-btn" disabled={!isLoading} onclick={handleStop} title="Stop (Esc)">
			<span class="ie-btn-icon">■</span>
		</button>
		<button type="button" class="ie-toolbar-btn" onclick={handleRefresh} title="Refresh (F5)">
			<i class="icon icon-ui-toolbar-search ie-toolbar-icon"></i>
		</button>
		<button type="button" class="ie-toolbar-btn" onclick={handleHome} title="Home">
			<i class="icon icon-ui-toolbar-homepage ie-toolbar-icon"></i>
		</button>

		<div class="ie-toolbar-separator"></div>

		<button type="button" class="ie-toolbar-btn-text" disabled title="Search">
			<i class="icon icon-ui-toolbar-search ie-toolbar-icon"></i>
			<span class="ie-btn-text">Search</span>
		</button>
		<button type="button" class="ie-toolbar-btn-text" onclick={toggleFavorites} title="Favorites">
			<i class="icon icon-ui-toolbar-favorites ie-toolbar-icon"></i>
			<span class="ie-btn-text">Favorites</span>
		</button>
		<button type="button" class="ie-toolbar-btn-text" disabled title="History">
			<i class="icon icon-ui-toolbar-history ie-toolbar-icon"></i>
			<span class="ie-btn-text">History</span>
		</button>
	</div>

	<!-- Address Bar -->
	<div class="ie-addressbar">
		<span class="ie-address-label">Address</span>
		<div class="ie-address-combo">
			<button type="button" class="ie-address-dropdown" title="Recent pages">
				<span class="ie-dropdown-arrow">▼</span>
			</button>
			<div class="ie-address-input-wrapper">
				<span class="ie-address-icon">📄</span>
				<input
					id="address-{windowId}"
					type="text"
					class="ie-address-input"
					bind:value={addressBarUrl}
					onkeydown={handleKeyDown}
					placeholder=""
				/>
			</div>
		</div>
		<button type="button" class="ie-go-btn" onclick={handleGo}>Go</button>
	</div>

	<!-- Links Bar -->
	<div class="ie-linksbar">
		<span class="ie-links-label">Links</span>
		<button type="button" class="ie-links-dropdown">▼</button>
		<button type="button" class="ie-link-btn" disabled>Best of the Web</button>
		<button type="button" class="ie-link-btn" disabled>Channel Guide</button>
		<button type="button" class="ie-link-btn" disabled>Customize Links</button>
	</div>

	<!-- Favorites Panel (if shown) -->
	{#if showFavorites}
		<div class="ie-favorites-panel">
			<div class="ie-favorites-header">
				<strong>Favorites</strong>
				<button type="button" class="ie-favorites-close" onclick={toggleFavorites}>×</button>
			</div>
			<div class="ie-favorites-list">
				{#if bookmarks.length === 0}
					<div class="ie-favorites-empty">No favorites</div>
				{:else}
					{#each bookmarks as bookmark}
						<div class="ie-favorite-item">
							<button type="button" class="ie-favorite-link" onclick={() => navigateToBookmark(bookmark.url)}>
								<i class="icon icon-ui-toolbar-favorites ie-favorite-icon"></i>
								<span>{bookmark.title}</span>
							</button>
							<button type="button" class="ie-favorite-delete" onclick={() => removeBookmark(bookmark.id)}>×</button>
						</div>
					{/each}
				{/if}
			</div>
		</div>
	{/if}

	<!-- Content Area -->
	<div class="ie-content">
		{#if loadError}
			<div class="ie-error">
				<h2>The page cannot be displayed</h2>
				<p>The page you are looking for is currently unavailable. The Web site might be experiencing technical difficulties, or you may need to adjust your browser settings.</p>
				<hr />
				<p><strong>Please try the following:</strong></p>
				<ul>
					<li>Click the <strong>Refresh</strong> button, or try again later.</li>
					<li>If you typed the page address in the Address bar, make sure that it is spelled correctly.</li>
					<li>Many sites (Google, Facebook, etc.) block iframe embedding for security reasons.</li>
				</ul>
				<p>HTTP 403 - Forbidden or X-Frame-Options blocking</p>
			</div>
		{:else}
			<iframe
				bind:this={iframeElement}
				src={currentUrl}
				class="ie-iframe"
				title="Browser Content"
				sandbox="allow-scripts allow-forms allow-popups allow-popups-to-escape-sandbox"
				onload={handleIframeLoad}
				onerror={handleIframeError}
			></iframe>
		{/if}
	</div>

	<!-- Status Bar -->
	<div class="ie-statusbar">
		<div class="ie-status-text">{statusText}</div>
		<div class="ie-status-zone">
			<span class="ie-zone-icon">🌐</span>
			<span>My Computer</span>
		</div>
	</div>
</div>

