<!--
  Windows 98 F1 Help System - Status Bar Component
  
  This component displays the status information at the bottom of the help system,
  including current topic information, progress indicators, and system status.
  
  @fileoverview Status bar component for help system
-->

<script lang="ts">
  import type { HelpTopic, HelpSystemState } from '../types.js';

  // Props
  let { 
    currentTopic = null,
    systemState,
    isLoading = false,
    progress = 0,
    message = ''
  }: {
    currentTopic?: HelpTopic | null;
    systemState?: HelpSystemState;
    isLoading?: boolean;
    progress?: number;
    message?: string;
  } = $props();

  // Computed values
  const statusText = $derived(currentTopic ? currentTopic.title : 'Ready');
  const progressText = $derived(progress > 0 ? `${Math.round(progress)}%` : '');
  const systemStatus = $derived(systemState?.isOnline ? 'Online' : 'Offline');
</script>

<div class="status-bar win98-status-bar">
  <div class="status-left">
    <span class="status-text">{statusText}</span>
    {#if message}
      <span class="status-message">{message}</span>
    {/if}
  </div>
  
  <div class="status-center">
    {#if isLoading}
      <div class="status-progress">
        <div class="progress-bar">
          <div class="progress-fill" style="width: {progress}%"></div>
        </div>
        {#if progressText}
          <span class="progress-text">{progressText}</span>
        {/if}
      </div>
    {/if}
  </div>
  
  <div class="status-right">
    <span class="status-system">{systemStatus}</span>
    {#if currentTopic}
      <span class="status-topic-id">Topic: {currentTopic.id}</span>
    {/if}
  </div>
</div>

<style>
  .status-bar {
    display: flex;
    align-items: center;
    justify-content: space-between;
    height: 22px;
    padding: 0 8px;
    background: #c0c0c0;
    border-top: 1px solid #808080;
    font-family: 'MS Sans Serif', sans-serif;
    font-size: 11px;
    color: #000000;
    user-select: none;
  }

  .status-left {
    display: flex;
    align-items: center;
    gap: 8px;
  }

  .status-center {
    display: flex;
    align-items: center;
    justify-content: center;
    flex: 1;
    max-width: 200px;
  }

  .status-right {
    display: flex;
    align-items: center;
    gap: 8px;
  }

  .status-text {
    font-weight: normal;
    color: #000000;
  }

  .status-message {
    color: #000080;
    font-style: italic;
  }

  .status-progress {
    display: flex;
    align-items: center;
    gap: 4px;
  }

  .progress-bar {
    width: 100px;
    height: 12px;
    background: #ffffff;
    border: 1px inset #c0c0c0;
    position: relative;
    overflow: hidden;
  }

  .progress-fill {
    height: 100%;
    background: linear-gradient(to bottom, #0080ff, #004080);
    transition: width 0.3s ease;
  }

  .progress-text {
    font-size: 10px;
    color: #000000;
    min-width: 30px;
    text-align: center;
  }

  .status-system {
    color: #008000;
    font-weight: bold;
  }

  .status-topic-id {
    color: #808080;
    font-size: 10px;
  }

  /* Windows 98 specific styling */
  .win98-status-bar {
    background: linear-gradient(to bottom, #c0c0c0, #a0a0a0);
    border-top: 1px solid #808080;
    box-shadow: inset 0 1px 0 #ffffff;
  }

  .win98-status-bar .progress-bar {
    background: #ffffff;
    border: 1px inset #c0c0c0;
    box-shadow: inset 1px 1px 2px #808080;
  }

  .win98-status-bar .progress-fill {
    background: linear-gradient(to bottom, #0080ff, #004080);
    box-shadow: inset 0 1px 0 #40a0ff;
  }
</style>
