<script lang="ts">
  import { createEventDispatcher } from 'svelte';
  import type { HelpSystemManager, HelpTopic } from '../types.js';
  import Scrollbar from '../../components/controls/Scrollbar.svelte';

  // Props
  let {
    helpSystem,
    currentTopic = $bindable(null)
  }: {
    helpSystem: HelpSystemManager;
    currentTopic?: HelpTopic | null;
  } = $props();

  // Event dispatcher
  const dispatch = createEventDispatcher();

  // State
  let searchQuery = $state('');
  let searchResults: HelpTopic[] = $state([]);
  let isSearching = $state(false);
  let searchError: string | null = $state(null);
  let expanded = $state(true);

  // Functions
  async function performSearch() {
    if (!searchQuery.trim()) {
      searchResults = [];
      return;
    }

    isSearching = true;
    searchError = null;

    try {
      searchResults = await helpSystem.searchEngine.search(searchQuery.trim());
    } catch (error) {
      searchError = error instanceof Error ? error.message : 'Search failed';
      searchResults = [];
    } finally {
      isSearching = false;
    }
  }

  function handleSearchInput() {
    // Debounce search
    clearTimeout(searchTimeout);
    searchTimeout = setTimeout(performSearch, 300);
  }

  function handleTopicSelect(topicId: string) {
    dispatch('topic-select', topicId);
  }

  function toggleExpanded() {
    expanded = !expanded;
  }

  let searchTimeout: NodeJS.Timeout;
</script>

<div class="search-panel win98-panel">
  <div class="panel-header" onclick={toggleExpanded}>
    <div class="panel-title">
      <span class="panel-icon">🔍</span>
      <span class="panel-label">Search</span>
    </div>
    <div class="panel-controls">
      <span class="expand-icon" class:expanded={expanded}>▼</span>
    </div>
  </div>

  {#if expanded}
    <div class="panel-content">
      <!-- Search Input -->
      <div class="search-input-container">
        <input
          type="text"
          class="search-input win98-input"
          placeholder="Search help topics..."
          bind:value={searchQuery}
          oninput={handleSearchInput}
          onkeydown={(e) => e.key === 'Enter' && performSearch()}
        />
        <button 
          class="search-button win98-button"
          onclick={performSearch}
          disabled={isSearching}
        >
          {isSearching ? '⏳' : '🔍'}
        </button>
      </div>

      <!-- Search Results -->
      <div class="search-results">
        {#if searchError}
          <div class="search-error">
            <div class="error-icon">⚠️</div>
            <div class="error-text">{searchError}</div>
          </div>
        {:else if searchResults.length > 0}
          <Scrollbar>
            <div class="results-list">
              {#each searchResults as result (result.id)}
                <div 
                  class="result-item"
                  class:current={currentTopic?.id === result.id}
                  onclick={() => handleTopicSelect(result.id)}
                >
                  <div class="result-title">{result.title}</div>
                  {#if result.description}
                    <div class="result-description">{result.description}</div>
                  {/if}
                </div>
              {/each}
            </div>
          </Scrollbar>
        {:else if searchQuery.trim()}
          <div class="no-results">
            <div class="no-results-icon">🔍</div>
            <div class="no-results-text">No results found for "{searchQuery}"</div>
          </div>
        {:else}
          <div class="search-prompt">
            <div class="prompt-icon">💡</div>
            <div class="prompt-text">Enter a search term to find help topics</div>
          </div>
        {/if}
      </div>
    </div>
  {/if}
</div>

