<script lang="ts">
	import { onMount, onDestroy } from 'svelte';

	interface Props {
		orientation?: 'vertical' | 'horizontal' | 'both';
		scrollLineAmount?: number;
		scrollPageAmount?: number;
		children?: import('svelte').Snippet;
	}

	let { 
		orientation = 'vertical',
		scrollLineAmount = 40, // pixels to scroll per line (arrow button click)
		scrollPageAmount = 200, // pixels to scroll per page (track click)
		children
	}: Props = $props();

	// Refs
	let wrapperEl: HTMLDivElement;
	let contentEl: HTMLDivElement;
	let verticalThumbEl: HTMLDivElement | null = $state(null);
	let horizontalThumbEl: HTMLDivElement | null = $state(null);

	// State
	let showVertical = $state(false);
	let showHorizontal = $state(false);
	let verticalThumbHeight = $state(0);
	let verticalThumbTop = $state(0);
	let horizontalThumbWidth = $state(0);
	let horizontalThumbLeft = $state(0);
	let isDraggingVertical = $state(false);
	let isDraggingHorizontal = $state(false);
	let dragStartY = $state(0);
	let dragStartX = $state(0);
	let dragStartScrollTop = $state(0);
	let dragStartScrollLeft = $state(0);

	// Constants
	const SCROLLBAR_SIZE = 16;
	const BUTTON_SIZE = 16;
	const MIN_THUMB_SIZE = 24;

	// Update scrollbar visibility and thumb sizes/positions
	function updateScrollbars() {
		if (!contentEl) return;

		const { scrollHeight, clientHeight, scrollWidth, clientWidth, scrollTop, scrollLeft } =
			contentEl;

		// Vertical scrollbar
		if (orientation === 'vertical' || orientation === 'both') {
			showVertical = scrollHeight > clientHeight;
			if (showVertical) {
				const trackHeight = clientHeight - BUTTON_SIZE * 2;
				const thumbRatio = clientHeight / scrollHeight;
				verticalThumbHeight = Math.max(trackHeight * thumbRatio, MIN_THUMB_SIZE);
				const maxThumbTop = trackHeight - verticalThumbHeight;
				const scrollRatio = scrollTop / (scrollHeight - clientHeight);
				verticalThumbTop = BUTTON_SIZE + scrollRatio * maxThumbTop;
			}
		}

		// Horizontal scrollbar
		if (orientation === 'horizontal' || orientation === 'both') {
			showHorizontal = scrollWidth > clientWidth;
			if (showHorizontal) {
				const trackWidth = clientWidth - BUTTON_SIZE * 2;
				const thumbRatio = clientWidth / scrollWidth;
				horizontalThumbWidth = Math.max(trackWidth * thumbRatio, MIN_THUMB_SIZE);
				const maxThumbLeft = trackWidth - horizontalThumbWidth;
				const scrollRatio = scrollLeft / (scrollWidth - clientWidth);
				horizontalThumbLeft = BUTTON_SIZE + scrollRatio * maxThumbLeft;
			}
		}
	}

	// Scroll handlers
	function handleScroll() {
		updateScrollbars();
	}

	// Arrow button click handlers
	function scrollUp() {
		if (contentEl) {
			contentEl.scrollTop -= scrollLineAmount;
		}
	}

	function scrollDown() {
		if (contentEl) {
			contentEl.scrollTop += scrollLineAmount;
		}
	}

	function scrollLeft() {
		if (contentEl) {
			contentEl.scrollLeft -= scrollLineAmount;
		}
	}

	function scrollRight() {
		if (contentEl) {
			contentEl.scrollLeft += scrollLineAmount;
		}
	}

	// Track click handlers
	function handleVerticalTrackClick(e: MouseEvent) {
		if (!contentEl || !verticalThumbEl) return;
		const target = e.target as HTMLElement;
		if (target.classList.contains('win98-scrollbar-thumb')) return;

		const trackRect = target.getBoundingClientRect();
		const clickY = e.clientY - trackRect.top;
		const thumbCenter = verticalThumbTop - BUTTON_SIZE + verticalThumbHeight / 2;

		if (clickY < thumbCenter) {
			contentEl.scrollTop -= scrollPageAmount;
		} else {
			contentEl.scrollTop += scrollPageAmount;
		}
	}

	function handleHorizontalTrackClick(e: MouseEvent) {
		if (!contentEl || !horizontalThumbEl) return;
		const target = e.target as HTMLElement;
		if (target.classList.contains('win98-scrollbar-thumb')) return;

		const trackRect = target.getBoundingClientRect();
		const clickX = e.clientX - trackRect.left;
		const thumbCenter = horizontalThumbLeft - BUTTON_SIZE + horizontalThumbWidth / 2;

		if (clickX < thumbCenter) {
			contentEl.scrollLeft -= scrollPageAmount;
		} else {
			contentEl.scrollLeft += scrollPageAmount;
		}
	}

	// Thumb drag handlers
	function handleVerticalThumbMouseDown(e: MouseEvent) {
		if (!contentEl) return;
		e.preventDefault();
		isDraggingVertical = true;
		dragStartY = e.clientY;
		dragStartScrollTop = contentEl.scrollTop;
		document.addEventListener('mousemove', handleMouseMove);
		document.addEventListener('mouseup', handleMouseUp);
	}

	function handleHorizontalThumbMouseDown(e: MouseEvent) {
		if (!contentEl) return;
		e.preventDefault();
		isDraggingHorizontal = true;
		dragStartX = e.clientX;
		dragStartScrollLeft = contentEl.scrollLeft;
		document.addEventListener('mousemove', handleMouseMove);
		document.addEventListener('mouseup', handleMouseUp);
	}

	function handleMouseMove(e: MouseEvent) {
		if (!contentEl) return;

		if (isDraggingVertical) {
			const deltaY = e.clientY - dragStartY;
			const { scrollHeight, clientHeight } = contentEl;
			const trackHeight = clientHeight - BUTTON_SIZE * 2;
			const maxThumbTop = trackHeight - verticalThumbHeight;
			const scrollRatio = deltaY / maxThumbTop;
			const scrollDelta = scrollRatio * (scrollHeight - clientHeight);
			contentEl.scrollTop = dragStartScrollTop + scrollDelta;
		}

		if (isDraggingHorizontal) {
			const deltaX = e.clientX - dragStartX;
			const { scrollWidth, clientWidth } = contentEl;
			const trackWidth = clientWidth - BUTTON_SIZE * 2;
			const maxThumbLeft = trackWidth - horizontalThumbWidth;
			const scrollRatio = deltaX / maxThumbLeft;
			const scrollDelta = scrollRatio * (scrollWidth - clientWidth);
			contentEl.scrollLeft = dragStartScrollLeft + scrollDelta;
		}
	}

	function handleMouseUp() {
		isDraggingVertical = false;
		isDraggingHorizontal = false;
		document.removeEventListener('mousemove', handleMouseMove);
		document.removeEventListener('mouseup', handleMouseUp);
	}

	// Wheel event handler
	function handleWheel(e: WheelEvent) {
		// Let the browser handle it naturally
		updateScrollbars();
	}

	// Resize observer
	let resizeObserver: ResizeObserver;

	onMount(() => {
		updateScrollbars();

		// Watch for content size changes
		resizeObserver = new ResizeObserver(() => {
			updateScrollbars();
		});

		if (contentEl) {
			resizeObserver.observe(contentEl);
			// Also observe all children for dynamic content
			Array.from(contentEl.children).forEach((child) => {
				resizeObserver.observe(child);
			});
		}
	});

	onDestroy(() => {
		if (resizeObserver) {
			resizeObserver.disconnect();
		}
		document.removeEventListener('mousemove', handleMouseMove);
		document.removeEventListener('mouseup', handleMouseUp);
	});

	// Export functions for programmatic control
	export function scrollTo(x: number, y: number) {
		if (contentEl) {
			contentEl.scrollTo(x, y);
		}
	}

	export function scrollToTop() {
		if (contentEl) {
			contentEl.scrollTop = 0;
		}
	}

	export function scrollToBottom() {
		if (contentEl) {
			contentEl.scrollTop = contentEl.scrollHeight;
		}
	}

	export function getScrollPosition() {
		if (contentEl) {
			return {
				scrollTop: contentEl.scrollTop,
				scrollLeft: contentEl.scrollLeft,
				scrollHeight: contentEl.scrollHeight,
				scrollWidth: contentEl.scrollWidth,
				clientHeight: contentEl.clientHeight,
				clientWidth: contentEl.clientWidth
			};
		}
		return null;
	}
</script>

<div class="win98-scrollbar-wrapper" bind:this={wrapperEl}>
	<div
		class="win98-scrollbar-content"
		bind:this={contentEl}
		onscroll={handleScroll}
		onwheel={handleWheel}
		role="region"
		tabindex="-1"
	>
		{@render children?.()}
	</div>

	{#if showVertical}
		<div class="win98-scrollbar-vertical" role="scrollbar" aria-orientation="vertical" aria-controls="scrollbar-content" aria-valuenow={contentEl?.scrollTop || 0}>
			<button
				class="win98-scrollbar-button"
				onclick={scrollUp}
				aria-label="Scroll up"
				type="button"
			>
				<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 16 16">
					<polygon points="8,5 12,11 4,11" />
				</svg>
			</button>

			<div class="win98-scrollbar-track" onclick={handleVerticalTrackClick} role="presentation">
				<div
					class="win98-scrollbar-thumb"
					class:dragging={isDraggingVertical}
					bind:this={verticalThumbEl}
					onmousedown={handleVerticalThumbMouseDown}
					style="height: {verticalThumbHeight}px; top: {verticalThumbTop - BUTTON_SIZE}px;"
					role="presentation"
				></div>
			</div>

			<button
				class="win98-scrollbar-button"
				onclick={scrollDown}
				aria-label="Scroll down"
				type="button"
			>
				<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 16 16">
					<polygon points="8,11 12,5 4,5" />
				</svg>
			</button>
		</div>
	{/if}

	{#if showHorizontal}
		<div class="win98-scrollbar-horizontal" role="scrollbar" aria-orientation="horizontal" aria-controls="scrollbar-content" aria-valuenow={contentEl?.scrollLeft || 0}>
			<button
				class="win98-scrollbar-button"
				onclick={scrollLeft}
				aria-label="Scroll left"
				type="button"
			>
				<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 16 16">
					<polygon points="5,8 11,12 11,4" />
				</svg>
			</button>

			<div
				class="win98-scrollbar-track"
				onclick={handleHorizontalTrackClick}
				role="presentation"
			>
				<div
					class="win98-scrollbar-thumb"
					class:dragging={isDraggingHorizontal}
					bind:this={horizontalThumbEl}
					onmousedown={handleHorizontalThumbMouseDown}
					style="width: {horizontalThumbWidth}px; left: {horizontalThumbLeft - BUTTON_SIZE}px;"
					role="presentation"
				></div>
			</div>

			<button
				class="win98-scrollbar-button"
				onclick={scrollRight}
				aria-label="Scroll right"
				type="button"
			>
				<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 16 16">
					<polygon points="11,8 5,12 5,4" />
				</svg>
			</button>
		</div>
	{/if}

	{#if showVertical && showHorizontal}
		<div class="win98-scrollbar-corner"></div>
	{/if}
</div>

